-- ============================================================================
-- ALL_COMBINED.sql — full DDL/DML record of the SUPPLY_CHAIN database.
-- Auto-generated by concatenating sql/*.sql in the build order defined by
-- scripts/rebuild.mjs (the FILES array is the authoritative source of order).
-- Regenerate rather than hand-edit if the source files change.
-- ============================================================================


-- ============================================================================
-- FILE: 00a_foundation.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 00a — Foundation: database, schemas, roles, warehouse access.
--
-- Run first. Everything else assumes the schemas and roles below exist.
--
-- WHY THE OBJECT GRANTS ARE NOT HERE. Only role creation and container-level
-- access (database, schema, warehouse) live in this file. Grants on tables and
-- semantic views are issued at the end of 00e and 00f, where those objects are
-- created. Future grants would be the tidier option, but they are silently
-- one-directional: a future grant added here does nothing for an object that a
-- later CREATE OR REPLACE re-creates under a different owner, and debugging
-- that costs more than repeating a GRANT next to the CREATE.
--
-- WHY EIGHT ROLES. Five are personas the application switches into per request
-- (lib/persona.ts issues USE ROLE, then USE SECONDARY ROLES NONE so that
-- inherited privileges cannot widen the row scope). Three are owner roles that
-- appear only as METRIC_DEFINITION.owner_role and TARGET_SOURCE text — they name
-- who is accountable for a metric's definition and target. They are real roles
-- rather than free text so that accountability is checkable, not decorative.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;

CREATE DATABASE IF NOT EXISTS SUPPLY_CHAIN
  COMMENT = 'Supply Chain Ontology. Governed conversational analytics: every number in the app and in the conversational layer resolves to a metric defined in SEMANTIC, registered in GOVERNANCE, and reconcilable to an atomic fact in CANONICAL.';

USE DATABASE SUPPLY_CHAIN;

CREATE SCHEMA IF NOT EXISTS RAW
  COMMENT = 'Landing zone. Synthetic source systems, generated by 00b/00c. Nothing outside CANONICAL reads these tables and no application role is granted on them.';

CREATE SCHEMA IF NOT EXISTS CANONICAL
  COMMENT = 'Atomic-grain conformed facts. One row per business event. These are the reconciliation target: every governed metric carries the SQL that computes it from exactly one of these tables, and the drift test asserts the semantic views agree with that SQL.';

CREATE SCHEMA IF NOT EXISTS SEMANTIC
  COMMENT = 'Semantic views. The only surface the application and Cortex Analyst query. A metric exists here once and is referenced everywhere, so the UI and the conversational layer cannot disagree about what a number means.';

CREATE SCHEMA IF NOT EXISTS GOVERNANCE
  COMMENT = 'Metric registry, ontology catalogue, drift control, persona scoping. Admin-owned: EXCEPTION_WHERE and ORDER_BY from METRIC_EXCEPTION_RULE are interpolated into SQL by the drill-down route, which is safe only because no application role can write here.';

CREATE SCHEMA IF NOT EXISTS UTIL
  COMMENT = 'Reserved for synthetic-data generation helpers. Deliberately empty: the generators in 00c are self-contained and seeded inline, so that no business number depends on a value stored here.';

CREATE SCHEMA IF NOT EXISTS APPS
  COMMENT = 'Holds the deployed APPLICATION SERVICE (see app.yml).';

-- ---------------------------------------------------------------------------
-- Persona roles. Assumed per request by the application.
-- ---------------------------------------------------------------------------

CREATE ROLE IF NOT EXISTS SC_PLANNER
  COMMENT = 'Demand and inventory planning. Sees forecast, inventory and fulfilment.';
CREATE ROLE IF NOT EXISTS SC_PROCUREMENT
  COMMENT = 'Direct materials buying. Sees supplier delivery, fill and purchase price variance.';
CREATE ROLE IF NOT EXISTS SC_LOGISTICS
  COMMENT = 'Outbound transport and cost to serve. Sees fulfilment and landed cost, all regions.';
CREATE ROLE IF NOT EXISTS SC_LOGISTICS_EU
  COMMENT = 'Regional variant of SC_LOGISTICS, row-scoped to EU shipments by a row access policy. Exists to demonstrate that one metric definition can serve different row scopes without being redefined.';
CREATE ROLE IF NOT EXISTS SC_ONTOLOGY_STEWARD
  COMMENT = 'Owns the semantic layer. The only persona that sees every view, the drift control and the consistency evidence.';

-- ---------------------------------------------------------------------------
-- Owner roles. Named as accountable parties in the metric registry.
-- ---------------------------------------------------------------------------

CREATE ROLE IF NOT EXISTS SC_PROCUREMENT_ANALYST
  COMMENT = 'Accountable for the definition and target of the supplier metrics.';
CREATE ROLE IF NOT EXISTS SC_LOGISTICS_ANALYST
  COMMENT = 'Accountable for the definition and target of the fulfilment and landed-cost metrics.';
CREATE ROLE IF NOT EXISTS SC_PLANNING_ANALYST
  COMMENT = 'Accountable for the definition and target of the inventory and demand metrics.';

-- ---------------------------------------------------------------------------
-- Container access and warehouse usage.
--
-- RAW is deliberately absent: a persona that could read RAW could compute a
-- metric by hand and get a different answer, which is the failure this project
-- exists to prevent. Personas reach atomic rows only through CANONICAL, and only
-- via the drill-down, which is constrained by METRIC_EXCEPTION_RULE.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;

-- MONTY needs to be able to assume every persona to exercise the app locally.
GRANT ROLE SC_PLANNER            TO USER MONTY;
GRANT ROLE SC_PROCUREMENT        TO USER MONTY;
GRANT ROLE SC_LOGISTICS          TO USER MONTY;
GRANT ROLE SC_LOGISTICS_EU       TO USER MONTY;
GRANT ROLE SC_ONTOLOGY_STEWARD   TO USER MONTY;
GRANT ROLE SC_PROCUREMENT_ANALYST TO USER MONTY;
GRANT ROLE SC_LOGISTICS_ANALYST  TO USER MONTY;
GRANT ROLE SC_PLANNING_ANALYST   TO USER MONTY;

GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_PLANNER;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_PROCUREMENT;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_LOGISTICS;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_PLANNER;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_PROCUREMENT;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_LOGISTICS;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON DATABASE SUPPLY_CHAIN TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_PLANNER;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_PROCUREMENT;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_LOGISTICS;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.SEMANTIC TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PLANNER;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PROCUREMENT;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_PLANNER;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_PROCUREMENT;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_LOGISTICS;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_ONTOLOGY_STEWARD;

-- The steward reads INFORMATION_SCHEMA.SEMANTIC_* through the ontology views.
GRANT USAGE ON SCHEMA SUPPLY_CHAIN.APPS TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 00b_raw_dimensions.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 00b — RAW conformed dimensions and reference data.
--
-- DETERMINISM. Nothing here uses RANDOM(). Every derived attribute is a function
-- of the row's sequence number via ABS(HASH(seq, 'salt')), so a rebuild produces
-- byte-identical dimensions. RANDOM() with a seed is reproducible only if row
-- order is, and row order under a parallel GENERATOR is not guaranteed — which
-- would mean supplier 41 changing region between rebuilds and every historical
-- metric value moving with it.
--
-- DATE_DIM COLUMN NAMES ARE A CONTRACT. 01_calendar_dimension.sql maps
-- CALENDAR.CAL_DATE, CAL_MONTH, CAL_PERIOD, CAL_QUARTER, CAL_YEAR and IS_WEEKDAY
-- onto date_key, month_start, period, fiscal_quarter, year_num and is_weekday
-- respectively. Renaming any of them breaks the splice silently: the semantic
-- view still compiles, and the failure surfaces later as an unresolved dimension
-- on every page that applies a reporting period.
--
-- The range is 2024-01-01..2026-12-31, wider on both sides than the transactional
-- data in 00c (2024-10-03..2026-11-25). A date dimension that stops at the last
-- fact row cannot express "no activity in this period", and IS_FUTURE needs dates
-- beyond today to be meaningful at all.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA RAW;

-- ---------------------------------------------------------------------------
-- DATE_DIM — the conformed time dimension.
--
-- FISCAL_QUARTER is calendar-aligned on purpose. A genuine 3M fiscal calendar
-- would be a guess, and a wrong fiscal boundary silently misstates every
-- quarter-grain number; calendar alignment is at least verifiably what it says.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE DATE_DIM (
  DATE_KEY        DATE     NOT NULL COMMENT 'Calendar day. Join key for every day-grain fact.',
  MONTH_START     DATE     NOT NULL COMMENT 'First day of the calendar month.',
  MONTH_END       DATE     NOT NULL COMMENT 'Last day of the calendar month.',
  PERIOD          STRING   NOT NULL COMMENT 'Month as a YYYY-MM label. The period key the application and the forecast both use.',
  FISCAL_QUARTER  STRING   NOT NULL COMMENT 'Fiscal quarter, calendar-aligned, as YYYY-Qn.',
  YEAR_NUM        NUMBER   NOT NULL COMMENT 'Calendar year.',
  MONTH_NUM       NUMBER   NOT NULL COMMENT 'Month number 1-12.',
  DAY_OF_WEEK     NUMBER   NOT NULL COMMENT 'ISO day of week, 1 = Monday.',
  IS_WEEKDAY      BOOLEAN  NOT NULL COMMENT 'TRUE for Monday-Friday.',
  IS_MONTH_END    BOOLEAN  NOT NULL COMMENT 'TRUE on the last day of the month. Inventory snapshots land only on these dates.',
  CONSTRAINT pk_date_dim PRIMARY KEY (DATE_KEY)
) COMMENT = 'Conformed calendar, 2024-01-01..2026-12-31. Deliberately wider than the fact data so that empty periods are expressible and IS_FUTURE is meaningful.';

INSERT INTO DATE_DIM
SELECT
  d                                                              AS date_key,
  DATE_TRUNC('MONTH', d)                                         AS month_start,
  LAST_DAY(d)                                                    AS month_end,
  TO_CHAR(d, 'YYYY-MM')                                          AS period,
  TO_CHAR(YEAR(d)) || '-Q' || TO_CHAR(QUARTER(d))                AS fiscal_quarter,
  YEAR(d)                                                        AS year_num,
  MONTH(d)                                                       AS month_num,
  DAYOFWEEKISO(d)                                                AS day_of_week,
  DAYOFWEEKISO(d) <= 5                                           AS is_weekday,
  d = LAST_DAY(d)                                                AS is_month_end
FROM (
  SELECT DATEADD('DAY', SEQ4(), DATE '2024-01-01') AS d
  FROM TABLE(GENERATOR(ROWCOUNT => 1096))
)
WHERE d <= DATE '2026-12-31';

-- ---------------------------------------------------------------------------
-- PART — 2,000 materials.
--
-- STANDARD_COST is the basis for purchase price variance, so it must be stable
-- per material across the whole history: PPV is only interpretable if the
-- standard it is measured against does not move. ABC_CLASS is skewed A/B/C
-- 15/30/55 rather than evenly, because an even split would make the class
-- useless as a segmentation on the inventory pages.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PART (
  MATERIAL_ID      STRING NOT NULL COMMENT 'Material number. Conformed key across purchasing, fulfilment, inventory and manufacturing.',
  MATERIAL_DESC    STRING NOT NULL COMMENT 'Human-readable description.',
  PRODUCT_FAMILY   STRING NOT NULL COMMENT 'Product family. The most-used analytical grouping in the application.',
  BUSINESS_SEGMENT STRING NOT NULL COMMENT 'Reporting segment the family rolls into.',
  ABC_CLASS        STRING NOT NULL COMMENT 'Inventory value classification: A is high-value low-volume, C the reverse.',
  STANDARD_COST    NUMBER(12,4) NOT NULL COMMENT 'Standard unit cost. Fixed for the life of the material so that purchase price variance is measured against an unchanging basis.',
  UOM              STRING NOT NULL COMMENT 'Unit of measure.',
  CONSTRAINT pk_part PRIMARY KEY (MATERIAL_ID)
) COMMENT = 'Material master. 2,000 materials across 8 product families.';

INSERT INTO PART
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 2000)))
SELECT
  'MAT-' || LPAD(TO_CHAR(i + 1), 6, '0')                          AS material_id,
  fam.name || ' Component ' || TO_CHAR(i + 1)                     AS material_desc,
  fam.name                                                        AS product_family,
  fam.segment                                                     AS business_segment,
  CASE WHEN ABS(HASH(i, 'abc')) % 100 < 15 THEN 'A'
       WHEN ABS(HASH(i, 'abc')) % 100 < 45 THEN 'B'
       ELSE 'C' END                                               AS abc_class,
  -- 1.50 .. 14.49, quantised to cents, averaging ~8.00.
  --
  -- The ceiling is set by the landed-cost metric, not by realism for its own
  -- sake. TOTAL_LANDED_COST is MATERIAL_COST + FREIGHT + DUTY + HANDLING, and
  -- MATERIAL_COST is standard cost times quantity, so mean standard cost is the
  -- dominant term in landed cost per unit. That metric has a governed target of
  -- $10 (03_targets.sql) and 05_exception_rules.sql flags shipments above $15 as
  -- "well above" it. A mean standard cost of, say, $90 would put every shipment
  -- an order of magnitude past the target, turning the whole red/amber/green
  -- layer and the exception drill-down into noise. ~$8 of material plus ~$2.40
  -- of freight, duty and handling lands the metric just over target, which is
  -- where the thresholds are actually exercised.
  ROUND(1.50 + (ABS(HASH(i, 'cost')) % 1300) / 100.0, 2)          AS standard_cost,
  CASE ABS(HASH(i, 'uom')) % 3 WHEN 0 THEN 'EA' WHEN 1 THEN 'CS' ELSE 'RL' END AS uom
FROM s
JOIN (
  SELECT * FROM VALUES
    (0, 'Abrasives',   'Safety & Industrial'),
    (1, 'Adhesives',   'Safety & Industrial'),
    (2, 'Tapes',       'Safety & Industrial'),
    (3, 'Films',       'Transportation & Electronics'),
    (4, 'Electronics', 'Transportation & Electronics'),
    (5, 'Filtration',  'Consumer'),
    (6, 'Medical',     'Health Care'),
    (7, 'Safety',      'Safety & Industrial')
  AS v(idx, name, segment)
) fam ON fam.idx = ABS(HASH(s.i, 'fam')) % 8;

-- ---------------------------------------------------------------------------
-- SUPPLIER — 300 suppliers.
--
-- SUPPLIER_REGION is the row-scope dimension on the inbound side and is weighted
-- rather than uniform (NA 40 / EU 30 / APAC 22 / LATAM 8), so that a regional
-- filter produces populations of visibly different size. Uniform regions make a
-- row-scoped persona indistinguishable from an unscoped one at a glance.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE SUPPLIER (
  SUPPLIER_ID     STRING NOT NULL COMMENT 'Vendor number.',
  SUPPLIER_NAME   STRING NOT NULL COMMENT 'Vendor name, shown in drill-down rows.',
  SUPPLIER_REGION STRING NOT NULL COMMENT 'Sourcing region: NA, EU, APAC or LATAM.',
  SUPPLIER_GROUP  STRING NOT NULL COMMENT 'Commodity group the vendor is managed under.',
  SUPPLIER_TIER   STRING NOT NULL COMMENT 'Strategic tier. TIER_1 vendors carry the majority of spend.',
  COUNTRY         STRING NOT NULL COMMENT 'Country of the shipping origin.',
  CONSTRAINT pk_supplier PRIMARY KEY (SUPPLIER_ID)
) COMMENT = 'Supplier master. 300 vendors, regionally weighted so that row-scoped personas see populations of different size.';

INSERT INTO SUPPLIER
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 300)))
SELECT
  'SUP-' || LPAD(TO_CHAR(i + 1), 5, '0')                          AS supplier_id,
  'Supplier ' || LPAD(TO_CHAR(i + 1), 4, '0') || ' ' ||
    CASE ABS(HASH(i, 'sfx')) % 5
      WHEN 0 THEN 'Industries' WHEN 1 THEN 'Materials' WHEN 2 THEN 'Group'
      WHEN 3 THEN 'Manufacturing' ELSE 'Technologies' END         AS supplier_name,
  r.region                                                        AS supplier_region,
  CASE ABS(HASH(i, 'grp')) % 6
    WHEN 0 THEN 'Resins' WHEN 1 THEN 'Minerals' WHEN 2 THEN 'Packaging'
    WHEN 3 THEN 'Electronics' WHEN 4 THEN 'Chemicals' ELSE 'Textiles' END AS supplier_group,
  CASE WHEN ABS(HASH(i, 'tier')) % 100 < 20 THEN 'TIER_1'
       WHEN ABS(HASH(i, 'tier')) % 100 < 55 THEN 'TIER_2'
       ELSE 'TIER_3' END                                          AS supplier_tier,
  r.country                                                       AS country
FROM s
JOIN (
  -- lo/hi are cumulative percentage bounds, so the weighting is explicit.
  SELECT * FROM VALUES
    ('NA',     0,  40, 'United States'),
    ('EU',    40,  70, 'Germany'),
    ('APAC',  70,  92, 'Japan'),
    ('LATAM', 92, 100, 'Brazil')
  AS v(region, lo, hi, country)
) r ON ABS(HASH(s.i, 'sreg')) % 100 >= r.lo AND ABS(HASH(s.i, 'sreg')) % 100 < r.hi;

-- ---------------------------------------------------------------------------
-- CUSTOMER — 1,200 ship-to customers.
--
-- CUSTOMER_REGION carries the same weighting as SUPPLIER_REGION. It is distinct
-- from the shipment's SHIP_REGION in 00c: the EU row access policy scopes on
-- SHIP_REGION, because where goods went is what a regional logistics owner is
-- accountable for, not where the account is registered.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE CUSTOMER (
  CUSTOMER_ID      STRING NOT NULL COMMENT 'Ship-to customer number.',
  CUSTOMER_NAME    STRING NOT NULL COMMENT 'Customer name.',
  CUSTOMER_REGION  STRING NOT NULL COMMENT 'Region the account is managed in.',
  CUSTOMER_SEGMENT STRING NOT NULL COMMENT 'Go-to-market segment.',
  CHANNEL          STRING NOT NULL COMMENT 'Route to market.',
  CONSTRAINT pk_customer PRIMARY KEY (CUSTOMER_ID)
) COMMENT = 'Customer master. 1,200 ship-to accounts.';

INSERT INTO CUSTOMER
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 1200)))
SELECT
  'CUST-' || LPAD(TO_CHAR(i + 1), 6, '0')                         AS customer_id,
  'Customer ' || LPAD(TO_CHAR(i + 1), 5, '0')                     AS customer_name,
  r.region                                                        AS customer_region,
  CASE ABS(HASH(i, 'seg')) % 4
    WHEN 0 THEN 'Enterprise' WHEN 1 THEN 'Mid-Market'
    WHEN 2 THEN 'Distributor' ELSE 'Retail' END                   AS customer_segment,
  CASE ABS(HASH(i, 'chan')) % 3
    WHEN 0 THEN 'Direct' WHEN 1 THEN 'Distribution' ELSE 'eCommerce' END AS channel
FROM s
JOIN (
  SELECT * FROM VALUES
    ('NA',     0,  40),
    ('EU',    40,  70),
    ('APAC',  70,  92),
    ('LATAM', 92, 100)
  AS v(region, lo, hi)
) r ON ABS(HASH(s.i, 'creg')) % 100 >= r.lo AND ABS(HASH(s.i, 'creg')) % 100 < r.hi;

-- ---------------------------------------------------------------------------
-- NODE — 24 distribution and plant locations.
--
-- Enumerated rather than generated. Node count is small and node region drives
-- the inventory row scope, so an explicit list is easier to verify by eye than a
-- hash-derived one, and 24 nodes against 2,000 materials is what produces the
-- ~137K inventory snapshot rows over 24 month-ends.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE NODE (
  NODE_ID     STRING NOT NULL COMMENT 'Plant or distribution centre code.',
  NODE_NAME   STRING NOT NULL COMMENT 'Location name, shown in inventory drill-down rows.',
  NODE_REGION STRING NOT NULL COMMENT 'Region the node serves.',
  NODE_TYPE   STRING NOT NULL COMMENT 'PLANT for manufacturing, DC for distribution.',
  CONSTRAINT pk_node PRIMARY KEY (NODE_ID)
) COMMENT = 'Network master. 24 nodes across 4 regions.';

INSERT INTO NODE
SELECT * FROM VALUES
  ('ND-01','Saint Paul DC','NA','DC'),      ('ND-02','Columbia Plant','NA','PLANT'),
  ('ND-03','Austin DC','NA','DC'),          ('ND-04','Brookings Plant','NA','PLANT'),
  ('ND-05','Chicago DC','NA','DC'),         ('ND-06','Ontario DC','NA','DC'),
  ('ND-07','Neuss DC','EU','DC'),           ('ND-08','Kamen Plant','EU','PLANT'),
  ('ND-09','Gorseinon Plant','EU','PLANT'), ('ND-10','Breda DC','EU','DC'),
  ('ND-11','Milan DC','EU','DC'),           ('ND-12','Lyon DC','EU','DC'),
  ('ND-13','Singapore DC','APAC','DC'),     ('ND-14','Suzhou Plant','APAC','PLANT'),
  ('ND-15','Yamagata Plant','APAC','PLANT'),('ND-16','Sydney DC','APAC','DC'),
  ('ND-17','Pune Plant','APAC','PLANT'),    ('ND-18','Seoul DC','APAC','DC'),
  ('ND-19','Sumare Plant','LATAM','PLANT'), ('ND-20','Itapetininga DC','LATAM','DC'),
  ('ND-21','Queretaro Plant','LATAM','PLANT'),('ND-22','Bogota DC','LATAM','DC'),
  ('ND-23','Santiago DC','LATAM','DC'),     ('ND-24','Buenos Aires DC','LATAM','DC')
AS v(node_id, node_name, node_region, node_type);

-- ---------------------------------------------------------------------------
-- CARRIER — 8 carriers.
--
-- ON_TIME_BIAS is the per-carrier deviation from the network's baseline on-time
-- probability, in percentage points. It exists so that carrier is a real
-- explanatory dimension: without it, "which carrier is hurting OTD" has no
-- answer in the data and the drill-down is decorative.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE CARRIER (
  CARRIER_ID    STRING NOT NULL COMMENT 'Carrier code.',
  CARRIER_NAME  STRING NOT NULL COMMENT 'Carrier name.',
  MODE          STRING NOT NULL COMMENT 'Transport mode.',
  ON_TIME_BIAS  NUMBER(4,1) NOT NULL COMMENT 'Deviation from baseline on-time probability, in percentage points. Makes carrier a genuine driver of OTD rather than noise.',
  COST_INDEX    NUMBER(5,3) NOT NULL COMMENT 'Multiplier on baseline freight cost per shipment.',
  CONSTRAINT pk_carrier PRIMARY KEY (CARRIER_ID)
) COMMENT = 'Carrier master. ON_TIME_BIAS and COST_INDEX make carrier an explanatory dimension for both service and cost.';

INSERT INTO CARRIER
SELECT * FROM VALUES
  ('CAR-01','Northwind Freight','ROAD',    4.0, 0.940),
  ('CAR-02','Meridian Logistics','ROAD',   1.5, 1.000),
  ('CAR-03','BlueLane Express','PARCEL',   5.5, 1.180),
  ('CAR-04','TransGlobal Ocean','OCEAN',  -7.0, 0.620),
  ('CAR-05','AeroCargo','AIR',             6.5, 1.850),
  ('CAR-06','Continental Haulage','ROAD', -3.5, 0.880),
  ('CAR-07','Pacific Star Lines','OCEAN', -5.0, 0.650),
  ('CAR-08','RegioTrans','ROAD',           0.5, 0.960)
AS v(carrier_id, carrier_name, mode, on_time_bias, cost_index);

-- ---------------------------------------------------------------------------
-- LANE — 96 origin/destination service combinations.
--
-- TRANSIT_TARGET_DAYS is what the promise date is derived from in 00c, so that a
-- late delivery is late relative to a stated commitment rather than to an
-- arbitrary constant.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE LANE (
  LANE_ID             STRING NOT NULL COMMENT 'Lane code.',
  ORIGIN_NODE         STRING NOT NULL COMMENT 'Shipping node.',
  DEST_REGION         STRING NOT NULL COMMENT 'Destination region. The shipment SHIP_REGION comes from here.',
  SERVICE_LEVEL       STRING NOT NULL COMMENT 'Committed service level.',
  TRANSIT_TARGET_DAYS NUMBER NOT NULL COMMENT 'Committed transit time. The promise date in 00c is derived from this, so lateness is measured against a real commitment.',
  CONSTRAINT pk_lane PRIMARY KEY (LANE_ID)
) COMMENT = 'Transport lanes. 96 origin/destination/service combinations.';

INSERT INTO LANE
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 96)))
SELECT
  'LANE-' || LPAD(TO_CHAR(s.i + 1), 4, '0')                       AS lane_id,
  n.node_id                                                       AS origin_node,
  d.region                                                        AS dest_region,
  sl.service_level                                                AS service_level,
  -- Cross-region moves take materially longer; same-region is short-haul.
  CASE WHEN n.node_region = d.region THEN sl.base_days
       ELSE sl.base_days + 8 END                                  AS transit_target_days
FROM s
JOIN NODE n ON n.node_id = 'ND-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'lnode')) % 24) + 1), 2, '0')
JOIN (
  SELECT * FROM VALUES ('NA',0),('EU',1),('APAC',2),('LATAM',3) AS v(region, idx)
) d ON d.idx = ABS(HASH(s.i, 'ldest')) % 4
JOIN (
  SELECT * FROM VALUES
    ('EXPRESS', 2, 0), ('STANDARD', 5, 1), ('ECONOMY', 9, 2)
  AS v(service_level, base_days, idx)
) sl ON sl.idx = ABS(HASH(s.i, 'lsvc')) % 3;


-- ============================================================================
-- FILE: 00c_raw_transactions.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 00c — RAW transactional sources, full scale.
--
-- Row counts, matching the documented production of this dataset:
--   PO_RECEIPT_LINE      420,000
--   SALES_ORDER_LINE   1,500,000
--   SHIPMENT_COST      1,480,500   (one per shipped order line; 1.3% of lines
--                                   never shipped, so the counts differ)
--   INVENTORY_POSITION   137,088   (5,712 material-node pairs x 24 month-ends)
--   PRODUCTION_ORDER     240,000
--   DEMAND_FORECAST       52,000   (2,000 materials x 26 periods)
--
-- ---------------------------------------------------------------------------
-- HOW THE DATE DISTRIBUTION IS BUILT, AND WHY IT IS NOT UNIFORM
--
-- The data must span 2024-10-03..2026-11-25 while roughly 2.8% of receipt and
-- shipment rows fall after today (2026-09-20), because 02_as_of_rule.sql records
-- the as-of rule that excludes them and scripts/probe-asof.mjs asserts the
-- effect is visible.
--
-- A uniform spread over that range would put 66 of 784 days in the future, or
-- 8.4% — three times too many, which would make several months look
-- catastrophically bad rather than simply incomplete. So the date is drawn from
-- one of two windows by an explicit 2.8% Bernoulli draw: the historical window
-- (718 days, to 2026-09-20) or the future window (66 days, beyond it). The
-- future rows are genuine open commitments: promised receipts and planned
-- deliveries that have not happened.
--
-- ---------------------------------------------------------------------------
-- HOW ON-TIME IS CONSTRUCTED, AND WHY THIS DIRECTION
--
-- The event date is drawn first, then the promise is derived from it:
--   on time  -> promise = event + 0..3 days of slack   (event <= promise)
--   late     -> promise = event - 1..12 days           (event >  promise)
--
-- The opposite direction — promise first, then delivery — is the intuitive one
-- and it is wrong here, because it makes the event date a function of lateness.
-- Late rows would then drift into later months than the on-time rows they are
-- compared against, so a month's OTD would be biased by its own lateness. With
-- the event date fixed first, a row's reporting period is independent of whether
-- it was late, which is what makes month-over-month OTD comparable at all.
--
-- On-time probability is baseline 87.5pp + CARRIER.ON_TIME_BIAS (-7.0..+6.5)
-- + 0.2pp for EU destinations. Carrier bias averages +0.31pp, so network OTD
-- lands near 87.8% and EU near 88.0%. Those two numbers being close but not
-- equal is the point: 91_verify_personas.sql uses the gap to prove the EU row
-- scope is actually filtering, and an exact tie would prove nothing.
--
-- Future-dated rows are forced on-time. A promise that has not come due yet
-- cannot have been missed, and marking it late would be the single biggest
-- source of a wrong number on the dashboard.
--
-- DETERMINISM. No RANDOM() anywhere; every draw is ABS(HASH(i, 'salt')). See the
-- header of 00b for why.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA RAW;

-- ---------------------------------------------------------------------------
-- PO_RECEIPT_LINE — inbound goods receipts. 420,000 lines.
--
-- ACTUAL_PRICE vs STANDARD_PRICE drives purchase price variance. The spread is
-- deliberately asymmetric: ~62% of receipts price at or below standard and ~38%
-- above, so PPV nets out unfavourable overall. A symmetric spread would average
-- to zero and make the metric, and its exception list, meaningless.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PO_RECEIPT_LINE (
  PO_ID           STRING NOT NULL COMMENT 'Purchase order number.',
  LINE            NUMBER NOT NULL COMMENT 'Line number within the purchase order.',
  SUPPLIER_ID     STRING NOT NULL COMMENT 'Vendor the line was placed with.',
  MATERIAL_ID     STRING NOT NULL COMMENT 'Material ordered.',
  ORDERED_QTY     NUMBER NOT NULL COMMENT 'Quantity ordered.',
  RECEIVED_QTY    NUMBER NOT NULL COMMENT 'Quantity actually received. Below ORDERED_QTY is a short receipt.',
  PROMISED_DATE   DATE   NOT NULL COMMENT 'Date the supplier committed to. The basis for on-time measurement.',
  RECEIPT_DATE    DATE   NOT NULL COMMENT 'Date goods were received. The event date: the reporting period comes from here.',
  STANDARD_PRICE  NUMBER(12,4) NOT NULL COMMENT 'Standard unit cost from the material master.',
  ACTUAL_PRICE    NUMBER(12,4) NOT NULL COMMENT 'Unit price actually invoiced.',
  CONSTRAINT pk_po_receipt_line PRIMARY KEY (PO_ID, LINE)
) COMMENT = 'Inbound purchase-order receipt lines. Source for CANONICAL.FCT_SUPPLIER_DELIVERY_LINE.';

INSERT INTO PO_RECEIPT_LINE
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 420000))),
base AS (
  SELECT
    s.i,
    'PO-' || LPAD(TO_CHAR(FLOOR(s.i / 4) + 1), 8, '0')                    AS po_id,
    (s.i % 4) + 1                                                          AS line,
    'SUP-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'sup')) % 300) + 1), 5, '0')     AS supplier_id,
    'MAT-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'mat')) % 2000) + 1), 6, '0')    AS material_id,
    -- 2.8% of receipts are promised for a date that has not arrived yet.
    ABS(HASH(s.i, 'fut')) % 1000 < 28                                      AS is_future,
    (ABS(HASH(s.i, 'oqty')) % 480) + 20                                    AS ordered_qty
  FROM s
),
dated AS (
  SELECT
    b.*,
    CASE WHEN b.is_future
         -- future window: 2026-09-21 .. 2026-11-25 (66 days)
         THEN DATEADD('DAY', ABS(HASH(b.i, 'fd')) % 66,  DATE '2026-09-21')
         -- historical window: 2024-10-03 .. 2026-09-20 (718 days)
         ELSE DATEADD('DAY', ABS(HASH(b.i, 'hd')) % 718, DATE '2024-10-03')
    END                                                                    AS receipt_date
  FROM base b
),
scored AS (
  SELECT
    d.*,
    sup.supplier_region,
    -- Supplier on-time probability: baseline 87.3pp, tier-1 vendors run better,
    -- tier-3 worse. Lands network supplier OTD near 87.7%, just under the 0.90
    -- target so the metric reads amber rather than green.
    87.3
      + CASE sup.supplier_tier WHEN 'TIER_1' THEN 3.0 WHEN 'TIER_2' THEN 0.0 ELSE -2.0 END
      + CASE sup.supplier_region WHEN 'APAC' THEN -1.5 WHEN 'LATAM' THEN -2.0 ELSE 0.5 END
                                                                           AS p_ontime,
    prt.standard_cost
  FROM dated d
  JOIN SUPPLIER sup ON sup.supplier_id = d.supplier_id
  JOIN PART     prt ON prt.material_id = d.material_id
)
SELECT
  po_id,
  line,
  supplier_id,
  material_id,
  ordered_qty,
  -- ~2.4% of receipts are short. Future rows are not yet received at all, so
  -- they carry the full ordered quantity rather than a fabricated shortfall.
  CASE WHEN is_future THEN ordered_qty
       WHEN ABS(HASH(i, 'short')) % 1000 < 24
         THEN GREATEST(1, ordered_qty - 1 - (ABS(HASH(i, 'shortq')) % GREATEST(1, FLOOR(ordered_qty * 0.30))))
       ELSE ordered_qty END                                                AS received_qty,
  CASE WHEN is_future OR (ABS(HASH(i, 'otd')) % 1000) < p_ontime * 10
       THEN DATEADD('DAY',  ABS(HASH(i, 'slack')) % 4,      receipt_date)
       ELSE DATEADD('DAY', -1 - (ABS(HASH(i, 'late')) % 12), receipt_date)
  END                                                                      AS promised_date,
  receipt_date,
  standard_cost                                                            AS standard_price,
  -- 62% at or below standard by up to 6%, 38% above by up to 14%, so PPV nets
  -- unfavourable: 0.62 x -3% + 0.38 x +7% = +0.8% of spend.
  --
  -- The unfavourable tail was widened from 9% to 14% after measurement. At 9% the
  -- weighted result was -$1.29M, i.e. favourable overall, which contradicts the
  -- narrative the metric is built for: an exception list of overpriced receipts is
  -- only worth chasing if the aggregate is actually adverse. The asymmetry is what
  -- produces that, since a symmetric spread cancels to roughly zero.
  CASE WHEN ABS(HASH(i, 'ppv')) % 100 < 62
       THEN ROUND(standard_cost * (1 - (ABS(HASH(i, 'fav')) % 600) / 10000.0), 4)
       ELSE ROUND(standard_cost * (1 + (ABS(HASH(i, 'unf')) % 1400) / 10000.0), 4)
  END                                                                      AS actual_price
FROM scored;

-- ---------------------------------------------------------------------------
-- SALES_ORDER_LINE — outbound customer order lines. 1,500,000 lines.
--
-- CDDA_MET (Customer Delivery Date Accepted) is a third, independent condition
-- beyond on-time and in-full. It exists so that perfect-order rate is strictly
-- harder to satisfy than OTIF, which is what makes them distinguishable metrics
-- rather than two names for the same number.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE SALES_ORDER_LINE (
  ORDER_ID      STRING NOT NULL COMMENT 'Sales order number.',
  ORDER_LINE    NUMBER NOT NULL COMMENT 'Line number within the sales order.',
  CUSTOMER_ID   STRING NOT NULL COMMENT 'Ship-to customer.',
  MATERIAL_ID   STRING NOT NULL COMMENT 'Material ordered.',
  CARRIER_ID    STRING NOT NULL COMMENT 'Carrier that moved the line.',
  LANE_ID       STRING NOT NULL COMMENT 'Transport lane used. Supplies the destination region and the committed transit time.',
  ORDERED_QTY   NUMBER NOT NULL COMMENT 'Quantity ordered by the customer.',
  SHIPPED_QTY   NUMBER NOT NULL COMMENT 'Quantity shipped. Below ORDERED_QTY is a short ship.',
  PROMISE_DATE  DATE   NOT NULL COMMENT 'Date promised to the customer.',
  DELIVERY_DATE DATE   NOT NULL COMMENT 'Date delivered. The event date: the reporting period comes from here.',
  TRANSIT_DAYS  NUMBER NOT NULL COMMENT 'Actual days in transit.',
  DEFECT_REASON STRING          COMMENT 'Recorded cause, populated only on lines that failed a condition. NULL on clean lines.',
  CDDA_MET      BOOLEAN NOT NULL COMMENT 'Customer delivery date accepted. An independent third condition, so that perfect order is strictly harder than OTIF.',
  WAS_SHIPPED   BOOLEAN NOT NULL COMMENT 'FALSE where the customer collected and no carrier-billed shipment exists. These lines are still delivered and still count in fulfilment; they simply have no landed-cost row, which is why SHIPMENT_COST is smaller than this table.',
  CONSTRAINT pk_sales_order_line PRIMARY KEY (ORDER_ID, ORDER_LINE)
) COMMENT = 'Outbound customer order lines. Source for CANONICAL.FCT_ORDER_LINE_FULFILLMENT.';

INSERT INTO SALES_ORDER_LINE
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 1500000))),
base AS (
  SELECT
    s.i,
    'SO-' || LPAD(TO_CHAR(FLOOR(s.i / 3) + 1), 9, '0')                     AS order_id,
    (s.i % 3) + 1                                                          AS order_line,
    'CUST-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'cust')) % 1200) + 1), 6, '0')  AS customer_id,
    'MAT-'  || LPAD(TO_CHAR((ABS(HASH(s.i, 'omat')) % 2000) + 1), 6, '0')  AS material_id,
    'CAR-'  || LPAD(TO_CHAR((ABS(HASH(s.i, 'car'))  % 8) + 1),    2, '0')  AS carrier_id,
    'LANE-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'lane')) % 96) + 1),   4, '0')  AS lane_id,
    ABS(HASH(s.i, 'ofut')) % 1000 < 28                                     AS is_future,
    (ABS(HASH(s.i, 'ooqty')) % 240) + 10                                   AS ordered_qty
  FROM s
),
dated AS (
  SELECT b.*,
    CASE WHEN b.is_future
         THEN DATEADD('DAY', ABS(HASH(b.i, 'ofd')) % 66,  DATE '2026-09-21')
         ELSE DATEADD('DAY', ABS(HASH(b.i, 'ohd')) % 718, DATE '2024-10-03')
    END                                                                    AS delivery_date
  FROM base b
),
scored AS (
  SELECT d.*,
    ln.dest_region,
    ln.transit_target_days,
    -- Baseline 87.5pp + carrier bias (mean +0.31pp) + 1.5pp for EU. Network OTD
    -- lands near 87.9%, EU near 89.4%.
    --
    -- The EU premium was first set to 0.2pp, which reproduced the 0.0017 gap this
    -- dataset historically showed. Measured, it produced a gap of 0.0001 for
    -- August 2026 -- smaller than the sampling noise of a single month (~14k EU
    -- lines, standard error ~0.003), so the sign of the gap was not even stable.
    -- 91_verify_personas.sql exists to *prove* the EU row scope is filtering, and
    -- an assertion that can pass or fail on noise proves nothing. 1.5pp is still
    -- a plausible regional difference but is unambiguously outside the noise.
    87.5 + car.on_time_bias + IFF(ln.dest_region = 'EU', 1.5, 0.0)          AS p_ontime
  FROM dated d
  JOIN LANE    ln  ON ln.lane_id    = d.lane_id
  JOIN CARRIER car ON car.carrier_id = d.carrier_id
),
flagged AS (
  SELECT sc.*,
    (is_future OR (ABS(HASH(i, 'ootd')) % 1000) < p_ontime * 10)            AS is_on_time,
    -- ~2.6% short-shipped; future lines ship complete by construction.
    (NOT is_future AND ABS(HASH(i, 'oshort')) % 1000 < 26)                  AS is_short,
    -- CDDA fails on ~4% of non-future lines, independent of the other two.
    (is_future OR ABS(HASH(i, 'cdda')) % 1000 >= 40)                        AS cdda_met
  FROM scored sc
)
SELECT
  order_id,
  order_line,
  customer_id,
  material_id,
  carrier_id,
  lane_id,
  ordered_qty,
  CASE WHEN is_short
       THEN GREATEST(1, ordered_qty - 1 - (ABS(HASH(i, 'osq')) % GREATEST(1, FLOOR(ordered_qty * 0.35))))
       ELSE ordered_qty END                                                AS shipped_qty,
  CASE WHEN is_on_time
       THEN DATEADD('DAY',  ABS(HASH(i, 'oslack')) % 4,       delivery_date)
       ELSE DATEADD('DAY', -1 - (ABS(HASH(i, 'olate')) % 12), delivery_date)
  END                                                                      AS promise_date,
  delivery_date,
  GREATEST(1, transit_target_days + (ABS(HASH(i, 'tr')) % 7) - 3)           AS transit_days,
  -- Populated only where something failed, and named after the dominant cause.
  CASE WHEN NOT is_on_time AND is_short THEN 'PARTIAL_LATE_SHIPMENT'
       WHEN NOT is_on_time THEN
         CASE ABS(HASH(i, 'dr')) % 5
           WHEN 0 THEN 'CARRIER_DELAY'      WHEN 1 THEN 'CUSTOMS_HOLD'
           WHEN 2 THEN 'WEATHER'            WHEN 3 THEN 'CAPACITY_SHORTFALL'
           ELSE 'DOCK_SCHEDULING' END
       WHEN is_short THEN
         CASE ABS(HASH(i, 'dr2')) % 3
           WHEN 0 THEN 'STOCK_SHORTAGE' WHEN 1 THEN 'QUALITY_HOLD'
           ELSE 'ALLOCATION_LIMIT' END
       WHEN NOT cdda_met THEN 'DATE_NOT_ACCEPTED'
       ELSE NULL END                                                       AS defect_reason,
  cdda_met,
  -- 1.3% of lines are customer-collect: delivered, and therefore fully in scope
  -- for fulfilment metrics, but with no carrier freight bill. This is why
  -- SHIPMENT_COST has fewer rows than this table. Modelling them as "never
  -- shipped" instead would be incoherent, because they carry a delivery date.
  (ABS(HASH(i, 'shipd')) % 1000 >= 13)                                     AS was_shipped
FROM flagged;

-- ---------------------------------------------------------------------------
-- SHIPMENT_COST — landed cost, one row per shipped order line. ~1,480,500.
--
-- Cost build-up, and why the proportions are what they are:
--   MATERIAL_COST = standard cost x shipped qty        (~$8.00 per unit)
--   FREIGHT_COST  = per-unit rate x carrier cost index (~$1.56 per unit)
--   DUTY_COST     = 4.5% of material, cross-region only
--   HANDLING_COST = $0.32 per unit
-- Landed cost per unit therefore lands near $10.35 against a $10 target with a
-- $10.50 warn boundary — amber, which is the only state that exercises both
-- comparisons. A figure far from the thresholds would leave the red/amber/green
-- logic untested by the data.
--
-- The per-unit freight rate was tuned down from $1.85 after measurement: that
-- rate produced $10.66, which sits in the dead band between the $10.50 warn
-- boundary and the $11.00 fail boundary, where the threshold semantics recorded
-- in 03_targets.sql ("<= warn is amber, > fail is red") classify it as neither.
--
-- INVOICED_FREIGHT_AMT is what the carrier billed and FREIGHT_COST what was
-- accrued; the variance is skewed so ~34% of shipments are overbilled. Freight
-- bill variance is a to-zero metric, so a symmetric spread would cancel to
-- nothing and the exception list would be empty.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE SHIPMENT_COST (
  SHIPMENT_ID          STRING NOT NULL COMMENT 'Shipment number.',
  ORDER_ID             STRING NOT NULL COMMENT 'Sales order the shipment belongs to.',
  ORDER_LINE           NUMBER NOT NULL COMMENT 'Order line the shipment covers.',
  CARRIER_ID           STRING NOT NULL COMMENT 'Carrier that moved the shipment.',
  LANE_ID              STRING NOT NULL COMMENT 'Lane used.',
  SERVICE_LEVEL        STRING NOT NULL COMMENT 'Committed service level from the lane.',
  SHIP_REGION          STRING NOT NULL COMMENT 'Destination region. The EU row access policy scopes on this column.',
  MATERIAL_ID          STRING NOT NULL COMMENT 'Material shipped.',
  SHIPPED_QTY          NUMBER NOT NULL COMMENT 'Units shipped. Denominator of landed cost per unit.',
  DELIVERY_DATE        DATE   NOT NULL COMMENT 'Delivery date. The event date for landed-cost reporting.',
  MATERIAL_COST        NUMBER(14,2) NOT NULL COMMENT 'Standard cost times quantity.',
  FREIGHT_COST         NUMBER(14,2) NOT NULL COMMENT 'Accrued freight.',
  INVOICED_FREIGHT_AMT NUMBER(14,2) NOT NULL COMMENT 'Freight the carrier actually invoiced.',
  ACCESSORIAL_USD      NUMBER(14,2) NOT NULL COMMENT 'Accessorial charges: detention, liftgate, redelivery.',
  DUTY_COST            NUMBER(14,2) NOT NULL COMMENT 'Duty. Cross-region movements only.',
  HANDLING_COST        NUMBER(14,2) NOT NULL COMMENT 'Warehouse handling.',
  IS_PREMIUM_FREIGHT   BOOLEAN NOT NULL COMMENT 'TRUE where an expedited service level was used.',
  CONSTRAINT pk_shipment_cost PRIMARY KEY (SHIPMENT_ID)
) COMMENT = 'Landed cost per shipped order line. Source for CANONICAL.FCT_LANDED_COST_SHIPMENT.';

INSERT INTO SHIPMENT_COST
WITH src AS (
  SELECT
    sol.order_id, sol.order_line, sol.carrier_id, sol.lane_id, sol.material_id,
    sol.shipped_qty, sol.delivery_date,
    ln.dest_region, ln.service_level,
    car.cost_index,
    prt.standard_cost,
    ABS(HASH(sol.order_id, sol.order_line, 'shp')) AS h,
    nd.node_region AS origin_region
  FROM SALES_ORDER_LINE sol
  JOIN LANE    ln  ON ln.lane_id     = sol.lane_id
  JOIN CARRIER car ON car.carrier_id = sol.carrier_id
  JOIN PART    prt ON prt.material_id = sol.material_id
  JOIN NODE    nd  ON nd.node_id      = ln.origin_node
  WHERE sol.was_shipped
),
costed AS (
  SELECT src.*,
    ROUND(standard_cost * shipped_qty, 2)                                  AS material_cost,
    -- ~$1.54 per unit at index 1.0, varied +/-18% per shipment.
    ROUND(shipped_qty * 1.54 * cost_index * (1 + ((h % 360) - 180) / 1000.0), 2) AS freight_cost,
    ROUND(shipped_qty * 0.32, 2)                                           AS handling_cost,
    IFF(origin_region <> dest_region, ROUND(standard_cost * shipped_qty * 0.045, 2), 0.00) AS duty_cost
  FROM src
)
SELECT
  'SHP-' || LPAD(TO_CHAR(ROW_NUMBER() OVER (ORDER BY order_id, order_line)), 10, '0') AS shipment_id,
  order_id,
  order_line,
  carrier_id,
  lane_id,
  service_level,
  dest_region                                                              AS ship_region,
  material_id,
  shipped_qty,
  delivery_date,
  material_cost,
  freight_cost,
  -- 34% overbilled by up to 12%, 66% billed at or slightly under accrual.
  CASE WHEN h % 100 < 34
       THEN ROUND(freight_cost * (1 + ((ABS(HASH(order_id, order_line, 'ov')) % 1200) + 1) / 10000.0), 2)
       ELSE ROUND(freight_cost * (1 - (ABS(HASH(order_id, order_line, 'un')) % 400) / 10000.0), 2)
  END                                                                      AS invoiced_freight_amt,
  -- Accessorials on ~18% of shipments only.
  IFF(h % 100 < 18, ROUND(12 + (h % 9000) / 100.0, 2), 0.00)               AS accessorial_usd,
  duty_cost,
  handling_cost,
  (service_level = 'EXPRESS')                                              AS is_premium_freight
FROM costed;

-- ---------------------------------------------------------------------------
-- INVENTORY_POSITION — month-end balances. 5,712 pairs x 24 months = 137,088.
--
-- EXACTLY ONE SNAPSHOT PER MONTH-END, 2024-10-31..2026-09-30. This is not a
-- detail: a snapshot is a balance, not a flow, so it must not be summed across
-- periods. 02_as_of_rule.sql records that rule, the inventory verified queries in
-- 07 demonstrate it, and 92_verify_counts.sql asserts the 24 dates. Emitting
-- daily snapshots would let a plausible-looking SUM over a quarter produce a
-- number ninety times too large.
--
-- Snapshots stop at 2026-09-30 rather than running into the future window: a
-- balance cannot be observed for a date that has not occurred, which is also why
-- these metrics are scoped SNAPSHOT and need no future-row exclusion.
--
-- ON_HAND_QTY is built as a multiple of AVG_DAILY_DEMAND so that days of cover
-- averages ~32 days against a 30-day target with a 35-day warn boundary — amber,
-- and close enough to both to exercise them.
--
-- THE DISTRIBUTION IS SKEWED, NOT UNIFORM, AND THAT IS LOAD-BEARING. Days of
-- cover was first drawn uniformly over 5..59 days, which gave the right mean of
-- 32 but a hard ceiling below 60 — so the "more than 60 days of cover" exception
-- rule in 05_exception_rules.sql matched exactly zero rows, and the drill-down
-- behind the inventory metric was permanently empty. A squared draw keeps the
-- mean near 32 while producing a genuine long right tail: overstocked positions
-- are precisely what the metric exists to surface.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE INVENTORY_POSITION (
  SNAPSHOT_DATE    DATE   NOT NULL COMMENT 'Month-end date the balance was observed. One per month, never a partial period.',
  MATERIAL_ID      STRING NOT NULL COMMENT 'Material.',
  NODE_ID          STRING NOT NULL COMMENT 'Stocking location.',
  ON_HAND_QTY      NUMBER NOT NULL COMMENT 'Units on hand at the snapshot.',
  AVG_DAILY_DEMAND NUMBER(12,3) NOT NULL COMMENT 'Trailing average daily demand. Denominator of days of inventory.',
  SAFETY_STOCK     NUMBER NOT NULL COMMENT 'Target safety stock. Below this is an availability risk.',
  ATP_QTY          NUMBER NOT NULL COMMENT 'Available to promise: on hand less allocated, floored at zero. Zero is a genuine stockout and is what IS_STOCKED_OUT is derived from in CANONICAL.',
  CONSTRAINT pk_inventory_position PRIMARY KEY (SNAPSHOT_DATE, MATERIAL_ID, NODE_ID)
) COMMENT = 'Month-end inventory balances by material and node. Exactly 24 snapshot dates, 2024-10-31..2026-09-30. A snapshot is non-additive across periods.';

INSERT INTO INVENTORY_POSITION
WITH pairs AS (
  -- 5,712 = 24 nodes x 238 materials. Deriving the node from i % 24 and the
  -- material slot from i / 24 guarantees distinct pairs without a DISTINCT pass,
  -- and guarantees every node is stocked — a hash-filtered cross join would
  -- leave some nodes empty and make node a misleading dimension.
  SELECT
    i,
    'ND-'  || LPAD(TO_CHAR((i % 24) + 1), 2, '0')                                     AS node_id,
    'MAT-' || LPAD(TO_CHAR((((i % 24) * 238 + FLOOR(i / 24)) % 2000) + 1), 6, '0')     AS material_id
  FROM (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 5712)))
),
months AS (
  SELECT DISTINCT month_end AS snapshot_date
  FROM DATE_DIM
  WHERE month_end BETWEEN DATE '2024-10-31' AND DATE '2026-09-30'
),
grid AS (
  SELECT p.i, p.node_id, p.material_id, m.snapshot_date,
         ABS(HASH(p.i, m.snapshot_date, 'inv')) AS h
  FROM pairs p CROSS JOIN months m
),
demanded AS (
  SELECT g.*,
    prt.abc_class,
    -- A-class items move fastest; demand also drifts mildly by month so that a
    -- trend line over the 24 snapshots is not flat.
    ROUND(
      CASE prt.abc_class WHEN 'A' THEN 42.0 WHEN 'B' THEN 18.0 ELSE 7.0 END
      * (1 + ((g.h % 700) - 350) / 1000.0)
      * (1 + (MONTH(g.snapshot_date) - 6) / 90.0)
    , 3)                                                                   AS avg_daily_demand
  FROM grid g
  JOIN PART prt ON prt.material_id = g.material_id
)
SELECT
  snapshot_date,
  material_id,
  node_id,
  -- Days of cover = 8 + (h%100)^2/135, i.e. 8..81 days, mean ~32, with ~16% of
  -- positions above 60 days for the exception rule to select.
  GREATEST(0, ROUND(avg_daily_demand * (8 + POWER(h % 100, 2) / 135.0)))    AS on_hand_qty,
  avg_daily_demand,
  GREATEST(1, ROUND(avg_daily_demand * 12))                                AS safety_stock,
  -- ATP is on hand less an allocation of 0.6x-1.4x safety stock, floored at zero.
  -- Deriving it this way rather than as a flat percentage of on-hand is what
  -- makes genuine stockouts occur: a position holding only 8 days of cover
  -- against 12 days of safety stock allocates to zero. A percentage-of-on-hand
  -- formula can never reach zero, which would leave IS_STOCKED_OUT constantly
  -- false and the inventory-value exception rule in 05 selecting on only half of
  -- its stated predicate.
  GREATEST(0, ROUND(avg_daily_demand * (8 + POWER(h % 100, 2) / 135.0))
              - ROUND(GREATEST(1, ROUND(avg_daily_demand * 12)) * (0.6 + (h % 800) / 1000.0))) AS atp_qty
FROM demanded;

-- ---------------------------------------------------------------------------
-- PRODUCTION_ORDER — manufacturing completions. 240,000 orders.
--
-- Plants only: a DC does not complete production orders, and allowing one to
-- would make NODE_TYPE meaningless as a dimension.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PRODUCTION_ORDER (
  PRODUCTION_ORDER_ID STRING NOT NULL COMMENT 'Production order number.',
  MATERIAL_ID         STRING NOT NULL COMMENT 'Material produced.',
  NODE_ID             STRING NOT NULL COMMENT 'Producing plant. Always a PLANT, never a DC.',
  PLANNED_QTY         NUMBER NOT NULL COMMENT 'Quantity planned.',
  COMPLETED_QTY       NUMBER NOT NULL COMMENT 'Quantity completed good.',
  SCRAP_QTY           NUMBER NOT NULL COMMENT 'Quantity scrapped.',
  SCHEDULED_DATE      DATE   NOT NULL COMMENT 'Scheduled completion date.',
  COMPLETED_DATE      DATE   NOT NULL COMMENT 'Actual completion date. The event date for manufacturing reporting.',
  CONSTRAINT pk_production_order PRIMARY KEY (PRODUCTION_ORDER_ID)
) COMMENT = 'Manufacturing completions. Source for the MANUFACTURING domain.';

INSERT INTO PRODUCTION_ORDER
WITH s AS (SELECT SEQ4() AS i FROM TABLE(GENERATOR(ROWCOUNT => 240000))),
plants AS (SELECT node_id, ROW_NUMBER() OVER (ORDER BY node_id) - 1 AS idx, COUNT(*) OVER () AS n
           FROM NODE WHERE node_type = 'PLANT'),
base AS (
  SELECT s.i,
    'PRD-' || LPAD(TO_CHAR(s.i + 1), 9, '0')                               AS production_order_id,
    'MAT-' || LPAD(TO_CHAR((ABS(HASH(s.i, 'pmat')) % 2000) + 1), 6, '0')   AS material_id,
    (ABS(HASH(s.i, 'pqty')) % 900) + 100                                   AS planned_qty,
    DATEADD('DAY', ABS(HASH(s.i, 'pd')) % 718, DATE '2024-10-03')          AS completed_date,
    ABS(HASH(s.i, 'pnode'))                                                AS hnode,
    ABS(HASH(s.i, 'pscrap'))                                               AS hscrap,
    ABS(HASH(s.i, 'psched'))                                               AS hsched
  FROM s
)
SELECT
  b.production_order_id,
  b.material_id,
  p.node_id,
  b.planned_qty,
  b.planned_qty - FLOOR(b.planned_qty * (b.hscrap % 45) / 1000.0)           AS completed_qty,
  FLOOR(b.planned_qty * (b.hscrap % 45) / 1000.0)                          AS scrap_qty,
  DATEADD('DAY', (b.hsched % 9) - 4, b.completed_date)                      AS scheduled_date,
  b.completed_date
FROM base b
JOIN plants p ON p.idx = b.hnode % p.n;

-- ---------------------------------------------------------------------------
-- DEMAND_FORECAST — 2,000 materials x 26 periods = 52,000.
--
-- PERIOD IS A 'YYYY-MM' STRING, NOT A DATE, AND MUST STAY THAT WAY.
-- 01_calendar_dimension.sql documents that FORECAST is deliberately left
-- unjoined to CALENDAR precisely because it has no day-grain key. Converting
-- this to a DATE would invite a CALENDAR relationship, which would give several
-- facts two join paths to the calendar and make every affected metric fail with
-- a multi-path error.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE DEMAND_FORECAST (
  MATERIAL_ID   STRING NOT NULL COMMENT 'Material forecast.',
  PERIOD        STRING NOT NULL COMMENT 'Forecast month as a YYYY-MM label. Deliberately not a DATE: see the header note and 01_calendar_dimension.sql.',
  FORECAST_QTY  NUMBER NOT NULL COMMENT 'Forecast quantity for the period.',
  ACTUAL_QTY    NUMBER NOT NULL COMMENT 'Realised quantity. Zero for periods that have not closed.',
  CONSTRAINT pk_demand_forecast PRIMARY KEY (MATERIAL_ID, PERIOD)
) COMMENT = 'Monthly demand forecast versus actual, by material. 26 periods, 2024-10..2026-11.';

INSERT INTO DEMAND_FORECAST
WITH periods AS (
  SELECT DISTINCT period, month_start
  FROM DATE_DIM
  WHERE month_start BETWEEN DATE '2024-10-01' AND DATE '2026-11-01'
),
grid AS (
  SELECT prt.material_id, p.period, p.month_start, prt.abc_class,
         ABS(HASH(prt.material_id, p.period, 'fc')) AS h
  FROM PART prt CROSS JOIN periods p
)
SELECT
  material_id,
  period,
  ROUND(CASE abc_class WHEN 'A' THEN 1250 WHEN 'B' THEN 540 ELSE 210 END
        * (1 + ((h % 620) - 310) / 1000.0))                                AS forecast_qty,
  -- Actual is zero for periods that have not closed: a forecast for an open
  -- month has nothing to be compared against yet.
  CASE WHEN month_start > DATE_TRUNC('MONTH', DATE '2026-09-20') THEN 0
       ELSE ROUND(CASE abc_class WHEN 'A' THEN 1250 WHEN 'B' THEN 540 ELSE 210 END
                  * (1 + ((h % 620) - 310) / 1000.0)
                  * (1 + ((ABS(HASH(material_id, period, 'act')) % 440) - 200) / 1000.0))
  END                                                                      AS actual_qty
FROM grid;


-- ============================================================================
-- FILE: 00d_canonical.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 00d — CANONICAL atomic-grain facts.
--
-- These tables are the reconciliation target of the whole project. Every metric
-- in GOVERNANCE.METRIC_DEFINITION carries a CANONICAL_SQL that computes it from
-- exactly one of these tables, and METRIC_DRIFT_TEST asserts that every semantic
-- view binding agrees with that SQL. The semantic views in 00e are defined over
-- these same tables, which is what makes agreement achievable rather than
-- coincidental: a view reading a different source could match today and diverge
-- tomorrow for reasons nobody would notice.
--
-- ---------------------------------------------------------------------------
-- BOOLEAN FLAGS ARE NUMBER(1,0), NOT BOOLEAN. This looks like a mistake and is
-- not. METRIC_EXCEPTION_RULE.exception_where in 05_exception_rules.sql contains
-- predicates written as `IS_ON_TIME = 0`, `IS_OTIF = 0`, `IS_STOCKED_OUT = 1`,
-- and those strings are interpolated into the drill-down query verbatim. Against
-- a BOOLEAN column Snowflake rejects the comparison outright, so the drill-down
-- would fail for every service metric. The flags are also summed directly by the
-- metric expressions (AVG of a 1/0 flag is a rate), which a BOOLEAN cannot do.
--
-- ---------------------------------------------------------------------------
-- WHY THE DIMENSION ATTRIBUTES ARE DENORMALISED ONTO EACH FACT
--
-- SUPPLIER_REGION, PRODUCT_FAMILY, NODE_NAME and so on are copied onto the facts
-- rather than left to a join. Two reasons, both structural:
--
--   1. The drill-down route builds its column list from METRIC_EXCEPTION_RULE
--      and validates every name against INFORMATION_SCHEMA.COLUMNS *of the fact
--      table alone* (app/api/drilldown/route.ts). A column reachable only by a
--      join is not in that list, so it can never be displayed or filtered on.
--   2. The row access policy scoping SC_LOGISTICS_EU attaches to a column on the
--      fact. A policy cannot filter on an attribute that lives in another table
--      without the join being part of the policy, which would make the scope
--      depend on join cardinality.
--
-- The cost is storage and the risk is staleness against the dimension. Both are
-- acceptable here because these tables are rebuilt wholesale, never updated in
-- place.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA CANONICAL;

-- ---------------------------------------------------------------------------
-- FCT_SUPPLIER_DELIVERY_LINE — 420,000 rows. One per purchase-order receipt line.
--
-- RECEIPT_VARIANCE_DAYS is signed, positive meaning late. 05_exception_rules.sql
-- orders the supplier-OTD exception list by `RECEIPT_VARIANCE_DAYS DESC` to put
-- the worst offenders first, which only works with that sign convention.
--
-- EXTENDED_PRICE_VARIANCE is the dollar impact and multiplies by RECEIVED_QTY,
-- not ORDERED_QTY: variance is realised on what was actually invoiced. Using the
-- ordered quantity would overstate PPV on every short receipt.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE FCT_SUPPLIER_DELIVERY_LINE (
  PO_ID                   STRING       NOT NULL COMMENT 'Purchase order number.',
  LINE                    NUMBER       NOT NULL COMMENT 'Line number within the purchase order.',
  SUPPLIER_ID             STRING       NOT NULL COMMENT 'Vendor number.',
  SUPPLIER_NAME           STRING       NOT NULL COMMENT 'Vendor name.',
  SUPPLIER_REGION         STRING       NOT NULL COMMENT 'Sourcing region.',
  SUPPLIER_GROUP          STRING       NOT NULL COMMENT 'Commodity group.',
  SUPPLIER_TIER           STRING       NOT NULL COMMENT 'Strategic tier.',
  MATERIAL_ID             STRING       NOT NULL COMMENT 'Material received.',
  PRODUCT_FAMILY          STRING       NOT NULL COMMENT 'Product family of the material.',
  BUSINESS_SEGMENT        STRING       NOT NULL COMMENT 'Reporting segment.',
  ABC_CLASS               STRING       NOT NULL COMMENT 'Inventory value class of the material.',
  PROMISED_DATE           DATE         NOT NULL COMMENT 'Date the supplier committed to.',
  RECEIPT_DATE            DATE         NOT NULL COMMENT 'Date goods were received. The event date: reporting periods are applied to this column.',
  RECEIPT_VARIANCE_DAYS   NUMBER       NOT NULL COMMENT 'Receipt date minus promised date. Positive is late, negative is early.',
  ORDERED_QTY             NUMBER       NOT NULL COMMENT 'Quantity ordered.',
  RECEIVED_QTY            NUMBER       NOT NULL COMMENT 'Quantity received.',
  IS_ON_TIME              NUMBER(1,0)  NOT NULL COMMENT '1 when received on or before the promised date. Numeric, not boolean: the exception rules compare it to 0 and the metrics average it.',
  IS_IN_FULL              NUMBER(1,0)  NOT NULL COMMENT '1 when the received quantity met the ordered quantity.',
  STANDARD_PRICE          NUMBER(12,4) NOT NULL COMMENT 'Standard unit cost.',
  ACTUAL_PRICE            NUMBER(12,4) NOT NULL COMMENT 'Unit price invoiced.',
  UNIT_PRICE_VARIANCE     NUMBER(12,4) NOT NULL COMMENT 'Actual less standard, per unit. Positive is unfavourable.',
  EXTENDED_PRICE_VARIANCE NUMBER(16,4) NOT NULL COMMENT 'Unit variance times received quantity: the realised dollar impact. Deliberately on received, not ordered, quantity.',
  CONSTRAINT pk_fct_supplier_delivery_line PRIMARY KEY (PO_ID, LINE)
) COMMENT = 'Atomic inbound receipt lines. Canonical source for supplier OTD, supplier fill rate and purchase price variance.';

INSERT INTO FCT_SUPPLIER_DELIVERY_LINE
SELECT
  r.po_id,
  r.line,
  r.supplier_id,
  s.supplier_name,
  s.supplier_region,
  s.supplier_group,
  s.supplier_tier,
  r.material_id,
  p.product_family,
  p.business_segment,
  p.abc_class,
  r.promised_date,
  r.receipt_date,
  DATEDIFF('DAY', r.promised_date, r.receipt_date)                          AS receipt_variance_days,
  r.ordered_qty,
  r.received_qty,
  IFF(r.receipt_date <= r.promised_date, 1, 0)                              AS is_on_time,
  IFF(r.received_qty >= r.ordered_qty, 1, 0)                                AS is_in_full,
  r.standard_price,
  r.actual_price,
  ROUND(r.actual_price - r.standard_price, 4)                               AS unit_price_variance,
  ROUND((r.actual_price - r.standard_price) * r.received_qty, 4)             AS extended_price_variance
FROM SUPPLY_CHAIN.RAW.PO_RECEIPT_LINE r
JOIN SUPPLY_CHAIN.RAW.SUPPLIER s ON s.supplier_id = r.supplier_id
JOIN SUPPLY_CHAIN.RAW.PART     p ON p.material_id = r.material_id;

-- ---------------------------------------------------------------------------
-- FCT_ORDER_LINE_FULFILLMENT — 1,500,000 rows. One per customer order line.
--
-- The four service flags form a strict hierarchy, and each one is stored rather
-- than recomputed downstream:
--   IS_ON_TIME        delivered on or before the promise
--   IS_IN_FULL        shipped the full ordered quantity
--   IS_OTIF           both of the above
--   IS_PERFECT_ORDER  OTIF and the customer accepted the delivery date
--
-- Storing them is what lets 05_exception_rules.sql write a different predicate
-- per metric against one table, and what lets the drill-down show which specific
-- condition failed on a row rather than only that something did.
--
-- CARRIER holds the carrier NAME, not the id: the operations page groups on
-- order_fulfillment.carrier and the drill-down displays it, and a code would be
-- unreadable in both. The id is not carried, since nothing joins back to it.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE FCT_ORDER_LINE_FULFILLMENT (
  ORDER_ID         STRING      NOT NULL COMMENT 'Sales order number.',
  ORDER_LINE       NUMBER      NOT NULL COMMENT 'Line number within the sales order.',
  CUSTOMER_ID      STRING      NOT NULL COMMENT 'Ship-to customer.',
  CUSTOMER_NAME    STRING      NOT NULL COMMENT 'Customer name.',
  CUSTOMER_REGION  STRING      NOT NULL COMMENT 'Region the account is managed in.',
  CUSTOMER_SEGMENT STRING      NOT NULL COMMENT 'Go-to-market segment.',
  MATERIAL_ID      STRING      NOT NULL COMMENT 'Material ordered.',
  PRODUCT_FAMILY   STRING      NOT NULL COMMENT 'Product family.',
  BUSINESS_SEGMENT STRING      NOT NULL COMMENT 'Reporting segment.',
  CARRIER          STRING      NOT NULL COMMENT 'Carrier name. The name rather than the code, because this column is both grouped on and displayed.',
  LANE_ID          STRING      NOT NULL COMMENT 'Transport lane.',
  SHIP_REGION      STRING      NOT NULL COMMENT 'Destination region. The row access policy for SC_LOGISTICS_EU scopes on this column.',
  PROMISE_DATE     DATE        NOT NULL COMMENT 'Date promised to the customer.',
  DELIVERY_DATE    DATE        NOT NULL COMMENT 'Date delivered. The event date: reporting periods are applied to this column.',
  TRANSIT_DAYS     NUMBER      NOT NULL COMMENT 'Actual days in transit.',
  DEFECT_REASON    STRING               COMMENT 'Recorded cause on lines that failed a condition. NULL on clean lines.',
  ORDERED_QTY      NUMBER      NOT NULL COMMENT 'Quantity ordered.',
  SHIPPED_QTY      NUMBER      NOT NULL COMMENT 'Quantity shipped.',
  IS_ON_TIME       NUMBER(1,0) NOT NULL COMMENT '1 when delivered on or before the promise date.',
  IS_IN_FULL       NUMBER(1,0) NOT NULL COMMENT '1 when the full ordered quantity shipped.',
  IS_OTIF          NUMBER(1,0) NOT NULL COMMENT '1 when on time AND in full. Stored, not recomputed, so one table can serve a different exception predicate per metric.',
  IS_CDDA_MET      NUMBER(1,0) NOT NULL COMMENT '1 when the customer accepted the delivery date. Independent of the other conditions.',
  IS_PERFECT_ORDER NUMBER(1,0) NOT NULL COMMENT '1 when OTIF and CDDA both hold. Strictly harder than OTIF, which is what makes it a distinct metric.',
  CONSTRAINT pk_fct_order_line_fulfillment PRIMARY KEY (ORDER_ID, ORDER_LINE)
) COMMENT = 'Atomic outbound order lines. Canonical source for customer OTD, OTIF, fill rate and perfect order rate.';

INSERT INTO FCT_ORDER_LINE_FULFILLMENT
WITH flags AS (
  SELECT
    sol.*,
    c.customer_name, c.customer_region, c.customer_segment,
    p.product_family, p.business_segment,
    car.carrier_name,
    ln.dest_region,
    IFF(sol.delivery_date <= sol.promise_date, 1, 0)  AS f_on_time,
    IFF(sol.shipped_qty  >= sol.ordered_qty,   1, 0)  AS f_in_full,
    IFF(sol.cdda_met, 1, 0)                           AS f_cdda
  FROM SUPPLY_CHAIN.RAW.SALES_ORDER_LINE sol
  JOIN SUPPLY_CHAIN.RAW.CUSTOMER c  ON c.customer_id  = sol.customer_id
  JOIN SUPPLY_CHAIN.RAW.PART     p  ON p.material_id  = sol.material_id
  JOIN SUPPLY_CHAIN.RAW.CARRIER  car ON car.carrier_id = sol.carrier_id
  JOIN SUPPLY_CHAIN.RAW.LANE     ln ON ln.lane_id     = sol.lane_id
)
SELECT
  order_id, order_line, customer_id, customer_name, customer_region, customer_segment,
  material_id, product_family, business_segment,
  carrier_name AS carrier,
  lane_id,
  dest_region  AS ship_region,
  promise_date, delivery_date, transit_days, defect_reason, ordered_qty, shipped_qty,
  f_on_time                                     AS is_on_time,
  f_in_full                                     AS is_in_full,
  f_on_time * f_in_full                         AS is_otif,
  f_cdda                                        AS is_cdda_met,
  f_on_time * f_in_full * f_cdda                AS is_perfect_order
FROM flags;

-- ---------------------------------------------------------------------------
-- FCT_LANDED_COST_SHIPMENT — 1,480,499 rows. One per carrier-billed shipment.
--
-- FREIGHT_BILL_VAR_AMT is invoiced minus accrued, so positive means the carrier
-- overbilled. 05_exception_rules.sql selects `FREIGHT_BILL_VAR_AMT > 0` and calls
-- those rows overbilling, so the sign convention is part of the contract.
--
-- TOTAL_LANDED_COST is stored rather than computed on read. Landed cost per unit
-- is a ratio of two sums, and the drill-down orders on
-- `(TOTAL_LANDED_COST / SHIPPED_QTY) DESC`; if the total were a view expression,
-- that ORDER BY would reference a column that INFORMATION_SCHEMA.COLUMNS does not
-- list and the drill-down's own validation would reject it.
--
-- ACCESSORIAL_USD is deliberately NOT part of TOTAL_LANDED_COST. Accessorials are
-- billed separately from the landed cost of goods, and folding them in would make
-- landed cost per unit disagree with the components shown beside it in the
-- drill-down — the exact kind of quiet inconsistency the drift test exists to
-- catch, except in a place the drift test cannot see.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE FCT_LANDED_COST_SHIPMENT (
  SHIPMENT_ID          STRING       NOT NULL COMMENT 'Shipment number.',
  ORDER_ID             STRING       NOT NULL COMMENT 'Sales order.',
  ORDER_LINE           NUMBER       NOT NULL COMMENT 'Sales order line.',
  CARRIER              STRING       NOT NULL COMMENT 'Carrier name.',
  LANE_ID              STRING       NOT NULL COMMENT 'Lane used.',
  SERVICE_LEVEL        STRING       NOT NULL COMMENT 'Committed service level.',
  SHIP_REGION          STRING       NOT NULL COMMENT 'Destination region. Scoped by the EU row access policy.',
  MATERIAL_ID          STRING       NOT NULL COMMENT 'Material shipped.',
  PRODUCT_FAMILY       STRING       NOT NULL COMMENT 'Product family.',
  BUSINESS_SEGMENT     STRING       NOT NULL COMMENT 'Reporting segment.',
  SHIPPED_QTY          NUMBER       NOT NULL COMMENT 'Units shipped. Denominator of landed cost per unit.',
  DELIVERY_DATE        DATE         NOT NULL COMMENT 'Delivery date. The event date for landed-cost reporting.',
  MATERIAL_COST        NUMBER(14,2) NOT NULL COMMENT 'Standard cost times quantity.',
  FREIGHT_COST         NUMBER(14,2) NOT NULL COMMENT 'Accrued freight.',
  INVOICED_FREIGHT_AMT NUMBER(14,2) NOT NULL COMMENT 'Freight the carrier invoiced.',
  FREIGHT_BILL_VAR_AMT NUMBER(14,2) NOT NULL COMMENT 'Invoiced less accrued. Positive is carrier overbilling.',
  ACCESSORIAL_USD      NUMBER(14,2) NOT NULL COMMENT 'Accessorial charges. Deliberately excluded from TOTAL_LANDED_COST: they are billed separately from the landed cost of goods.',
  DUTY_COST            NUMBER(14,2) NOT NULL COMMENT 'Duty on cross-region movements.',
  HANDLING_COST        NUMBER(14,2) NOT NULL COMMENT 'Warehouse handling.',
  TOTAL_LANDED_COST    NUMBER(14,2) NOT NULL COMMENT 'Material + freight + duty + handling. Stored rather than derived so the drill-down can order on it.',
  IS_PREMIUM_FREIGHT   NUMBER(1,0)  NOT NULL COMMENT '1 where an expedited service level was used.',
  CONSTRAINT pk_fct_landed_cost_shipment PRIMARY KEY (SHIPMENT_ID)
) COMMENT = 'Atomic landed cost per shipment. Canonical source for landed cost per unit, freight cost, freight invoiced and freight bill variance.';

INSERT INTO FCT_LANDED_COST_SHIPMENT
SELECT
  sc.shipment_id,
  sc.order_id,
  sc.order_line,
  car.carrier_name                                                          AS carrier,
  sc.lane_id,
  sc.service_level,
  sc.ship_region,
  sc.material_id,
  p.product_family,
  p.business_segment,
  sc.shipped_qty,
  sc.delivery_date,
  sc.material_cost,
  sc.freight_cost,
  sc.invoiced_freight_amt,
  ROUND(sc.invoiced_freight_amt - sc.freight_cost, 2)                        AS freight_bill_var_amt,
  sc.accessorial_usd,
  sc.duty_cost,
  sc.handling_cost,
  ROUND(sc.material_cost + sc.freight_cost + sc.duty_cost + sc.handling_cost, 2) AS total_landed_cost,
  IFF(sc.is_premium_freight, 1, 0)                                           AS is_premium_freight
FROM SUPPLY_CHAIN.RAW.SHIPMENT_COST sc
JOIN SUPPLY_CHAIN.RAW.PART    p   ON p.material_id   = sc.material_id
JOIN SUPPLY_CHAIN.RAW.CARRIER car ON car.carrier_id  = sc.carrier_id;

-- ---------------------------------------------------------------------------
-- FCT_INVENTORY_SNAPSHOT — 137,088 rows. 5,712 material-node pairs x 24 month-ends.
--
-- THIS TABLE IS NOT ADDITIVE OVER TIME and every consumer has to know it. Summing
-- INVENTORY_VALUE across the 24 snapshots yields a number 24 times too large that
-- looks entirely plausible. The guards against that are layered deliberately:
-- METRIC_DEFINITION.as_of_scope marks these metrics SNAPSHOT (02_as_of_rule.sql),
-- lib/sc.ts selects the latest snapshot date within the requested period rather
-- than aggregating, and the inventory verified queries in 07 are all written per
-- snapshot so Cortex Analyst is shown the correct pattern rather than left to
-- infer it.
--
-- INVENTORY_VALUE is on-hand at standard cost. Using a moving average cost would
-- make the value move for reasons unrelated to the quantity on hand, which would
-- make the metric unusable for explaining a change in stock.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE FCT_INVENTORY_SNAPSHOT (
  SNAPSHOT_DATE    DATE         NOT NULL COMMENT 'Month-end the balance was observed. Exactly 24 distinct values. Not additive across periods.',
  MATERIAL_ID      STRING       NOT NULL COMMENT 'Material.',
  PRODUCT_FAMILY   STRING       NOT NULL COMMENT 'Product family.',
  BUSINESS_SEGMENT STRING       NOT NULL COMMENT 'Reporting segment.',
  ABC_CLASS        STRING       NOT NULL COMMENT 'Inventory value class.',
  NODE_ID          STRING       NOT NULL COMMENT 'Stocking location code.',
  NODE_NAME        STRING       NOT NULL COMMENT 'Stocking location name.',
  NODE_REGION      STRING       NOT NULL COMMENT 'Region the node serves.',
  ON_HAND_QTY      NUMBER       NOT NULL COMMENT 'Units on hand.',
  AVG_DAILY_DEMAND NUMBER(12,3) NOT NULL COMMENT 'Trailing average daily demand. Denominator of days of inventory.',
  SAFETY_STOCK     NUMBER       NOT NULL COMMENT 'Target safety stock.',
  ATP_QTY          NUMBER       NOT NULL COMMENT 'Available to promise.',
  IS_STOCKED_OUT   NUMBER(1,0)  NOT NULL COMMENT '1 when nothing is available to promise.',
  INVENTORY_VALUE  NUMBER(16,2) NOT NULL COMMENT 'On-hand quantity at standard cost. Standard rather than moving-average cost, so that value moves only when quantity does.',
  CONSTRAINT pk_fct_inventory_snapshot PRIMARY KEY (SNAPSHOT_DATE, MATERIAL_ID, NODE_ID)
) COMMENT = 'Atomic month-end inventory positions. Canonical source for days of inventory and inventory value. A snapshot: never sum across snapshot dates.';

INSERT INTO FCT_INVENTORY_SNAPSHOT
SELECT
  ip.snapshot_date,
  ip.material_id,
  p.product_family,
  p.business_segment,
  p.abc_class,
  ip.node_id,
  n.node_name,
  n.node_region,
  ip.on_hand_qty,
  ip.avg_daily_demand,
  ip.safety_stock,
  ip.atp_qty,
  IFF(ip.atp_qty <= 0, 1, 0)                                                AS is_stocked_out,
  ROUND(ip.on_hand_qty * p.standard_cost, 2)                                AS inventory_value
FROM SUPPLY_CHAIN.RAW.INVENTORY_POSITION ip
JOIN SUPPLY_CHAIN.RAW.PART p ON p.material_id = ip.material_id
JOIN SUPPLY_CHAIN.RAW.NODE n ON n.node_id     = ip.node_id;

-- ---------------------------------------------------------------------------
-- FCT_REQUISITION_LINE — the demand signal upstream of a purchase order.
--
-- Carried because METRIC_DEFINITION references it as a canonical fact and the
-- ontology catalogue lists it, so its absence would leave a registered fact
-- pointing at nothing. One requisition line per purchase-order line, with the
-- requisition raised 5-25 days before the promise: enough to make requisition
-- lead time measurable, which is the only thing this grain adds over the receipt
-- line.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE FCT_REQUISITION_LINE (
  REQUISITION_ID    STRING NOT NULL COMMENT 'Requisition number.',
  REQUISITION_LINE  NUMBER NOT NULL COMMENT 'Line within the requisition.',
  PO_ID             STRING NOT NULL COMMENT 'Purchase order the requisition converted into.',
  LINE              NUMBER NOT NULL COMMENT 'Purchase order line.',
  MATERIAL_ID       STRING NOT NULL COMMENT 'Material requested.',
  PRODUCT_FAMILY    STRING NOT NULL COMMENT 'Product family.',
  SUPPLIER_ID       STRING NOT NULL COMMENT 'Vendor the requisition was sourced to.',
  SUPPLIER_REGION   STRING NOT NULL COMMENT 'Sourcing region.',
  REQUESTED_QTY     NUMBER NOT NULL COMMENT 'Quantity requested.',
  REQUISITION_DATE  DATE   NOT NULL COMMENT 'Date the requisition was raised. The event date.',
  PROMISED_DATE     DATE   NOT NULL COMMENT 'Date subsequently committed by the supplier.',
  LEAD_TIME_DAYS    NUMBER NOT NULL COMMENT 'Days from requisition to promised delivery.',
  CONSTRAINT pk_fct_requisition_line PRIMARY KEY (REQUISITION_ID, REQUISITION_LINE)
) COMMENT = 'Atomic requisition lines: the demand signal upstream of a purchase order. Adds requisition lead time over the receipt grain.';

INSERT INTO FCT_REQUISITION_LINE
SELECT
  'REQ-' || SUBSTR(f.po_id, 4)                                              AS requisition_id,
  f.line                                                                    AS requisition_line,
  f.po_id,
  f.line,
  f.material_id,
  f.product_family,
  f.supplier_id,
  f.supplier_region,
  f.ordered_qty                                                             AS requested_qty,
  DATEADD('DAY', -(5 + ABS(HASH(f.po_id, f.line, 'req')) % 21), f.promised_date) AS requisition_date,
  f.promised_date,
  5 + ABS(HASH(f.po_id, f.line, 'req')) % 21                                AS lead_time_days
FROM FCT_SUPPLIER_DELIVERY_LINE f;

-- ---------------------------------------------------------------------------
-- Read access for the personas.
--
-- SELECT only, and only on CANONICAL — never on RAW. The drill-down is the single
-- path from a metric to the rows behind it, and it is constrained by
-- METRIC_EXCEPTION_RULE, so a persona cannot wander off and compute a rival
-- version of a governed number from the source system.
-- ---------------------------------------------------------------------------

GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_PLANNER;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_PROCUREMENT;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_LOGISTICS;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.CANONICAL TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 00e_semantic.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 00e — SEMANTIC views. The only surface the application and Cortex Analyst query.
--
-- MUST RUN BEFORE 01_calendar_dimension.sql, AND NEVER AFTER IT.
-- 01 reads this file's SC_ONTOLOGY_360 back with GET_DDL and string-splices the
-- CALENDAR entity into it. Re-running this file afterwards reverts the view to 10
-- entities, silently removing calendar.cal_date and calendar.is_future — which
-- lib/period.ts filters on for every reporting period. See sql/00_README.md.
--
-- ---------------------------------------------------------------------------
-- THREE SPLICE ANCHORS IN 01 ARE LOAD-BEARING AND VERIFIED, NOT ASSUMED
--
-- 01 inserts the CALENDAR table, its relationships and its dimensions by
-- REPLACE-ing three substrings that must each occur EXACTLY ONCE in GET_DDL
-- output:
--
--   'SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)'
--   'PO_TO_PART as PURCHASE_ORDER(MATERIAL_ID)'
--   'PART.MATERIAL as part.material_id'
--
-- Note the first one carries no `PART as` alias. That is not an oversight in 01:
-- GET_DDL omits the alias when it is identical to the base table name, so the
-- deployed DDL really does read `SUPPLY_CHAIN.RAW.PART primary key (...)`. This
-- was confirmed against this account rather than assumed, because a REPLACE on a
-- string that does not occur is a silent no-op — the view would still compile and
-- the failure would only surface later as a missing dimension.
--
-- Consequences for anything edited here:
--   * PART must remain the only logical table over SUPPLY_CHAIN.RAW.PART.
--   * The relationship must stay named PO_TO_PART and stay declared as
--     PURCHASE_ORDER(MATERIAL_ID).
--   * The dimension must stay named PART.MATERIAL over part.material_id.
-- 90_verify_base.sql asserts all three occurrence counts before 01 runs.
--
-- ---------------------------------------------------------------------------
-- WHY LANDED_COST HAS NO EDGE TO PART, AND WILL NOT GET ONE
--
-- LANDED_COST reaches PART only through COST_TO_FULFILLMENT -> ORDER_FULFILLMENT
-- -> FULFILLMENT_TO_PART. A direct LANDED_COST(MATERIAL_ID) -> PART edge looks
-- like an obvious convenience and would break every landed-cost metric: two join
-- paths to the same entity make the traversal ambiguous and Snowflake rejects the
-- query with a multi-path error. 01 relies on exactly the same reasoning to
-- justify leaving LANDED_COST unjoined to CALENDAR.
--
-- ---------------------------------------------------------------------------
-- ENTITY COMMENTS ARE PARSED, NOT DECORATION
--
-- GOVERNANCE.ONTOLOGY_ENTITY (00f) derives two columns from the comment text:
--   * ONTOLOGY_CLASS from the leading 'sco:<Class>' token
--   * ENTITY_ROLE from whether the comment contains the exact phrase
--     'Conformed dimension.'
-- Deriving them from the deployed comment rather than storing them separately is
-- what makes the catalogue on /ontology incapable of drifting from the view. The
-- cost is that rewording a comment reclassifies an entity, so every dimension
-- comment below contains that phrase verbatim and no fact comment does.
--
-- ---------------------------------------------------------------------------
-- RELATIONSHIP COUNT: 10 HERE, 14 AFTER 01
--
-- The previous build of this dataset recorded 16 relationships. Ten are
-- reconstructible from what the application and the increments actually
-- reference; 01 adds four calendar edges, giving 14. The remaining two are not
-- recoverable, and inventing edges to reach a count would be actively harmful:
-- every additional edge is a chance to create a second join path and break a
-- metric. The catalogue reports what is deployed, so 14 is simply the true number.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA SEMANTIC;

-- ---------------------------------------------------------------------------
-- SC_ONTOLOGY_360 — the cross-domain view.
--
-- The only view the application queries directly. Every other view in this file
-- is a domain-scoped subset for the conversational layer, where a narrower tool
-- resolves more reliably than one wide one.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE SEMANTIC VIEW SC_ONTOLOGY_360
  TABLES (
    PART as SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)
      with synonyms=('part','material','sku','item','product')
      comment='sco:Material - what is bought, made, stocked and sold. Conformed dimension. Shared by purchasing, fulfilment, inventory, manufacturing and demand, so product family means the same thing in every domain.',
    SUPPLIER as SUPPLY_CHAIN.RAW.SUPPLIER primary key (SUPPLIER_ID)
      with synonyms=('supplier','vendor','source')
      comment='sco:Supplier - who goods are bought from. Conformed dimension. The inbound counterpart to CUSTOMER.',
    CUSTOMER as SUPPLY_CHAIN.RAW.CUSTOMER primary key (CUSTOMER_ID)
      with synonyms=('customer','account','ship-to','client')
      comment='sco:Customer - who goods are sold to. Conformed dimension. The outbound counterpart to SUPPLIER.',
    NODE as SUPPLY_CHAIN.RAW.NODE primary key (NODE_ID)
      with synonyms=('node','plant','warehouse','dc','location','site')
      comment='sco:Location - where goods are made or held. Conformed dimension. Shared by inventory and manufacturing.',
    PURCHASE_ORDER as SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE primary key (PO_ID, LINE)
      with synonyms=('purchase order','po','receipt','inbound delivery','goods receipt')
      comment='sco:InboundReceipt - one purchase-order line received from a supplier. Fact, receipt-line grain. Event date is RECEIPT_DATE.',
    ORDER_FULFILLMENT as SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT primary key (ORDER_ID, ORDER_LINE)
      with synonyms=('order fulfillment','sales order','delivery','outbound','customer order','shipment')
      comment='sco:OutboundDelivery - one customer order line delivered. Fact, order-line grain. Event date is DELIVERY_DATE. Distinct from PURCHASE_ORDER: this is delivery to a customer, not receipt from a supplier.',
    LANDED_COST as SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT primary key (SHIPMENT_ID)
      with synonyms=('landed cost','freight','cost to serve','shipment cost','transport cost')
      comment='sco:LandedCost - total delivered cost of one shipment. Fact, shipment grain. Reaches PART and CALENDAR only through ORDER_FULFILLMENT, deliberately.',
    INVENTORY as SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT primary key (SNAPSHOT_DATE, MATERIAL_ID, NODE_ID)
      with synonyms=('inventory','stock','on hand','position','balance')
      comment='sco:InventoryPosition - month-end balance for one material at one node. Fact, snapshot grain. NOT additive across snapshot dates: select the latest snapshot in the period, never sum over it.',
    PRODUCTION_ORDER as SUPPLY_CHAIN.RAW.PRODUCTION_ORDER primary key (PRODUCTION_ORDER_ID)
      with synonyms=('production order','manufacturing order','work order','build')
      comment='sco:ProductionOrder - one manufacturing completion at a plant. Fact, order grain. Event date is COMPLETED_DATE.',
    FORECAST as SUPPLY_CHAIN.RAW.DEMAND_FORECAST primary key (MATERIAL_ID, PERIOD)
      with synonyms=('forecast','demand plan','planned demand')
      comment='sco:DemandForecast - monthly forecast versus actual for one material. Fact, material-period grain. Has no day-grain date, so it carries its own period dimension and is not joined to CALENDAR.'
  )
  RELATIONSHIPS (
    PO_TO_PART as PURCHASE_ORDER(MATERIAL_ID) references PART(MATERIAL_ID),
    PO_TO_SUPPLIER as PURCHASE_ORDER(SUPPLIER_ID) references SUPPLIER(SUPPLIER_ID),
    FULFILLMENT_TO_PART as ORDER_FULFILLMENT(MATERIAL_ID) references PART(MATERIAL_ID),
    FULFILLMENT_TO_CUSTOMER as ORDER_FULFILLMENT(CUSTOMER_ID) references CUSTOMER(CUSTOMER_ID),
    COST_TO_FULFILLMENT as LANDED_COST(ORDER_ID, ORDER_LINE) references ORDER_FULFILLMENT(ORDER_ID, ORDER_LINE),
    INVENTORY_TO_PART as INVENTORY(MATERIAL_ID) references PART(MATERIAL_ID),
    INVENTORY_TO_NODE as INVENTORY(NODE_ID) references NODE(NODE_ID),
    PRODUCTION_TO_PART as PRODUCTION_ORDER(MATERIAL_ID) references PART(MATERIAL_ID),
    PRODUCTION_TO_NODE as PRODUCTION_ORDER(NODE_ID) references NODE(NODE_ID),
    FORECAST_TO_PART as FORECAST(MATERIAL_ID) references PART(MATERIAL_ID)
  )
  FACTS (
    PURCHASE_ORDER.ON_TIME as purchase_order.is_on_time comment='1 when the receipt met the promised date.',
    PURCHASE_ORDER.IN_FULL as purchase_order.is_in_full comment='1 when the full ordered quantity was received.',
    PURCHASE_ORDER.PRICE_VARIANCE as purchase_order.extended_price_variance comment='Unfavourable dollars from pricing above standard.',
    ORDER_FULFILLMENT.ON_TIME as order_fulfillment.is_on_time comment='1 when delivered by the promise date.',
    ORDER_FULFILLMENT.IN_FULL as order_fulfillment.is_in_full comment='1 when the full ordered quantity shipped.',
    ORDER_FULFILLMENT.OTIF as order_fulfillment.is_otif comment='1 when on time and in full.',
    ORDER_FULFILLMENT.PERFECT as order_fulfillment.is_perfect_order comment='1 when on time, in full and date-accepted.',
    LANDED_COST.TOTAL_COST as landed_cost.total_landed_cost comment='Material + freight + duty + handling.',
    LANDED_COST.UNITS as landed_cost.shipped_qty comment='Units shipped.',
    LANDED_COST.FREIGHT as landed_cost.freight_cost comment='Accrued freight.',
    LANDED_COST.FREIGHT_INVOICED as landed_cost.invoiced_freight_amt comment='Freight the carrier invoiced.',
    LANDED_COST.BILL_VARIANCE as landed_cost.freight_bill_var_amt comment='Invoiced less accrued. Positive is overbilling.',
    INVENTORY.ON_HAND as inventory.on_hand_qty comment='Units on hand at the snapshot.',
    INVENTORY.DAILY_DEMAND as inventory.avg_daily_demand comment='Trailing average daily demand.',
    INVENTORY.VALUE as inventory.inventory_value comment='On-hand quantity at standard cost.',
    PRODUCTION_ORDER.COMPLETED as production_order.completed_qty comment='Good quantity completed.',
    PRODUCTION_ORDER.SCRAP as production_order.scrap_qty comment='Quantity scrapped.',
    PRODUCTION_ORDER.PLANNED as production_order.planned_qty comment='Quantity planned.',
    FORECAST.FORECAST_UNITS as forecast.forecast_qty comment='Forecast quantity.',
    FORECAST.ACTUAL_UNITS as forecast.actual_qty comment='Realised quantity.'
  )
  DIMENSIONS (
    PART.MATERIAL as part.material_id with synonyms=('material number','sku','item code') comment='Material identifier.',
    PART.PRODUCT_FAMILY as part.product_family with synonyms=('family','product line','category') comment='Product family. The most-used analytical grouping in the application.',
    PART.BUSINESS_SEGMENT as part.business_segment with synonyms=('segment','division','business') comment='Reporting segment the family rolls into.',
    PART.ABC_CLASS as part.abc_class with synonyms=('abc','value class','classification') comment='Inventory value class: A high-value low-volume, C the reverse.',
    SUPPLIER.SUPPLIER_NAME as supplier.supplier_name with synonyms=('vendor name','supplier') comment='Vendor name.',
    SUPPLIER.SUPPLIER_REGION as supplier.supplier_region with synonyms=('sourcing region','vendor region','inbound region') comment='Region goods are sourced from. The inbound region. Not the same as the outbound SHIP_REGION.',
    SUPPLIER.SUPPLIER_GROUP as supplier.supplier_group with synonyms=('commodity group','category') comment='Commodity group the vendor is managed under.',
    SUPPLIER.SUPPLIER_TIER as supplier.supplier_tier with synonyms=('tier','strategic tier') comment='Strategic tier. TIER_1 carries the majority of spend.',
    CUSTOMER.CUSTOMER_NAME as customer.customer_name with synonyms=('account name','customer') comment='Customer name.',
    CUSTOMER.CUSTOMER_REGION as customer.customer_region with synonyms=('account region','sales region') comment='Region the account is managed in. Where the account sits, not where goods went.',
    CUSTOMER.CUSTOMER_SEGMENT as customer.customer_segment with synonyms=('segment','go-to-market') comment='Go-to-market segment.',
    NODE.NODE_NAME as node.node_name with synonyms=('site','location name','plant name','warehouse') comment='Location name.',
    NODE.NODE_REGION as node.node_region with synonyms=('site region','network region') comment='Region the node serves.',
    NODE.NODE_TYPE as node.node_type with synonyms=('site type','facility type') comment='PLANT for manufacturing, DC for distribution.',
    PURCHASE_ORDER.RECEIPT_DATE as purchase_order.receipt_date with synonyms=('goods receipt date','received on') comment='Date goods were received. The inbound event date.',
    PURCHASE_ORDER.LATE_DAYS as purchase_order.receipt_variance_days with synonyms=('days late','receipt variance') comment='Receipt date minus promised date. Positive is late.',
    ORDER_FULFILLMENT.DELIVERY_DATE as order_fulfillment.delivery_date with synonyms=('delivered on','ship date') comment='Date delivered to the customer. The outbound event date.',
    ORDER_FULFILLMENT.CARRIER as order_fulfillment.carrier with synonyms=('carrier','freight carrier','transport provider') comment='Carrier that moved the line.',
    ORDER_FULFILLMENT.SHIP_REGION as order_fulfillment.ship_region with synonyms=('destination region','delivery region','outbound region') comment='Region goods were delivered to. The outbound region, and the column regional row scoping applies to.',
    ORDER_FULFILLMENT.DEFECT_REASON as order_fulfillment.defect_reason with synonyms=('failure reason','root cause','defect') comment='Recorded cause on lines that failed a service condition. NULL on clean lines.',
    LANDED_COST.SERVICE_LEVEL as landed_cost.service_level with synonyms=('service','freight service') comment='Committed service level.',
    LANDED_COST.LANE as landed_cost.lane_id with synonyms=('lane','route') comment='Transport lane.',
    INVENTORY.SNAPSHOT_DATE as inventory.snapshot_date with synonyms=('as of date','snapshot','balance date') comment='Month-end the balance was observed. Filter to one snapshot; do not aggregate across them.',
    PRODUCTION_ORDER.COMPLETED_DATE as production_order.completed_date with synonyms=('completion date','made on') comment='Date production completed. The manufacturing event date.',
    FORECAST.FORECAST_PERIOD as forecast.period with synonyms=('forecast month','plan period','yyyy-mm') comment='Forecast month as a YYYY-MM label. FORECAST has no day-grain date, so this is its own time dimension rather than a join to CALENDAR.'
  )
  METRICS (
    PURCHASE_ORDER.SUPPLIER_OTD_PCT as AVG(purchase_order.on_time)
      with synonyms=('supplier on-time delivery','inbound otd','vendor otd','supplier delivery performance')
      comment='Share of purchase-order lines received on or before the promised date. Receipt-line weighted, not an average of per-supplier rates. Inbound: this is supplier performance, not delivery to customers.',
    PURCHASE_ORDER.SUPPLIER_FILL_RATE as AVG(purchase_order.in_full)
      with synonyms=('supplier fill rate','inbound fill rate','vendor fill')
      comment='Share of purchase-order lines received complete.',
    PURCHASE_ORDER.PPV as SUM(purchase_order.price_variance)
      with synonyms=('purchase price variance','ppv','price variance')
      comment='Unfavourable dollars from receipts priced above standard cost, on received quantity. An absolute dollar amount: it scales with volume and period length, so it has no fixed target.',
    PURCHASE_ORDER.PO_LINE_COUNT as COUNT(purchase_order.po_id)
      with synonyms=('receipt lines','po lines','inbound line count')
      comment='Number of purchase-order receipt lines. The denominator behind the inbound rates.',
    ORDER_FULFILLMENT.OTD_PCT as AVG(order_fulfillment.on_time)
      with synonyms=('on-time delivery','customer otd','otd','delivery performance','outbound otd')
      comment='Share of customer order lines delivered on or before the promise date. Order-line weighted. Outbound: delivery to customers, not receipt from suppliers.',
    ORDER_FULFILLMENT.OTIF_PCT as AVG(order_fulfillment.otif)
      with synonyms=('on time in full','otif')
      comment='Share of order lines both on time and in full. Always at or below OTD and fill rate individually.',
    ORDER_FULFILLMENT.FILL_RATE_PCT as AVG(order_fulfillment.in_full)
      with synonyms=('fill rate','line fill','order fill rate')
      comment='Share of order lines shipped complete.',
    ORDER_FULFILLMENT.PERFECT_ORDER_PCT as AVG(order_fulfillment.perfect)
      with synonyms=('perfect order rate','perfect order')
      comment='Share of order lines on time, in full, and with the delivery date accepted. Strictly harder than OTIF.',
    ORDER_FULFILLMENT.ORDER_LINE_COUNT as COUNT(order_fulfillment.order_id)
      with synonyms=('order lines','delivery lines','outbound line count')
      comment='Number of customer order lines. The denominator behind the outbound rates.',
    LANDED_COST.LANDED_COST_PER_UNIT as SUM(landed_cost.total_cost) / NULLIF(SUM(landed_cost.units), 0)
      with synonyms=('landed cost per unit','unit landed cost','cost per unit')
      comment='Total landed cost divided by units shipped. A ratio of two sums, never an average of per-shipment ratios: the latter would weight a one-unit shipment the same as a thousand-unit one. Normalised per unit, so it is comparable across periods and does carry a target.',
    LANDED_COST.LANDED_COST_USD as SUM(landed_cost.total_cost)
      with synonyms=('landed cost','total landed cost','delivered cost')
      comment='Total landed cost. An absolute dollar amount, so no fixed target.',
    LANDED_COST.FREIGHT_COST_USD as SUM(landed_cost.freight)
      with synonyms=('freight cost','accrued freight','transport cost')
      comment='Accrued freight. An absolute dollar amount, so no fixed target.',
    LANDED_COST.FREIGHT_INVOICED_USD as SUM(landed_cost.freight_invoiced)
      with synonyms=('freight invoiced','carrier billed','invoiced freight')
      comment='Freight the carriers invoiced. An absolute dollar amount, so no fixed target.',
    LANDED_COST.FREIGHT_BILL_VARIANCE_USD as SUM(landed_cost.bill_variance)
      with synonyms=('freight bill variance','overbilling','billing variance','freight audit')
      comment='Invoiced freight less accrued freight. Positive means carriers billed more than was accrued. A to-zero metric.',
    INVENTORY.DAYS_OF_INVENTORY as SUM(inventory.on_hand) / NULLIF(SUM(inventory.daily_demand), 0)
      with synonyms=('days of inventory','days of cover','doi','days on hand','inventory days')
      comment='On-hand units divided by average daily demand. Measured at a single snapshot: a period filter must select one snapshot date, because averaging this across months mixes balances from different points in time.',
    INVENTORY.INVENTORY_VALUE_USD as SUM(inventory.value)
      with synonyms=('inventory value','stock value','on-hand value')
      comment='On-hand quantity at standard cost, at one snapshot. Never sum across snapshot dates: the result is a plausible-looking multiple of the truth.',
    PRODUCTION_ORDER.PRODUCTION_COMPLETED_UNITS as SUM(production_order.completed)
      with synonyms=('units produced','completed units','production output')
      comment='Good units completed.',
    PRODUCTION_ORDER.SCRAP_RATE as SUM(production_order.scrap) / NULLIF(SUM(production_order.planned), 0)
      with synonyms=('scrap rate','yield loss','waste rate')
      comment='Scrapped units over planned units. A ratio of sums.',
    FORECAST.FORECAST_UNITS_TOTAL as SUM(forecast.forecast_units)
      with synonyms=('forecast units','planned demand')
      comment='Forecast quantity.',
    FORECAST.FORECAST_ACCURACY as 1 - ABS(SUM(forecast.actual_units) - SUM(forecast.forecast_units)) / NULLIF(SUM(forecast.forecast_units), 0)
      with synonyms=('forecast accuracy','demand accuracy','plan accuracy')
      comment='One minus absolute forecast error over forecast. Open periods carry a zero actual, so include only closed periods when reading this.'
  )
  COMMENT = 'Cross-domain supply chain ontology. Five conformed dimensions and six facts spanning inbound, outbound, inventory, cost, manufacturing and demand, so one question can compare across domains on shared dimensions. The only semantic view the application queries directly.'
  -- -------------------------------------------------------------------------
  -- VERIFIED QUERIES. Declared here, inline, NOT spliced in later.
  --
  -- sql/07_verified_queries.sql documents a GET_DDL splice for amending an
  -- already-deployed view. That is the right tool for a live change and the wrong
  -- one for a build: its Pattern A anchors on the string 'ai_verified_queries ('
  -- and is a SILENT NO-OP against a view that has no such block yet, which is
  -- exactly how a previous build ended up with 1 verified query instead of 38.
  -- In a from-scratch build we own this statement, so the queries are declared
  -- where the view is defined and the failure mode does not exist.
  --
  -- NO VERIFIED QUERY MAY REFERENCE calendar.*. This file runs BEFORE
  -- 01_calendar_dimension.sql adds the CALENDAR entity, so a calendar reference
  -- would fail at create time. The as-of teaching example below therefore filters
  -- on the fact's own event date, which works in every view and teaches the same
  -- lesson.
  --
  -- Several of these do double duty as teaching examples for Cortex Analyst:
  -- every inventory query is written per snapshot to demonstrate the non-additive
  -- pattern, and REALIZED_PERFORMANCE_EXCLUDES_FUTURE encodes the as-of rule.
  -- -------------------------------------------------------------------------
  AI_VERIFIED_QUERIES (
    SUPPLIER_VS_CUSTOMER_OTD AS (
      QUESTION 'How does supplier on-time delivery compare with the on-time delivery we give customers?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 METRICS purchase_order.supplier_otd_pct, order_fulfillment.otd_pct)'
    ),
    OTD_BY_PRODUCT_FAMILY AS (
      QUESTION 'What is on-time delivery by product family?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS part.product_family METRICS order_fulfillment.otd_pct) ORDER BY otd_pct ASC'
    ),
    SUPPLIER_OTD_BY_REGION AS (
      QUESTION 'Which supplier regions have the worst on-time delivery?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS supplier.supplier_region METRICS purchase_order.supplier_otd_pct, purchase_order.po_line_count) ORDER BY supplier_otd_pct ASC'
    ),
    INVENTORY_DAYS_AT_LATEST_SNAPSHOT AS (
      QUESTION 'How many days of inventory are we holding?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS inventory.snapshot_date METRICS inventory.days_of_inventory) QUALIFY snapshot_date = MAX(snapshot_date) OVER ()'
    ),
    LANDED_COST_PER_UNIT_BY_FAMILY AS (
      QUESTION 'What is landed cost per unit by product family?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS part.product_family METRICS landed_cost.landed_cost_per_unit) ORDER BY landed_cost_per_unit DESC'
    ),
    FREIGHT_BILL_VARIANCE_BY_CARRIER AS (
      QUESTION 'Are carriers billing us more than we accrued for freight?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS order_fulfillment.carrier METRICS landed_cost.freight_cost_usd, landed_cost.freight_invoiced_usd, landed_cost.freight_bill_variance_usd) ORDER BY freight_bill_variance_usd DESC'
    ),
    REALIZED_PERFORMANCE_EXCLUDES_FUTURE AS (
      QUESTION 'What is our realized on-time delivery, excluding orders that have not been delivered yet?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 METRICS order_fulfillment.otd_pct WHERE order_fulfillment.delivery_date <= CURRENT_DATE())'
    ),
    PERFECT_ORDER_VS_OTIF AS (
      QUESTION 'What is the difference between our perfect order rate and OTIF?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 METRICS order_fulfillment.otd_pct, order_fulfillment.fill_rate_pct, order_fulfillment.otif_pct, order_fulfillment.perfect_order_pct)'
    ),
    PPV_BY_SUPPLIER_TIER AS (
      QUESTION 'Where is purchase price variance coming from by supplier tier?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360 DIMENSIONS supplier.supplier_tier METRICS purchase_order.ppv) ORDER BY ppv DESC'
    )
  );

-- ---------------------------------------------------------------------------
-- Domain views.
--
-- WHY NARROWER VIEWS EXIST AT ALL. These are not a different definition of
-- anything — each metric expression is identical to its SC_ONTOLOGY_360 twin, and
-- METRIC_DRIFT_TEST asserts that agreement on every run. They exist because a
-- conversational tool resolves more reliably over a small, domain-scoped surface
-- than over an eleven-entity one, and because persona access is granted per view:
-- PERSONA_VIEW_ACCESS can give procurement the supplier view without also giving
-- it landed cost.
--
-- Duplicating an expression is the risk this project is about, so the drift test
-- is the control: if someone edits a metric here and not there, the next run
-- fails with a non-zero spread and names both bindings.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE SEMANTIC VIEW SC_SUPPLIER
  TABLES (
    SUPPLIER_DELIVERY as SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE primary key (PO_ID, LINE)
      with synonyms=('supplier delivery','purchase order receipt','inbound')
      comment='sco:InboundReceipt - one purchase-order line received. Fact, receipt-line grain.'
  )
  FACTS (
    SUPPLIER_DELIVERY.ON_TIME as supplier_delivery.is_on_time comment='1 when received by the promised date.',
    SUPPLIER_DELIVERY.IN_FULL as supplier_delivery.is_in_full comment='1 when received complete.',
    SUPPLIER_DELIVERY.PRICE_VARIANCE as supplier_delivery.extended_price_variance comment='Unfavourable pricing dollars.'
  )
  DIMENSIONS (
    SUPPLIER_DELIVERY.SUPPLIER_NAME as supplier_delivery.supplier_name with synonyms=('vendor','supplier') comment='Vendor name.',
    SUPPLIER_DELIVERY.SUPPLIER_REGION as supplier_delivery.supplier_region with synonyms=('sourcing region','vendor region') comment='Region goods are sourced from.',
    SUPPLIER_DELIVERY.SUPPLIER_TIER as supplier_delivery.supplier_tier with synonyms=('tier') comment='Strategic tier.',
    SUPPLIER_DELIVERY.PRODUCT_FAMILY as supplier_delivery.product_family with synonyms=('family','category') comment='Product family.',
    SUPPLIER_DELIVERY.RECEIPT_DATE as supplier_delivery.receipt_date with synonyms=('goods receipt date') comment='Date goods were received.'
  )
  METRICS (
    SUPPLIER_DELIVERY.SUPPLIER_OTD_PCT as AVG(supplier_delivery.on_time)
      with synonyms=('supplier on-time delivery','inbound otd','vendor otd')
      comment='Share of purchase-order lines received on or before the promised date. Receipt-line weighted. Identical to PURCHASE_ORDER.SUPPLIER_OTD_PCT in SC_ONTOLOGY_360.',
    SUPPLIER_DELIVERY.SUPPLIER_FILL_RATE as AVG(supplier_delivery.in_full)
      with synonyms=('supplier fill rate','inbound fill rate')
      comment='Share of purchase-order lines received complete.',
    SUPPLIER_DELIVERY.PPV as SUM(supplier_delivery.price_variance)
      with synonyms=('purchase price variance','ppv')
      comment='Unfavourable dollars from receipts above standard cost.'
  )
  COMMENT = 'Supplier delivery and purchasing performance. Domain-scoped subset of SC_ONTOLOGY_360 for the conversational layer; metric expressions are identical.'
  AI_VERIFIED_QUERIES (
    SUPPLIER_OTD_OVERALL AS (
      QUESTION 'What is our supplier on-time delivery?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER METRICS supplier_delivery.supplier_otd_pct)'
    ),
    SUPPLIER_OTD_BY_REGION AS (
      QUESTION 'Which sourcing regions are late most often?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER DIMENSIONS supplier_delivery.supplier_region METRICS supplier_delivery.supplier_otd_pct) ORDER BY supplier_otd_pct ASC'
    ),
    SUPPLIER_FILL_RATE_BY_TIER AS (
      QUESTION 'Do our strategic suppliers ship complete more often than the rest?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER DIMENSIONS supplier_delivery.supplier_tier METRICS supplier_delivery.supplier_fill_rate) ORDER BY supplier_tier'
    ),
    PPV_BY_PRODUCT_FAMILY AS (
      QUESTION 'Which product families are we overpaying for against standard cost?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER DIMENSIONS supplier_delivery.product_family METRICS supplier_delivery.ppv) ORDER BY ppv DESC'
    ),
    WORST_SUPPLIERS_BY_OTD AS (
      QUESTION 'Which individual suppliers have the worst on-time delivery?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER DIMENSIONS supplier_delivery.supplier_name METRICS supplier_delivery.supplier_otd_pct) ORDER BY supplier_otd_pct ASC LIMIT 20'
    )
  );

CREATE OR REPLACE SEMANTIC VIEW SC_FULFILLMENT
  TABLES (
    ORDER_FULFILLMENT as SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT primary key (ORDER_ID, ORDER_LINE)
      with synonyms=('order fulfillment','delivery','outbound','customer order')
      comment='sco:OutboundDelivery - one customer order line delivered. Fact, order-line grain.'
  )
  FACTS (
    ORDER_FULFILLMENT.ON_TIME as order_fulfillment.is_on_time comment='1 when delivered by the promise date.',
    ORDER_FULFILLMENT.IN_FULL as order_fulfillment.is_in_full comment='1 when shipped complete.',
    ORDER_FULFILLMENT.OTIF as order_fulfillment.is_otif comment='1 when on time and in full.',
    ORDER_FULFILLMENT.PERFECT as order_fulfillment.is_perfect_order comment='1 when on time, in full and date-accepted.'
  )
  DIMENSIONS (
    ORDER_FULFILLMENT.PRODUCT_FAMILY as order_fulfillment.product_family with synonyms=('family','category','product line') comment='Product family.',
    ORDER_FULFILLMENT.CUSTOMER_REGION as order_fulfillment.customer_region with synonyms=('account region') comment='Region the account is managed in.',
    ORDER_FULFILLMENT.SHIP_REGION as order_fulfillment.ship_region with synonyms=('destination region','delivery region') comment='Region goods were delivered to.',
    ORDER_FULFILLMENT.CARRIER as order_fulfillment.carrier with synonyms=('carrier','transport provider') comment='Carrier that moved the line.',
    ORDER_FULFILLMENT.DEFECT_REASON as order_fulfillment.defect_reason with synonyms=('failure reason','root cause') comment='Recorded cause on failed lines.',
    ORDER_FULFILLMENT.DELIVERY_DATE as order_fulfillment.delivery_date with synonyms=('delivered on') comment='Date delivered.'
  )
  METRICS (
    ORDER_FULFILLMENT.OTD_PCT as AVG(order_fulfillment.on_time)
      with synonyms=('on-time delivery','customer otd','otd')
      comment='Share of customer order lines delivered on or before the promise date. Identical to ORDER_FULFILLMENT.OTD_PCT in SC_ONTOLOGY_360.',
    ORDER_FULFILLMENT.OTIF_PCT as AVG(order_fulfillment.otif)
      with synonyms=('on time in full','otif') comment='Share of order lines on time and in full.',
    ORDER_FULFILLMENT.FILL_RATE_PCT as AVG(order_fulfillment.in_full)
      with synonyms=('fill rate','line fill') comment='Share of order lines shipped complete.',
    ORDER_FULFILLMENT.PERFECT_ORDER_PCT as AVG(order_fulfillment.perfect)
      with synonyms=('perfect order rate') comment='Share of order lines on time, in full and date-accepted.'
  )
  COMMENT = 'Customer fulfilment performance. Domain-scoped subset of SC_ONTOLOGY_360; metric expressions are identical.'
  AI_VERIFIED_QUERIES (
    OTD_OVERALL AS (
      QUESTION 'What is our on-time delivery to customers?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT METRICS order_fulfillment.otd_pct)'
    ),
    OTD_BY_PRODUCT_FAMILY AS (
      QUESTION 'What is on-time delivery by product family?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT DIMENSIONS order_fulfillment.product_family METRICS order_fulfillment.otd_pct) ORDER BY otd_pct ASC'
    ),
    OTIF_BY_SHIP_REGION AS (
      QUESTION 'Which destination regions are worst for on time in full?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT DIMENSIONS order_fulfillment.ship_region METRICS order_fulfillment.otif_pct) ORDER BY otif_pct ASC'
    ),
    FILL_RATE_BY_CARRIER AS (
      QUESTION 'Does fill rate differ by carrier?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT DIMENSIONS order_fulfillment.carrier METRICS order_fulfillment.fill_rate_pct, order_fulfillment.otd_pct) ORDER BY fill_rate_pct ASC'
    ),
    PERFECT_ORDER_BY_FAMILY AS (
      QUESTION 'What is our perfect order rate by product family?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT DIMENSIONS order_fulfillment.product_family METRICS order_fulfillment.perfect_order_pct) ORDER BY perfect_order_pct ASC'
    ),
    DEFECT_REASONS_FOR_FAILED_LINES AS (
      QUESTION 'Why are our deliveries failing?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT DIMENSIONS order_fulfillment.defect_reason METRICS order_fulfillment.otd_pct) WHERE defect_reason IS NOT NULL ORDER BY otd_pct ASC'
    )
  );

CREATE OR REPLACE SEMANTIC VIEW SC_INVENTORY
  TABLES (
    INVENTORY as SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT primary key (SNAPSHOT_DATE, MATERIAL_ID, NODE_ID)
      with synonyms=('inventory','stock','position')
      comment='sco:InventoryPosition - month-end balance for one material at one node. Fact, snapshot grain. NOT additive across snapshot dates.'
  )
  FACTS (
    INVENTORY.ON_HAND as inventory.on_hand_qty comment='Units on hand.',
    INVENTORY.DAILY_DEMAND as inventory.avg_daily_demand comment='Average daily demand.',
    INVENTORY.VALUE as inventory.inventory_value comment='On-hand at standard cost.',
    INVENTORY.STOCKED_OUT as inventory.is_stocked_out comment='1 when nothing is available to promise.'
  )
  DIMENSIONS (
    INVENTORY.SNAPSHOT_DATE as inventory.snapshot_date with synonyms=('as of date','snapshot') comment='Month-end observed. Filter to one snapshot; never aggregate across them.',
    INVENTORY.PRODUCT_FAMILY as inventory.product_family with synonyms=('family') comment='Product family.',
    INVENTORY.ABC_CLASS as inventory.abc_class with synonyms=('abc','value class') comment='Inventory value class.',
    INVENTORY.NODE_NAME as inventory.node_name with synonyms=('site','warehouse') comment='Stocking location.',
    INVENTORY.NODE_REGION as inventory.node_region with synonyms=('network region') comment='Region the node serves.'
  )
  METRICS (
    INVENTORY.DAYS_OF_INVENTORY as SUM(inventory.on_hand) / NULLIF(SUM(inventory.daily_demand), 0)
      with synonyms=('days of inventory','days of cover','doi')
      comment='On-hand over average daily demand at one snapshot. Identical to INVENTORY.DAYS_OF_INVENTORY in SC_ONTOLOGY_360.',
    INVENTORY.INVENTORY_VALUE_USD as SUM(inventory.value)
      with synonyms=('inventory value','stock value')
      comment='On-hand at standard cost, at one snapshot. Never sum across snapshot dates.',
    INVENTORY.STOCKOUT_RATE as AVG(inventory.stocked_out)
      with synonyms=('stockout rate','out of stock rate')
      comment='Share of material-node positions with nothing available to promise.'
  )
  COMMENT = 'Inventory positions and cover. Domain-scoped subset of SC_ONTOLOGY_360; metric expressions are identical. Snapshot grain: not additive over time.'
  -- EVERY QUERY HERE IS WRITTEN PER SNAPSHOT, ON PURPOSE.
  --
  -- These are teaching examples as much as shortcuts. A snapshot is a balance, so
  -- aggregating across snapshot dates double-counts the same physical stock and
  -- produces a plausible number that is wrong by a factor of however many months
  -- are in range. Showing Cortex Analyst the QUALIFY-the-latest-snapshot pattern
  -- in every single verified query is more reliable than describing the rule in
  -- prose and hoping it generalises.
  AI_VERIFIED_QUERIES (
    DAYS_OF_INVENTORY_LATEST AS (
      QUESTION 'How many days of inventory are we holding?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date METRICS inventory.days_of_inventory) QUALIFY snapshot_date = MAX(snapshot_date) OVER ()'
    ),
    INVENTORY_VALUE_LATEST AS (
      QUESTION 'What is our inventory value?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date METRICS inventory.inventory_value_usd) QUALIFY snapshot_date = MAX(snapshot_date) OVER ()'
    ),
    DAYS_BY_ABC_CLASS_LATEST AS (
      QUESTION 'How does days of inventory differ by ABC class?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT abc_class, days_of_inventory FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date, inventory.abc_class METRICS inventory.days_of_inventory) QUALIFY snapshot_date = MAX(snapshot_date) OVER () ORDER BY abc_class'
    ),
    INVENTORY_VALUE_BY_NODE_LATEST AS (
      QUESTION 'Which locations hold the most inventory value?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT node_name, inventory_value_usd FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date, inventory.node_name METRICS inventory.inventory_value_usd) QUALIFY snapshot_date = MAX(snapshot_date) OVER () ORDER BY inventory_value_usd DESC'
    ),
    STOCKOUT_RATE_LATEST AS (
      QUESTION 'What share of our stocking positions are out of stock?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date METRICS inventory.stockout_rate) QUALIFY snapshot_date = MAX(snapshot_date) OVER ()'
    ),
    DAYS_BY_FAMILY_LATEST AS (
      QUESTION 'Which product families are overstocked?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT product_family, days_of_inventory FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY DIMENSIONS inventory.snapshot_date, inventory.product_family METRICS inventory.days_of_inventory) QUALIFY snapshot_date = MAX(snapshot_date) OVER () ORDER BY days_of_inventory DESC'
    )
  );

CREATE OR REPLACE SEMANTIC VIEW SC_LANDED_COST
  TABLES (
    LANDED_COST as SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT primary key (SHIPMENT_ID)
      with synonyms=('landed cost','freight','cost to serve')
      comment='sco:LandedCost - total delivered cost of one shipment. Fact, shipment grain.'
  )
  FACTS (
    LANDED_COST.TOTAL_COST as landed_cost.total_landed_cost comment='Material + freight + duty + handling.',
    LANDED_COST.UNITS as landed_cost.shipped_qty comment='Units shipped.',
    LANDED_COST.FREIGHT as landed_cost.freight_cost comment='Accrued freight.',
    LANDED_COST.FREIGHT_INVOICED as landed_cost.invoiced_freight_amt comment='Freight invoiced.',
    LANDED_COST.BILL_VARIANCE as landed_cost.freight_bill_var_amt comment='Invoiced less accrued.'
  )
  DIMENSIONS (
    LANDED_COST.CARRIER as landed_cost.carrier with synonyms=('carrier') comment='Carrier.',
    LANDED_COST.SHIP_REGION as landed_cost.ship_region with synonyms=('destination region') comment='Region delivered to.',
    LANDED_COST.SERVICE_LEVEL as landed_cost.service_level with synonyms=('service') comment='Committed service level.',
    LANDED_COST.PRODUCT_FAMILY as landed_cost.product_family with synonyms=('family') comment='Product family.',
    LANDED_COST.DELIVERY_DATE as landed_cost.delivery_date with synonyms=('delivered on') comment='Delivery date.'
  )
  METRICS (
    LANDED_COST.LANDED_COST_PER_UNIT as SUM(landed_cost.total_cost) / NULLIF(SUM(landed_cost.units), 0)
      with synonyms=('landed cost per unit','cost per unit')
      comment='Total landed cost over units shipped. A ratio of sums. Identical to LANDED_COST.LANDED_COST_PER_UNIT in SC_ONTOLOGY_360.',
    LANDED_COST.LANDED_COST_USD as SUM(landed_cost.total_cost)
      with synonyms=('landed cost','delivered cost') comment='Total landed cost.',
    LANDED_COST.FREIGHT_COST_USD as SUM(landed_cost.freight)
      with synonyms=('freight cost','accrued freight') comment='Accrued freight.',
    LANDED_COST.FREIGHT_INVOICED_USD as SUM(landed_cost.freight_invoiced)
      with synonyms=('freight invoiced','carrier billed') comment='Freight invoiced by carriers.',
    LANDED_COST.FREIGHT_BILL_VARIANCE_USD as SUM(landed_cost.bill_variance)
      with synonyms=('freight bill variance','overbilling') comment='Invoiced less accrued freight. A to-zero metric.'
  )
  COMMENT = 'Landed cost and freight billing. Domain-scoped subset of SC_ONTOLOGY_360; metric expressions are identical.'
  AI_VERIFIED_QUERIES (
    LANDED_COST_PER_UNIT_OVERALL AS (
      QUESTION 'What is our landed cost per unit?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST METRICS landed_cost.landed_cost_per_unit)'
    ),
    LANDED_COST_PER_UNIT_BY_CARRIER AS (
      QUESTION 'Which carriers cost us the most per unit?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST DIMENSIONS landed_cost.carrier METRICS landed_cost.landed_cost_per_unit) ORDER BY landed_cost_per_unit DESC'
    ),
    FREIGHT_VARIANCE_BY_CARRIER AS (
      QUESTION 'Are carriers overbilling us for freight?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST DIMENSIONS landed_cost.carrier METRICS landed_cost.freight_cost_usd, landed_cost.freight_invoiced_usd, landed_cost.freight_bill_variance_usd) ORDER BY freight_bill_variance_usd DESC'
    ),
    COST_BY_SERVICE_LEVEL AS (
      QUESTION 'How much more does expedited freight cost us?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST DIMENSIONS landed_cost.service_level METRICS landed_cost.landed_cost_per_unit, landed_cost.freight_cost_usd) ORDER BY landed_cost_per_unit DESC'
    ),
    LANDED_COST_BY_SHIP_REGION AS (
      QUESTION 'What does it cost to serve each destination region?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST DIMENSIONS landed_cost.ship_region METRICS landed_cost.landed_cost_per_unit, landed_cost.landed_cost_usd) ORDER BY landed_cost_per_unit DESC'
    )
  );

CREATE OR REPLACE SEMANTIC VIEW SC_DEMAND
  TABLES (
    FORECAST as SUPPLY_CHAIN.RAW.DEMAND_FORECAST primary key (MATERIAL_ID, PERIOD)
      with synonyms=('forecast','demand plan')
      comment='sco:DemandForecast - monthly forecast versus actual for one material. Fact, material-period grain.',
    PART as SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)
      with synonyms=('part','material','sku')
      comment='sco:Material - what is forecast. Conformed dimension.'
  )
  RELATIONSHIPS (
    DEMAND_TO_PART as FORECAST(MATERIAL_ID) references PART(MATERIAL_ID)
  )
  FACTS (
    FORECAST.FORECAST_UNITS as forecast.forecast_qty comment='Forecast quantity.',
    FORECAST.ACTUAL_UNITS as forecast.actual_qty comment='Realised quantity. Zero for periods that have not closed.'
  )
  DIMENSIONS (
    FORECAST.FORECAST_PERIOD as forecast.period with synonyms=('forecast month','yyyy-mm') comment='Forecast month as a YYYY-MM label.',
    PART.PRODUCT_FAMILY as part.product_family with synonyms=('family') comment='Product family.',
    PART.ABC_CLASS as part.abc_class with synonyms=('abc') comment='Inventory value class.'
  )
  METRICS (
    FORECAST.FORECAST_UNITS_TOTAL as SUM(forecast.forecast_units)
      with synonyms=('forecast units','planned demand') comment='Forecast quantity.',
    FORECAST.ACTUAL_UNITS_TOTAL as SUM(forecast.actual_units)
      with synonyms=('actual units','realised demand') comment='Realised quantity. Zero in open periods.',
    FORECAST.FORECAST_ACCURACY as 1 - ABS(SUM(forecast.actual_units) - SUM(forecast.forecast_units)) / NULLIF(SUM(forecast.forecast_units), 0)
      with synonyms=('forecast accuracy','demand accuracy')
      comment='One minus absolute error over forecast. Include only closed periods: an open period has a zero actual and would read as total inaccuracy.'
  )
  COMMENT = 'Demand forecast versus actual. Domain-scoped view for the conversational layer.'
  AI_VERIFIED_QUERIES (
    FORECAST_ACCURACY_OVERALL AS (
      QUESTION 'How accurate is our demand forecast?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      -- Filters on the FACT forecast.actual_units, not the metric
      -- forecast.actual_units_total. A semantic-view WHERE clause accepts only a
      -- DIMENSION or a FACT; referencing a metric there fails with "must be one of
      -- the following types: (DIMENSION, FACT)". The filter matters either way:
      -- an open period carries a zero actual and would read as total inaccuracy.
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_DEMAND METRICS forecast.forecast_accuracy WHERE forecast.actual_units > 0)'
    ),
    FORECAST_ACCURACY_BY_FAMILY AS (
      QUESTION 'Which product families are hardest to forecast?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_DEMAND DIMENSIONS part.product_family METRICS forecast.forecast_accuracy) ORDER BY forecast_accuracy ASC'
    ),
    FORECAST_VS_ACTUAL_BY_PERIOD AS (
      QUESTION 'How has forecast accuracy moved month by month?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_DEMAND DIMENSIONS forecast.forecast_period METRICS forecast.forecast_units_total, forecast.actual_units_total) ORDER BY forecast_period'
    )
  );

CREATE OR REPLACE SEMANTIC VIEW SC_MANUFACTURING
  TABLES (
    PRODUCTION_ORDER as SUPPLY_CHAIN.RAW.PRODUCTION_ORDER primary key (PRODUCTION_ORDER_ID)
      with synonyms=('production order','work order','build')
      comment='sco:ProductionOrder - one manufacturing completion. Fact, order grain.',
    PART as SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)
      with synonyms=('part','material') comment='sco:Material - what was produced. Conformed dimension.',
    NODE as SUPPLY_CHAIN.RAW.NODE primary key (NODE_ID)
      with synonyms=('plant','site') comment='sco:Location - where it was produced. Conformed dimension.'
  )
  RELATIONSHIPS (
    MFG_TO_PART as PRODUCTION_ORDER(MATERIAL_ID) references PART(MATERIAL_ID),
    MFG_TO_NODE as PRODUCTION_ORDER(NODE_ID) references NODE(NODE_ID)
  )
  FACTS (
    PRODUCTION_ORDER.COMPLETED as production_order.completed_qty comment='Good units completed.',
    PRODUCTION_ORDER.SCRAP as production_order.scrap_qty comment='Units scrapped.',
    PRODUCTION_ORDER.PLANNED as production_order.planned_qty comment='Units planned.'
  )
  DIMENSIONS (
    PRODUCTION_ORDER.COMPLETED_DATE as production_order.completed_date with synonyms=('completion date') comment='Date production completed.',
    PART.PRODUCT_FAMILY as part.product_family with synonyms=('family') comment='Product family.',
    NODE.NODE_NAME as node.node_name with synonyms=('plant','site') comment='Producing plant.',
    NODE.NODE_REGION as node.node_region with synonyms=('region') comment='Region of the plant.'
  )
  METRICS (
    PRODUCTION_ORDER.PRODUCTION_COMPLETED_UNITS as SUM(production_order.completed)
      with synonyms=('units produced','output') comment='Good units completed.',
    PRODUCTION_ORDER.SCRAP_RATE as SUM(production_order.scrap) / NULLIF(SUM(production_order.planned), 0)
      with synonyms=('scrap rate','yield loss')
      comment='Scrapped over planned units. A ratio of sums, not an average of per-order rates.',
    PRODUCTION_ORDER.SCHEDULE_ADHERENCE as AVG(IFF(production_order.completed_date <= production_order.scheduled_date, 1, 0))
      with synonyms=('schedule adherence','on-time completion')
      comment='Share of production orders completed by the scheduled date.'
  )
  COMMENT = 'Manufacturing output and scrap. Domain-scoped view for the conversational layer.'
  AI_VERIFIED_QUERIES (
    SCRAP_RATE_BY_PLANT AS (
      QUESTION 'Which plants have the highest scrap rate?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING DIMENSIONS node.node_name METRICS production_order.scrap_rate, production_order.production_completed_units) ORDER BY scrap_rate DESC'
    ),
    SCHEDULE_ADHERENCE_OVERALL AS (
      QUESTION 'Are we completing production orders on schedule?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING METRICS production_order.schedule_adherence)'
    )
  );

-- ---------------------------------------------------------------------------
-- SC_SUPPLIER_LEGACY_DEFECT — the negative control. DELIBERATELY WRONG.
--
-- This view reproduces the average-of-averages bug on purpose, and must never be
-- fixed. Its whole function is to prove METRIC_DRIFT_TEST can fail: a control that
-- only ever passes is indistinguishable from a control that is not running, and
-- 06_drift_notification.sql binds this view specifically to demonstrate a failing
-- run end to end, including the alert and the email.
--
-- THE BUG. It reads V_SUPPLIER_OTD_BY_MONTH, where on-time rate is already
-- averaged per supplier per month, and then takes an unweighted AVG of those
-- rates. A supplier with three receipt lines in a month therefore carries the same
-- weight as one with nine hundred. The correct metric — every other supplier view
-- here — averages the 1/0 flag across receipt lines, so each line counts once.
--
-- This is the single most common way a governed metric silently diverges: both
-- numbers are called "supplier OTD", both are plausible, and nothing in a
-- dashboard reveals which weighting produced which.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW SUPPLY_CHAIN.CANONICAL.V_SUPPLIER_OTD_BY_MONTH
  COMMENT = 'Supplier on-time rate pre-aggregated per supplier per month. Exists ONLY to back SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT, the deliberately-defective negative control. Do not build a governed metric on this: averaging a rate that is already a rate discards line weighting.'
AS
SELECT
  supplier_id,
  supplier_name,
  supplier_region,
  DATE_TRUNC('MONTH', receipt_date)          AS month_start,
  AVG(is_on_time)                            AS otd_rate,
  COUNT(*)                                   AS line_count
FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE
GROUP BY supplier_id, supplier_name, supplier_region, DATE_TRUNC('MONTH', receipt_date);

CREATE OR REPLACE SEMANTIC VIEW SC_SUPPLIER_LEGACY_DEFECT
  TABLES (
    SUPPLIER as SUPPLY_CHAIN.CANONICAL.V_SUPPLIER_OTD_BY_MONTH primary key (SUPPLIER_ID, MONTH_START)
      with synonyms=('supplier','vendor')
      comment='sco:Supplier - supplier-month pre-aggregate. Fact, supplier-month grain. NOT receipt-line grain, which is the source of the defect this view exists to demonstrate.'
  )
  FACTS (
    SUPPLIER.MONTHLY_OTD_RATE as supplier.otd_rate comment='On-time rate for one supplier in one month. Already a rate: averaging it again loses line weighting.',
    SUPPLIER.LINES as supplier.line_count comment='Receipt lines behind the monthly rate. The weight the defective metric ignores.'
  )
  DIMENSIONS (
    SUPPLIER.SUPPLIER_NAME as supplier.supplier_name with synonyms=('vendor') comment='Vendor name.',
    SUPPLIER.SUPPLIER_REGION as supplier.supplier_region with synonyms=('region') comment='Sourcing region.',
    SUPPLIER.MONTH_START as supplier.month_start with synonyms=('month') comment='Month of the pre-aggregate.'
  )
  METRICS (
    SUPPLIER.SUPPLIER_OTD_PCT as AVG(supplier.monthly_otd_rate)
      with synonyms=('supplier on-time delivery','inbound otd')
      comment='DEFECTIVE ON PURPOSE. Unweighted average of per-supplier-per-month on-time rates, so a supplier with 3 receipt lines counts as much as one with 900. The governed definition averages the 1/0 flag across receipt lines. Kept as a negative control to prove the drift test can fail; never fix it.'
  )
  COMMENT = 'NEGATIVE CONTROL - DELIBERATELY DEFECTIVE. Reproduces the average-of-averages bug for supplier OTD so that METRIC_DRIFT_TEST is demonstrably capable of failing. Not bound to any persona and never used for reporting.';

-- ---------------------------------------------------------------------------
-- Persona access. Per view, so a persona sees only its domain.
--
-- REFERENCES is required alongside SELECT: Cortex Analyst reads the view's
-- metadata to resolve a question before it runs anything, and SELECT alone leaves
-- it unable to see the metric list.
--
-- SC_SUPPLIER_LEGACY_DEFECT is granted to nobody. It is bound in
-- METRIC_BINDING under the NEGATIVE_CONTROL persona so the drift test reaches it
-- with owner's rights, and no human persona should ever be able to query it.
-- ---------------------------------------------------------------------------

