-- ---------------------------------------------------------------------------
-- Drift results.
--
-- RUN_ID IS THE KEY, NOT RUN_AT. lib/sc.ts selects a run by RUN_ID
-- (getLatestDrift) because an earlier version selected every row written within
-- 30 seconds of the newest, which silently merged two overlapping runs and could
-- split one run that straddled the boundary. The procedure stamps one UUID per
-- invocation, so a run is exactly identifiable.
--
-- RELATIVE_SPREAD, not absolute, is what the status is judged on. An absolute
-- spread of 50 is nothing on a $40M landed-cost total and catastrophic on an OTD
-- ratio, so a single absolute tolerance cannot serve both.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE METRIC_DRIFT_RESULT (
  run_id          STRING NOT NULL COMMENT 'One UUID per invocation of METRIC_DRIFT_TEST. Select a run by this, never by a time window.',
  run_at          TIMESTAMP_LTZ NOT NULL COMMENT 'When the run started.',
  metric_id       STRING NOT NULL COMMENT 'Metric checked.',
  business_name   STRING NOT NULL COMMENT 'Business name, copied so a result is readable without joining.',
  binding_count   NUMBER NOT NULL COMMENT 'Number of semantic-view bindings compared. A count of 1 means the metric is not actually testable.',
  canonical_value FLOAT           COMMENT 'Value from CANONICAL_SQL: the independent second opinion.',
  min_value       FLOAT           COMMENT 'Lowest value across the canonical value and all bindings.',
  max_value       FLOAT           COMMENT 'Highest value across the canonical value and all bindings.',
  value_spread    FLOAT           COMMENT 'max_value - min_value, in the metric unit.',
  relative_spread FLOAT           COMMENT 'value_spread / ABS(canonical_value). What the status is judged on, so that one tolerance works across ratios and dollar totals.',
  status          STRING NOT NULL COMMENT 'PASS, FAIL, or ERROR when a binding could not be evaluated.',
  detail          STRING          COMMENT 'Per-binding values, or the error, in readable form.'
) COMMENT = 'One row per metric per drift-test run. The track record of the control, not just its current state.';

CREATE OR REPLACE TABLE METRIC_DRIFT_BASELINE (
  metric_id       STRING COMMENT 'Metric that was diverging.',
  semantic_view   STRING COMMENT 'View the value came from.',
  metric_reference STRING COMMENT 'Metric reference inside that view.',
  observed_value  FLOAT  COMMENT 'Value observed at the time.',
  definition_sql  STRING COMMENT 'Expression that produced it.',
  root_cause      STRING COMMENT 'Why the two definitions disagreed.',
  captured_at     TIMESTAMP_LTZ COMMENT 'When the divergence was recorded.',
  note            STRING COMMENT 'What was done about it.'
) COMMENT = 'The recorded before-state: two views reporting different numbers for supplier OTD. Kept so the /consistency page can show the problem this project fixed, not merely assert that it is fixed.';

CREATE OR REPLACE TABLE METRIC_DRIFT_NEGATIVE_CONTROL (
  run_at          TIMESTAMP_LTZ COMMENT 'When the control was exercised.',
  metric_id       STRING COMMENT 'Metric used.',
  business_name   STRING COMMENT 'Business name.',
  canonical_value FLOAT  COMMENT 'Correct, line-weighted value.',
  min_value       FLOAT  COMMENT 'Lowest value across bindings.',
  max_value       FLOAT  COMMENT 'Highest value across bindings.',
  value_spread    FLOAT  COMMENT 'Observed disagreement.',
  status          STRING COMMENT 'Expected to be FAIL. A PASS here would mean the control is not working.',
  detail          STRING COMMENT 'The competing values.',
  purpose         STRING COMMENT 'Why this row exists.'
) COMMENT = 'Evidence that METRIC_DRIFT_TEST is capable of failing. A control that has only ever passed is indistinguishable from one that is not running.';

-- ---------------------------------------------------------------------------
-- METRIC_DRIFT_TEST — the control itself.
--
-- For each metric: evaluate CANONICAL_SQL, evaluate every binding through
-- SEMANTIC_VIEW(...), and compare all of them. PASS requires the relative spread
-- to be within tolerance.
--
-- HOW THE BINDING QUERY IS BUILT. A semantic-view query returns its metric in a
-- column named after the last segment of the reference, so
-- `landed_cost.landed_cost_per_unit` yields a column LANDED_COST_PER_UNIT. The
-- procedure aliases that to VAL, matching the shape CANONICAL_SQL is required to
-- return, so both sides can be fetched by the same code path.
--
-- SCOPE IS DELIBERATELY ALL-HISTORY AND UNFILTERED. No period, and no exclusion
-- of future-dated rows. This looks inconsistent with 02_as_of_rule.sql, which
-- requires the application to exclude future rows -- and the difference is the
-- point: this test asks whether two definitions agree, not whether a reporting
-- period is right. Narrowing the scope would shrink the row population the
-- comparison runs over and weaken the test for no gain.
--
-- A FAILING BINDING DOES NOT ABORT THE RUN. Each binding is wrapped so that an
-- error is recorded as ERROR against that metric and the loop continues. A run
-- that stops at the first broken metric reports nothing about the other thirteen,
-- which is the opposite of what a control is for.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE PROCEDURE METRIC_DRIFT_TEST(TOLERANCE FLOAT)
RETURNS TABLE()
LANGUAGE SQL
COMMENT = 'Compares every semantic-view binding of every governed metric against the metric CANONICAL_SQL. Writes one row per metric to METRIC_DRIFT_RESULT under a single RUN_ID and returns that run. TOLERANCE is a relative spread.'
AS $$
DECLARE
  v_run_id    STRING;
  v_run_at    TIMESTAMP_LTZ;
  v_canon     FLOAT;
  v_min       FLOAT;
  v_max       FLOAT;
  v_n         NUMBER;
  v_detail    STRING;
  v_status    STRING;
  v_spread    FLOAT;
  v_rel       FLOAT;
  v_sql       STRING;
  v_val       FLOAT;
  -- Loop fields must be copied into locals before use as binds: Snowflake
  -- Scripting does not accept a qualified loop variable (:m.metric_id) as a bind
  -- inside a SQL statement, only a plain local (:v_mid).
  v_mid       STRING;
  v_bname     STRING;
  v_csql      STRING;
  v_view      STRING;
  v_ref       STRING;
  res         RESULTSET;
  metrics CURSOR FOR
    SELECT metric_id, business_name, canonical_sql
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
     ORDER BY metric_id;
BEGIN
  v_run_id := UUID_STRING();
  v_run_at := CURRENT_TIMESTAMP();

  FOR m IN metrics DO
    v_mid    := m.metric_id;
    v_bname  := m.business_name;
    v_csql   := m.canonical_sql;
    v_canon  := NULL;
    v_min    := NULL;
    v_max    := NULL;
    v_n      := 0;
    v_detail := '';
    v_status := 'PASS';

    -- The canonical value. If this fails the metric is unusable, so record ERROR
    -- and move on rather than letting one bad registry row end the run.
    BEGIN
      v_sql := v_csql;
      LET cres RESULTSET := (EXECUTE IMMEDIATE :v_sql);
      LET ccur CURSOR FOR cres;
      OPEN ccur;
      FETCH ccur INTO v_val;
      CLOSE ccur;
      v_canon  := v_val;
      v_min    := v_val;
      v_max    := v_val;
      v_detail := 'canonical=' || COALESCE(TO_VARCHAR(v_canon), 'NULL');
    EXCEPTION
      WHEN OTHER THEN
        v_status := 'ERROR';
        v_detail := 'canonical_sql failed: ' || SQLERRM;
    END;

    IF (v_status <> 'ERROR') THEN
      LET bres RESULTSET := (
        SELECT semantic_view, metric_reference
          FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING
         WHERE metric_id = :v_mid
         ORDER BY semantic_view, metric_reference
      );
      LET bcur CURSOR FOR bres;
      FOR b IN bcur DO
        v_view := b.semantic_view;
        v_ref  := b.metric_reference;
        BEGIN
          -- Alias the metric column to VAL so both sides fetch identically.
          v_sql := 'SELECT ' || UPPER(SPLIT_PART(v_ref, '.', 2))
                   || ' AS VAL FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.'
                   || v_view || ' METRICS ' || v_ref || ')';
          LET vres RESULTSET := (EXECUTE IMMEDIATE :v_sql);
          LET vcur CURSOR FOR vres;
          OPEN vcur;
          FETCH vcur INTO v_val;
          CLOSE vcur;
          v_n      := v_n + 1;
          v_min    := LEAST(COALESCE(v_min, v_val), COALESCE(v_val, v_min));
          v_max    := GREATEST(COALESCE(v_max, v_val), COALESCE(v_val, v_max));
          v_detail := v_detail || ' | ' || v_view || '.'
                      || SPLIT_PART(v_ref, '.', 2) || '='
                      || COALESCE(TO_VARCHAR(v_val), 'NULL');
        EXCEPTION
          WHEN OTHER THEN
            v_status := 'ERROR';
            v_detail := v_detail || ' | ' || v_view || ' FAILED: ' || SQLERRM;
        END;
      END FOR;
    END IF;

    v_spread := CASE WHEN v_min IS NULL OR v_max IS NULL THEN NULL ELSE v_max - v_min END;
    v_rel    := CASE WHEN v_spread IS NULL OR v_canon IS NULL OR ABS(v_canon) = 0
                     THEN v_spread ELSE v_spread / ABS(v_canon) END;

    IF (v_status <> 'ERROR') THEN
      -- A metric bound only once has nothing to disagree with. Saying PASS would
      -- overstate what was verified, so it is called out explicitly.
      IF (v_n < 2) THEN
        v_status := 'UNTESTED';
        v_detail := v_detail || ' | only ' || v_n || ' binding: nothing to compare against';
      ELSEIF (COALESCE(v_rel, 0) > :TOLERANCE) THEN
        v_status := 'FAIL';
      ELSE
        v_status := 'PASS';
      END IF;
    END IF;

    INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
      (run_id, run_at, metric_id, business_name, binding_count,
       canonical_value, min_value, max_value, value_spread, relative_spread, status, detail)
    SELECT :v_run_id, :v_run_at, :v_mid, :v_bname, :v_n,
           :v_canon, :v_min, :v_max, :v_spread, :v_rel, :v_status, :v_detail;
  END FOR;

  res := (
    SELECT metric_id, business_name, binding_count, canonical_value,
           value_spread, relative_spread, status, detail, run_at, run_id
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
     WHERE run_id = :v_run_id
     ORDER BY status DESC, metric_id
  );
  RETURN TABLE(res);
END;
$$;

-- Zero-argument overload. lib/sc.ts and components/drift-runner.tsx both call
-- METRIC_DRIFT_TEST() with no arguments, and 04/06/07/08 do the same.
-- Tolerance 1e-6: bindings that share an expression agree exactly, so anything
-- looser would let a genuine rounding divergence pass unnoticed.
CREATE OR REPLACE PROCEDURE METRIC_DRIFT_TEST()
RETURNS TABLE()
LANGUAGE SQL
COMMENT = 'Runs METRIC_DRIFT_TEST with a relative tolerance of 1e-6.'
AS $$
DECLARE
  res RESULTSET;
BEGIN
  CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST(0.000001);
  res := (
    SELECT metric_id, business_name, binding_count, canonical_value,
           value_spread, relative_spread, status, detail, run_at, run_id
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
     WHERE run_id = (SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
                      ORDER BY run_at DESC LIMIT 1)
     ORDER BY status DESC, metric_id
  );
  RETURN TABLE(res);
END;
$$;

-- ---------------------------------------------------------------------------
-- Ontology catalogue.
--
-- VIEWS OVER INFORMATION_SCHEMA, NOT TABLES. This is the whole design: the
-- catalogue rendered on /ontology is derived from the deployed semantic views, so
-- it is structurally incapable of drifting from them. A table would need to be
-- maintained alongside every view change, and the first missed update would make
-- the page describe an ontology that no longer exists.
--
-- ONTOLOGY_CLASS and ENTITY_ROLE are parsed out of the entity comment -- the
-- 'sco:' token and the exact phrase 'Conformed dimension.' respectively. That is
-- why 00e's comments are worded the way they are, and why 01 insists on the same
-- phrasing for CALENDAR.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW ONTOLOGY_ENTITY
  COMMENT = 'Entities of each semantic view, derived from INFORMATION_SCHEMA so the catalogue cannot drift from the deployed definition. ONTOLOGY_CLASS and ENTITY_ROLE are parsed from the entity comment.'
AS
SELECT
  t.semantic_view_name                                             AS semantic_view,
  t.name                                                           AS entity,
  NULLIF(REGEXP_SUBSTR(t.comment, 'sco:([A-Za-z]+)', 1, 1, 'e', 1), '') AS ontology_class,
  -- 'DIMENSION', NOT 'CONFORMED_DIMENSION'. app/ontology/page.tsx:25 filters
  --   entities.filter((e) => e.entityRole === "DIMENSION")
  -- to count the conformed dimensions for its stat tile. Emitting
  -- 'CONFORMED_DIMENSION' here -- which reads better and is what the comment
  -- phrase literally says -- made that filter match nothing, so /ontology
  -- displayed "Conformed dimensions 0" while the catalogue table directly below
  -- it tagged five entities as conformed. Nothing failed; the page just quietly
  -- contradicted itself, and only a visual check caught it.
  --
  -- 01_calendar_dimension.sql assumes the same two values: its header warns that
  -- wording a comment as "conformed time dimension" classifies CALENDAR "as a
  -- bare ENTITY instead", i.e. not as the DIMENSION this expression produces.
  IFF(t.comment ILIKE '%Conformed dimension.%', 'DIMENSION', 'FACT')  AS entity_role,
  t.base_table_catalog || '.' || t.base_table_schema || '.' || t.base_table_name AS base_object,
  t.primary_keys,
  t.synonyms,
  t.comment                                                        AS description,
  (SELECT COUNT(*) FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_DIMENSIONS d
    WHERE d.semantic_view_name = t.semantic_view_name AND d.table_name = t.name) AS dimension_count,
  (SELECT COUNT(*) FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_METRICS mt
    WHERE mt.semantic_view_name = t.semantic_view_name AND mt.table_name = t.name) AS metric_count
FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_TABLES t;

CREATE OR REPLACE VIEW ONTOLOGY_RELATIONSHIP
  COMMENT = 'Relationships of each semantic view, derived from INFORMATION_SCHEMA. The join graph as deployed, not as documented.'
AS
SELECT
  r.semantic_view_name AS semantic_view,
  r.name               AS relationship_name,
  r.table_name         AS from_entity,
  r.ref_table_name     AS to_entity,
  r.foreign_keys       AS from_columns,
  r.ref_keys           AS to_columns
FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_RELATIONSHIPS r;

-- ---------------------------------------------------------------------------
-- Personas.
--
-- PERSONA_VIEW_ACCESS MUST MIRROR THE ACTUAL GRANTS IN 00e. The application reads
-- this table to decide which views to offer a persona; if it lists a view the
-- role cannot query, /ask offers a tool that fails at run time. 19 rows here, and
-- 19 GRANT statements at the end of 00e.
--
-- PERSONA_CATALOG is a view, for the same reason the ontology catalogue is: it
-- derives accessible_semantic_views and view_count from PERSONA_VIEW_ACCESS, so
-- the count on screen cannot disagree with the list beside it.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PERSONA_DEFINITION (
  role_name     STRING NOT NULL COMMENT 'Snowflake role the application assumes for this persona.',
  persona_label STRING NOT NULL COMMENT 'Display name.',
  focus         STRING NOT NULL COMMENT 'What this persona is accountable for.',
  sort_order    NUMBER NOT NULL COMMENT 'Display order.',
  row_scope     STRING NOT NULL COMMENT 'Row scope in words. MUST be the exact literal "ALL REGIONS" for an unrestricted persona: app/api/consistency/route.ts compares against that string to decide which personas are comparable. Anything else, and the metric reads as UNPROVEN.',
  CONSTRAINT pk_persona_definition PRIMARY KEY (role_name)
) COMMENT = 'The personas the application can assume. One row per Snowflake role.';

-- ROW_SCOPE IS A STRING THE APPLICATION MATCHES ON, NOT FREE TEXT.
-- app/api/consistency/route.ts:77 keeps only personas whose rowScope equals the
-- literal 'ALL REGIONS' when judging whether the personas agree, because a
-- row-scoped persona legitimately returns a different number without the
-- definition having changed.
--
-- This was first seeded as 'ALL_ROWS', which reads identically to a human and is
-- invisible to every SQL assertion. The effect was that no persona qualified as
-- comparable, so /consistency observed zero values and reported the metric
-- UNPROVEN -- on the one page whose entire purpose is to prove the numbers agree.
-- 91_verify_personas.sql now asserts the exact literal.
INSERT INTO PERSONA_DEFINITION (role_name, persona_label, focus, sort_order, row_scope)
SELECT * FROM VALUES
 ('SC_ONTOLOGY_STEWARD','Ontology Steward','Owns the semantic layer. The only persona that sees every view, the drift control and the consistency evidence.',1,'ALL REGIONS'),
 ('SC_PROCUREMENT','Procurement Analyst','Supplier delivery, fill and purchase price variance on the inbound side.',2,'ALL REGIONS'),
 ('SC_LOGISTICS','Logistics Manager','Outbound delivery performance and cost to serve, all regions.',3,'ALL REGIONS'),
 ('SC_LOGISTICS_EU','Logistics Manager, EU','The same accountability as SC_LOGISTICS, restricted to EU destinations. Same metric definitions, different rows.',4,'SHIP_REGION = EU'),
 ('SC_PLANNER','Demand & Inventory Planner','Inventory cover, stock value and demand plan accuracy.',5,'ALL REGIONS')
AS v(role_name, persona_label, focus, sort_order, row_scope);

CREATE OR REPLACE TABLE PERSONA_VIEW_ACCESS (
  role_name     STRING NOT NULL COMMENT 'Persona role.',
  semantic_view STRING NOT NULL COMMENT 'Semantic view the role may query. Must correspond to an actual GRANT in 00e.',
  CONSTRAINT pk_persona_view_access PRIMARY KEY (role_name, semantic_view)
) COMMENT = 'Which semantic views each persona may query. Mirrors the grants issued in 00e: a row here with no matching grant makes the conversational layer offer a tool that fails.';

INSERT INTO PERSONA_VIEW_ACCESS (role_name, semantic_view)
SELECT * FROM VALUES
 ('SC_ONTOLOGY_STEWARD','SC_ONTOLOGY_360'),
 ('SC_ONTOLOGY_STEWARD','SC_SUPPLIER'),
 ('SC_ONTOLOGY_STEWARD','SC_FULFILLMENT'),
 ('SC_ONTOLOGY_STEWARD','SC_INVENTORY'),
 ('SC_ONTOLOGY_STEWARD','SC_LANDED_COST'),
 ('SC_ONTOLOGY_STEWARD','SC_DEMAND'),
 ('SC_ONTOLOGY_STEWARD','SC_MANUFACTURING'),
 ('SC_PROCUREMENT','SC_ONTOLOGY_360'),
 ('SC_PROCUREMENT','SC_SUPPLIER'),
 ('SC_LOGISTICS','SC_ONTOLOGY_360'),
 ('SC_LOGISTICS','SC_FULFILLMENT'),
 ('SC_LOGISTICS','SC_LANDED_COST'),
 ('SC_LOGISTICS_EU','SC_ONTOLOGY_360'),
 ('SC_LOGISTICS_EU','SC_FULFILLMENT'),
 ('SC_LOGISTICS_EU','SC_LANDED_COST'),
 ('SC_PLANNER','SC_ONTOLOGY_360'),
 ('SC_PLANNER','SC_INVENTORY'),
 ('SC_PLANNER','SC_DEMAND'),
 ('SC_PLANNER','SC_FULFILLMENT')
AS v(role_name, semantic_view);

CREATE OR REPLACE VIEW PERSONA_CATALOG
  COMMENT = 'The persona catalogue with its accessible-view list and count derived from PERSONA_VIEW_ACCESS, so the count shown can never disagree with the list shown beside it.'
AS
SELECT
  p.role_name,
  p.persona_label,
  p.focus,
  p.sort_order,
  p.row_scope,
  (SELECT LISTAGG(a.semantic_view, ', ') WITHIN GROUP (ORDER BY a.semantic_view)
     FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_VIEW_ACCESS a WHERE a.role_name = p.role_name) AS accessible_semantic_views,
  (SELECT COUNT(*) FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_VIEW_ACCESS a WHERE a.role_name = p.role_name) AS view_count
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_DEFINITION p;

-- ---------------------------------------------------------------------------
-- Regional row scoping.
--
-- DRIVEN BY A MAPPING TABLE, NOT BY A ROLE NAME IN THE POLICY BODY. Hardcoding
-- `CURRENT_ROLE() = 'SC_LOGISTICS_EU'` would mean every new regional persona
-- requires a policy change, and a policy change is a privileged operation that
-- silently affects every attached table. With the mapping table, adding an APAC
-- persona is an INSERT that is reviewable like any other governance row.
--
-- The three-branch logic matters:
--   scoped role, region matches   -> visible
--   scoped role, region does not  -> hidden
--   role not scoped at all        -> everything visible
-- Collapsing the last two would hide every row from every unscoped role, which
-- looks exactly like a broken warehouse rather than a policy mistake.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PERSONA_REGION_SCOPE (
  role_name    STRING NOT NULL COMMENT 'Role to restrict.',
  region_value STRING NOT NULL COMMENT 'Region value the role may see. A role absent from this table sees all regions.',
  CONSTRAINT pk_persona_region_scope PRIMARY KEY (role_name, region_value)
) COMMENT = 'Row-scope mapping consumed by RAP_SHIP_REGION. Adding a regional persona is an INSERT here, not a policy edit.';

INSERT INTO PERSONA_REGION_SCOPE (role_name, region_value)
SELECT * FROM VALUES ('SC_LOGISTICS_EU','EU') AS v(role_name, region_value);

-- DETACH BEFORE REPLACING. Snowflake refuses to replace a row access policy that
-- is still attached to anything: "Policy RAP_SHIP_REGION cannot be dropped/
-- replaced as it is associated with one or more entities."
--
-- So the order is detach, replace, re-attach. An earlier version of this file put
-- the CREATE OR REPLACE first and the detach afterwards, which worked on a fresh
-- account and failed on every subsequent run -- the worst shape of bug for a
-- script whose whole purpose is to be re-runnable.
--
-- DROP ALL rather than DROP <name> so this is safe whether a policy is attached or
-- not, and regardless of which one. A table may carry only one row access policy,
-- so there is nothing else to preserve.
ALTER TABLE SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT DROP ALL ROW ACCESS POLICIES;
ALTER TABLE SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT   DROP ALL ROW ACCESS POLICIES;

CREATE OR REPLACE ROW ACCESS POLICY RAP_SHIP_REGION
  AS (ship_region STRING) RETURNS BOOLEAN ->
    CASE
      WHEN EXISTS (
        SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_REGION_SCOPE s
         WHERE s.role_name = CURRENT_ROLE() AND s.region_value = ship_region
      ) THEN TRUE
      WHEN EXISTS (
        SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_REGION_SCOPE s
         WHERE s.role_name = CURRENT_ROLE()
      ) THEN FALSE
      ELSE TRUE
    END
  COMMENT = 'Restricts outbound rows by destination region for roles listed in PERSONA_REGION_SCOPE. Roles not listed are unrestricted.';

ALTER TABLE SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
  ADD ROW ACCESS POLICY RAP_SHIP_REGION ON (SHIP_REGION);
ALTER TABLE SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT
  ADD ROW ACCESS POLICY RAP_SHIP_REGION ON (SHIP_REGION);

-- ---------------------------------------------------------------------------
-- Agent feedback loop.
--
-- AGENT_QUESTION_LOG is created here rather than in 07 because
-- AGENT_IMPROVEMENT_CANDIDATE reads it and 00f runs first. 07 creates it with
-- CREATE TABLE IF NOT EXISTS, so it is a no-op there once this has run.
--
-- The ranking puts an UNSTABLE_RESOLUTION first: the same question answered two
-- different ways is the exact failure this project exists to prevent, showing up
-- in the conversational layer. A refusal is second -- it is a worse experience but
-- an honest one.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE AGENT_QUESTION_LOG (
  asked_at            TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  source              STRING  COMMENT 'Which surface asked: app, agent, evaluation harness.',
  persona_role        STRING  COMMENT 'Role in effect.',
  question            STRING  COMMENT 'Question as asked.',
  resolved_metric_ids STRING  COMMENT 'Pipe-delimited metric ids resolved to.',
  semantic_view       STRING  COMMENT 'View chosen.',
  refused             BOOLEAN COMMENT 'TRUE when the question was declined.',
  refusal_reason      STRING  COMMENT 'Why it was declined.',
  latency_ms          NUMBER  COMMENT 'End-to-end latency.',
  user_corrected      BOOLEAN COMMENT 'TRUE when the user corrected the answer.',
  correction_note     STRING  COMMENT 'What the user said was wrong.'
) COMMENT = 'Every question asked of the conversational layer. Real questions are a better source of the next synonym or verified query than imagined ones.';

CREATE OR REPLACE VIEW AGENT_IMPROVEMENT_CANDIDATE
  COMMENT = 'Questions ranked by how much they need attention. An unstable resolution ranks above a refusal: being answered two different ways is worse than not being answered.'
AS
WITH agg AS (
  SELECT
    question,
    COUNT(*)                                           AS times_asked,
    COUNT(DISTINCT COALESCE(resolved_metric_ids, ''))   AS distinct_resolutions,
    COUNT_IF(refused)                                   AS refusals,
    COUNT_IF(user_corrected)                            AS corrections,
    MAX(asked_at)                                       AS last_asked
  FROM SUPPLY_CHAIN.GOVERNANCE.AGENT_QUESTION_LOG
  GROUP BY question
)
SELECT
  question, times_asked, distinct_resolutions, refusals, corrections, last_asked,
  CASE
    WHEN distinct_resolutions > 1 THEN 'UNSTABLE_RESOLUTION'
    WHEN refusals > 0            THEN 'REFUSED'
    WHEN corrections > 0         THEN 'USER_CORRECTED'
    ELSE 'OK'
  END AS candidate_reason,
  CASE
    WHEN distinct_resolutions > 1 THEN 1
    WHEN refusals > 0            THEN 2
    WHEN corrections > 0         THEN 3
    ELSE 4
  END AS priority
FROM agg;

-- ---------------------------------------------------------------------------
-- Seed the evidence tables from the live views.
--
-- COMPUTED, NOT TYPED IN. Both tables are populated by querying the correct and
-- the deliberately-defective views right now, rather than by inserting literals
-- recorded from some earlier run. Hardcoded evidence is evidence that can quietly
-- become false: if the data is regenerated with different distributions, a typed
-- "observed_value" would still be displayed on /consistency as though it had been
-- measured. Deriving it means the numbers shown are always the numbers this
-- account actually produces.
--
-- The divergence being recorded is real and reproducible: SC_SUPPLIER computes
-- supplier OTD across receipt lines, SC_SUPPLIER_LEGACY_DEFECT averages
-- per-supplier-per-month rates, and the two disagree by roughly 0.7 percentage
-- points on identical underlying data.
-- ---------------------------------------------------------------------------

TRUNCATE TABLE METRIC_DRIFT_BASELINE;

INSERT INTO METRIC_DRIFT_BASELINE
  (metric_id, semantic_view, metric_reference, observed_value, definition_sql, root_cause, captured_at, note)
SELECT
  'supplier_otd_pct', 'SC_SUPPLIER', 'supplier_delivery.supplier_otd_pct',
  (SELECT supplier_otd_pct FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER METRICS supplier_delivery.supplier_otd_pct)),
  'AVG(is_on_time) over CANONICAL.FCT_SUPPLIER_DELIVERY_LINE',
  'Correct definition: averages the on-time flag across receipt lines, so every line carries equal weight.',
  CURRENT_TIMESTAMP(),
  'This is the governed definition. Retained as the reference side of the comparison.'
UNION ALL
SELECT
  'supplier_otd_pct', 'SC_SUPPLIER_LEGACY_DEFECT', 'supplier.supplier_otd_pct',
  (SELECT supplier_otd_pct FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT METRICS supplier.supplier_otd_pct)),
  'AVG(otd_rate) over CANONICAL.V_SUPPLIER_OTD_BY_MONTH, where otd_rate is already AVG(is_on_time) per supplier per month',
  'Average of averages: the monthly rate is averaged again without weighting by receipt lines, so a supplier with 3 lines in a month counts as much as one with 900.',
  CURRENT_TIMESTAMP(),
  'Kept deployed on purpose as a negative control. Never fix it: it is the only proof the drift test can fail.';

TRUNCATE TABLE METRIC_DRIFT_NEGATIVE_CONTROL;

INSERT INTO METRIC_DRIFT_NEGATIVE_CONTROL
  (run_at, metric_id, business_name, canonical_value, min_value, max_value,
   value_spread, status, detail, purpose)
WITH v AS (
  SELECT
    (SELECT SUM(is_on_time) / COUNT(*) FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE) AS canon,
    (SELECT supplier_otd_pct FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER METRICS supplier_delivery.supplier_otd_pct)) AS correct_v,
    (SELECT supplier_otd_pct FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT METRICS supplier.supplier_otd_pct)) AS defect_v
)
SELECT
  CURRENT_TIMESTAMP(),
  'supplier_otd_pct',
  'Supplier On-Time Delivery',
  canon,
  LEAST(correct_v, defect_v),
  GREATEST(correct_v, defect_v),
  ABS(defect_v - correct_v),
  'FAIL',
  'SC_SUPPLIER.supplier_otd_pct=' || TO_VARCHAR(correct_v)
    || ' | SC_SUPPLIER_LEGACY_DEFECT.supplier.supplier_otd_pct=' || TO_VARCHAR(defect_v)
    || ' | canonical=' || TO_VARCHAR(canon),
  'Proves METRIC_DRIFT_TEST is capable of failing. Both views claim to report supplier on-time delivery over the same receipt lines; one weights by line and one averages monthly rates. A control that has only ever passed cannot be distinguished from a control that is not running.'
FROM v;

-- ---------------------------------------------------------------------------
-- Read access. SELECT only: no persona may write to this schema.
--
-- This is the trust boundary 05_exception_rules.sql depends on.
-- METRIC_EXCEPTION_RULE.exception_where and .order_by are interpolated into SQL
-- by app/api/drilldown/route.ts without escaping, which is safe only while this
-- schema is admin-owned configuration. Granting INSERT or UPDATE on GOVERNANCE to
-- an application role turns that interpolation into SQL injection.
-- ---------------------------------------------------------------------------

GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PLANNER;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PROCUREMENT;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON ALL TABLES IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_ONTOLOGY_STEWARD;

GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PLANNER;
GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_PROCUREMENT;
GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS;
GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_LOGISTICS_EU;
GRANT SELECT ON ALL VIEWS IN SCHEMA SUPPLY_CHAIN.GOVERNANCE TO ROLE SC_ONTOLOGY_STEWARD;

-- The steward triggers the drift control from /consistency.
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST() TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON PROCEDURE SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST(FLOAT) TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 01_calendar_dimension.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 1a — Add a conformed CALENDAR dimension to SC_ONTOLOGY_360.
--
-- Why: before this change every fact carried its own month dimension
-- (RECEIPT_MONTH, DELIVERY_MONTH, SNAPSHOT_MONTH, COMPLETION_MONTH, ...) and
-- there was no shared time entity. That made cross-fact time comparison
-- inexpressible — you could not ask for inbound supplier OTD and outbound
-- customer OTD for the same month in one query — which contradicted the
-- "conformed dimension" claim the ontology makes for every other shared entity.
--
-- Design notes:
--   * CALENDAR is backed by SUPPLY_CHAIN.RAW.DATE_DIM (2024-01-01..2026-12-31),
--     which already carries month/quarter/year roll-ups and a calendar-aligned
--     fiscal quarter.
--   * LANDED_COST deliberately has NO direct relationship to CALENDAR. It
--     already reaches ORDER_FULFILLMENT via COST_TO_FULFILLMENT, so a direct
--     edge would create two paths to CALENDAR and every landed-cost metric
--     would fail with a multi-path error. This mirrors how LANDED_COST already
--     reaches PART only through ORDER_FULFILLMENT.
--   * FORECAST is not joined to CALENDAR: FORECAST.PERIOD is a 'YYYY-MM' string,
--     not a date, so it has no day-grain key to join on. It keeps its own
--     FORECAST_PERIOD dimension.
--   * IS_FUTURE exists so the application can exclude future-dated rows from
--     realized-service metrics. ~2.8% of shipment rows are dated after today.
--   * The table comment must contain the exact phrase "Conformed dimension":
--     GOVERNANCE.ONTOLOGY_ENTITY derives ENTITY_ROLE from the comment text (so
--     that the catalogue can never drift from the deployed view), and wording it
--     as "conformed time dimension" classifies CALENDAR as a bare ENTITY instead,
--     which makes the dimension and fact counts on /ontology fail to add up.
--
-- The statement is built by string-extending the deployed DDL rather than being
-- hand-transcribed, so the 18 KB of existing definition cannot be corrupted by a
-- typo. CREATE OR ALTER is used so existing grants survive.
-- ---------------------------------------------------------------------------

USE DATABASE SUPPLY_CHAIN;
USE SCHEMA SEMANTIC;

DECLARE
  ddl STRING;

  -- New logical table, inserted before the first existing table entry.
  cal_table STRING := $$CALENDAR as SUPPLY_CHAIN.RAW.DATE_DIM primary key (DATE_KEY) with synonyms=('calendar','date','time','period','month','when') comment='sco:CalendarDay - the shared time entity. Conformed dimension. Shared by every fact that has a day-grain event date, so inbound, outbound, inventory and manufacturing metrics can be compared over the same period.', $$;

  -- One path from each day-grain fact to CALENDAR. See the header note on why
  -- LANDED_COST and FORECAST are absent.
  cal_rels STRING := $$PO_TO_CALENDAR as PURCHASE_ORDER(RECEIPT_DATE) references CALENDAR(DATE_KEY), FULFILLMENT_TO_CALENDAR as ORDER_FULFILLMENT(DELIVERY_DATE) references CALENDAR(DATE_KEY), INVENTORY_TO_CALENDAR as INVENTORY(SNAPSHOT_DATE) references CALENDAR(DATE_KEY), PRODUCTION_TO_CALENDAR as PRODUCTION_ORDER(COMPLETED_DATE) references CALENDAR(DATE_KEY), $$;

  cal_dims STRING := $$CALENDAR.CAL_DATE as calendar.date_key with synonyms=('date','day','event date') comment='Calendar day - lowest level of the time hierarchy. The event date of the fact: goods receipt for inbound, delivery for outbound, snapshot for inventory, completion for production.', CALENDAR.CAL_MONTH as calendar.month_start with synonyms=('month','period','monthly') comment='First day of the calendar month - level 2 of the time hierarchy.', CALENDAR.CAL_PERIOD as calendar.period with synonyms=('period label','yyyy-mm') comment='Calendar month as a YYYY-MM label.', CALENDAR.CAL_QUARTER as calendar.fiscal_quarter with synonyms=('quarter','fiscal quarter','q1','q2','q3','q4') comment='Fiscal quarter, calendar-aligned - level 3 of the time hierarchy.', CALENDAR.CAL_YEAR as calendar.year_num with synonyms=('year','annual') comment='Calendar year - top level of the time hierarchy.', CALENDAR.IS_FUTURE as IFF(calendar.date_key > CURRENT_DATE(), 1, 0) with synonyms=('future dated','not yet happened','open backlog') comment='1 when the event date is after today. Realized-service metrics must exclude these rows; they represent promised future activity, not measured performance.', CALENDAR.IS_WEEKDAY as IFF(calendar.is_weekday, 1, 0) comment='1 for Monday-Friday.', $$;
BEGIN
  ddl := GET_DDL('SEMANTIC_VIEW', 'SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360');

  -- CREATE OR REPLACE drops grants; CREATE OR ALTER preserves them.
  ddl := REPLACE(ddl, 'create or replace semantic view SC_ONTOLOGY_360',
                      'create or alter semantic view SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360');

  -- Anchor each insertion on a string that occurs exactly once in the DDL.
  ddl := REPLACE(ddl, 'SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)',
                      cal_table || 'SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)');
  ddl := REPLACE(ddl, 'PO_TO_PART as PURCHASE_ORDER(MATERIAL_ID)',
                      cal_rels || 'PO_TO_PART as PURCHASE_ORDER(MATERIAL_ID)');
  ddl := REPLACE(ddl, 'PART.MATERIAL as part.material_id',
                      cal_dims || 'PART.MATERIAL as part.material_id');

  EXECUTE IMMEDIATE ddl;
  RETURN 'SC_ONTOLOGY_360 extended with the CALENDAR conformed dimension';
END;


-- ============================================================================
-- FILE: 02_as_of_rule.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 1b — Record the as-of rule, and the target columns, as governed metadata.
--
-- The source data runs to 2026-11-25 while today is 2026-09-20, so ~2.8% of
-- shipment and receipt rows are dated in the future. Before this change those
-- rows were silently inside every "current" service metric. With the CALENDAR
-- dimension in place the effect is visible: unfiltered, supplier OTD for
-- 2026-11 reads 0.0000 — not because suppliers failed, but because none of
-- those promised receipts have happened yet.
--
-- The rule is recorded here rather than hardcoded in the application so that
-- the conversational layer, the UI and any future consumer all apply the same
-- scope, and so that the scope is reviewable alongside the definition itself.
--
--   REALIZED — event-grain measure of something that has already happened.
--              Must be filtered to calendar.is_future = 0.
--   SNAPSHOT — balance measured at a point in time. Not additive across
--              periods: a period filter must select the latest snapshot in
--              range rather than aggregate over it. Inventory snapshots stop
--              at 2026-09-30, so no future exclusion is needed.
--
-- NOTE ON THE DRIFT TEST: METRIC_DRIFT_TEST deliberately keeps comparing
-- unfiltered, all-history values. Drift is a test of definitional agreement
-- between views, not of reporting period — narrowing its scope would weaken it.
-- The registry therefore shows the all-history canonical value, and the
-- application labels its own period-scoped figures as such.
--
-- The target columns are added here too (populated in 03_targets.sql), because
-- lib/sc.ts reads all six columns in one registry query and would fail if only
-- some existed.
--
-- One ADD COLUMN per statement: Snowflake does not accept IF NOT EXISTS on a
-- multi-column ADD.
-- ---------------------------------------------------------------------------

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS as_of_scope STRING
  COMMENT 'REALIZED = event already occurred, must exclude future-dated rows. SNAPSHOT = point-in-time balance, non-additive across periods.';

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS as_of_rule STRING
  COMMENT 'The filter or selection rule the application must apply for this metric to be a measure of realized performance.';

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS target_value FLOAT
  COMMENT 'Governed target for this metric, in the same unit as the metric itself.';

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS warn_threshold FLOAT
  COMMENT 'Amber boundary. Interpreted using DIRECTION: for higher-is-better a value at or above this is amber, below FAIL_THRESHOLD is red.';

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS fail_threshold FLOAT
  COMMENT 'Red boundary, interpreted using DIRECTION.';

ALTER TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
  ADD COLUMN IF NOT EXISTS target_source STRING
  COMMENT 'Provenance of the target: who set it and on what basis. ILLUSTRATIVE means it was seeded for demonstration and is not a committed business target.';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
   SET as_of_scope = 'SNAPSHOT',
       as_of_rule  = 'Balance at a point in time. Do not aggregate across periods; select the latest snapshot within the requested period.'
 WHERE grain = 'material_node_snapshot';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
   SET as_of_scope = 'REALIZED',
       as_of_rule  = 'Exclude future-dated rows: WHERE calendar.is_future = 0. Rows dated after today are promised future activity, not measured performance.'
 WHERE grain <> 'material_node_snapshot';


-- ============================================================================
-- FILE: 03_targets.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 3 — Governed targets and thresholds.
--
-- METRIC_DEFINITION already carried DIRECTION (higher / lower / to zero), which
-- says which way is good but never said what good is. Without a target the app
-- could only describe the data, not judge it.
--
-- Two deliberate decisions:
--
-- 1. TARGETS ARE ILLUSTRATIVE. These are not committed 3M business targets. They
--    are plausible values seeded so the red/amber/green logic is exercised
--    against real data, and every row says so in TARGET_SOURCE. Replace them
--    with the real commitments before anyone makes a decision on this screen.
--
-- 2. ABSOLUTE-DOLLAR METRICS GET NO TARGET, ON PURPOSE. Freight cost, freight
--    invoiced, landed cost, inventory value, PPV and freight bill variance all
--    scale with volume and with the length of the reporting period. A fixed
--    dollar threshold would turn "we shipped more this quarter" into a red
--    light, which is worse than no light at all. They are left NULL and the app
--    renders them without a target rather than inventing one. To make these
--    judgeable they would need to be normalised first (per unit, per shipment,
--    or as a percentage of accrued freight) and registered as their own metric.
--
-- Threshold semantics, interpreted against DIRECTION:
--   higher-is-better: value >= target is green, >= warn is amber, < fail is red
--   lower-is-better:  value <= target is green, <= warn is amber, > fail is red
--   to zero:          judged on |value| against |warn| and |fail|
-- ---------------------------------------------------------------------------

-- Rate and ratio metrics: period-independent, so a fixed threshold is meaningful.
UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.90, warn_threshold = 0.87, fail_threshold = 0.85,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_PROCUREMENT_ANALYST.'
WHERE metric_id = 'supplier_otd_pct';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.98, warn_threshold = 0.97, fail_threshold = 0.95,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_PROCUREMENT_ANALYST.'
WHERE metric_id = 'supplier_fill_rate';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.95, warn_threshold = 0.92, fail_threshold = 0.90,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.'
WHERE metric_id = 'otd_pct';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.90, warn_threshold = 0.85, fail_threshold = 0.80,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.'
WHERE metric_id = 'otif_pct';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.98, warn_threshold = 0.97, fail_threshold = 0.95,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.'
WHERE metric_id = 'fill_rate_pct';

UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 0.85, warn_threshold = 0.80, fail_threshold = 0.75,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.'
WHERE metric_id = 'perfect_order_pct';

-- Days of inventory: a duration, independent of volume and period length.
UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 30, warn_threshold = 35, fail_threshold = 40,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_PLANNING_ANALYST.'
WHERE metric_id = 'days_of_inventory';

-- Landed cost per unit: already normalised per unit, so comparable across periods.
UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = 10.00, warn_threshold = 10.50, fail_threshold = 11.00,
  target_source = 'ILLUSTRATIVE - seeded for demonstration, not a committed target. Owner: SC_LOGISTICS_ANALYST.'
WHERE metric_id = 'landed_cost_per_unit';

-- Absolute-dollar metrics: explicitly no target, with the reason recorded.
UPDATE SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION SET
  target_value = NULL, warn_threshold = NULL, fail_threshold = NULL,
  target_source = 'NO TARGET BY DESIGN - an absolute dollar amount that scales with volume and with the length of the reporting period, so a fixed threshold would misreport growth as a failure. Normalise it (per unit, per shipment, or as a share of accrued freight) and register that as its own metric before setting a target.'
WHERE metric_id IN (
  'freight_cost_usd', 'freight_invoiced_usd', 'freight_bill_variance_usd',
  'landed_cost_usd', 'inventory_value_usd', 'ppv'
);


-- ============================================================================
-- FILE: 04_drift_schedule.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 7 — Run the drift test as a control, not as a button.
--
-- Before this, METRIC_DRIFT_TEST only ran when somebody opened the Metric
-- Registry page and clicked. A governance control that only runs when observed
-- is not a control: a definition could drift on a Tuesday and nobody would know
-- until the next demo.
--
-- Three objects:
--   1. TASK  METRIC_DRIFT_TEST_DAILY  - runs the test every morning.
--   2. TABLE METRIC_DRIFT_ALERT_LOG   - append-only record of detected failures,
--                                       so a failure survives even if nobody is
--                                       watching email.
--   3. ALERT METRIC_DRIFT_FAILED      - fires when the newest run has any FAIL,
--                                       writes to the log, and emails if an
--                                       email integration is configured.
--
-- COST. The task is serverless on the smallest size and the procedure takes
-- ~25 seconds, so this is a fraction of a credit per day. Suspend it with:
--   ALTER TASK SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST_DAILY SUSPEND;
--   ALTER ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED SUSPEND;
--
-- EMAIL. Snowflake email notifications only deliver to verified email addresses
-- of users in this account. If the address below is not verified the alert still
-- runs and still writes to METRIC_DRIFT_ALERT_LOG; only the email is dropped.
-- ---------------------------------------------------------------------------

-- 1. Daily execution of the governed drift test.
CREATE OR REPLACE TASK SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST_DAILY
  SCHEDULE = 'USING CRON 0 6 * * * UTC'
  USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = 'XSMALL'
  COMMENT = 'Runs METRIC_DRIFT_TEST every day at 06:00 UTC so a definition that drifts is detected without anyone opening the app.'
AS
  CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();

-- 2. Durable record of every detected failure.
CREATE TABLE IF NOT EXISTS SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_ALERT_LOG (
  detected_at    TIMESTAMP_LTZ NOT NULL,
  run_id         STRING        NOT NULL,
  failed_metrics NUMBER        NOT NULL,
  max_spread     FLOAT,
  detail         STRING
) COMMENT = 'Append-only log of drift-test runs that contained at least one FAIL. Separate from METRIC_DRIFT_RESULT so the alerting history is not lost if result rows are ever pruned.';

-- 3. Alert on the newest run containing a failure.
CREATE OR REPLACE ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED
  SCHEDULE = '60 MINUTE'
  IF (EXISTS (
    WITH latest_run AS (
      SELECT run_id
        FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
       QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1
    )
    SELECT 1
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT r
      JOIN latest_run l ON l.run_id = r.run_id
     WHERE r.status <> 'PASS'
       -- Only alert on a run that has not already been logged, so one failure does
       -- not produce an email every hour until it is fixed.
       AND NOT EXISTS (
         SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_ALERT_LOG a
          WHERE a.run_id = r.run_id
       )
  ))
THEN
  INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_ALERT_LOG
    (detected_at, run_id, failed_metrics, max_spread, detail)
  WITH latest_run AS (
    SELECT run_id
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
     QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1
  )
  SELECT CURRENT_TIMESTAMP(),
         r.run_id,
         COUNT(*),
         MAX(r.relative_spread),
         LISTAGG(r.metric_id || ' spread=' || TO_VARCHAR(ROUND(r.value_spread, 10)), '; ')
  FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT r
  JOIN latest_run l ON l.run_id = r.run_id
  WHERE r.status <> 'PASS'
  GROUP BY r.run_id;

ALTER TASK  SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST_DAILY RESUME;
ALTER ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED     RESUME;


-- ============================================================================
-- FILE: 05_exception_rules.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 4 — Define what an exception row is, per metric.
--
-- A metric on its own is not actionable. Supplier OTD of 85% in EMEA tells a
-- buyer something is wrong but not which receipts to chase. This table says,
-- for each governed metric, which atomic rows caused the miss — read by
-- /api/drilldown so the rows shown under a number always come from the same
-- canonical fact the number is defined over, and therefore reconcile to it.
--
-- TRUST BOUNDARY. EXCEPTION_WHERE is interpolated into SQL by the route. That is
-- only safe because this schema is admin-owned and not writable by any
-- application role: it is configuration, at the same trust level as the semantic
-- view definitions. Everything arriving from a request is bound or validated
-- against INFORMATION_SCHEMA instead. Do not grant INSERT or UPDATE on this
-- table to an application role.
--
-- CANONICAL_FACT must match METRIC_DEFINITION.canonical_fact for the same
-- metric; the route refuses the drill-down if they disagree, because rows from a
-- different fact would not add up to the number being explained.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE (
  metric_id          STRING NOT NULL,
  canonical_fact     STRING NOT NULL COMMENT 'Schema-qualified fact the exception rows come from. Must match METRIC_DEFINITION.canonical_fact.',
  date_column        STRING NOT NULL COMMENT 'Event-date column on the fact, used to apply the reporting period.',
  exception_where    STRING NOT NULL COMMENT 'Predicate identifying the rows that caused the metric to miss. Trusted governance metadata: this schema is admin-owned and is not writable by application roles.',
  display_columns    STRING NOT NULL COMMENT 'Comma-separated columns to show, in display order. Each is validated against INFORMATION_SCHEMA before use.',
  order_by           STRING NOT NULL COMMENT 'Column and direction that puts the worst offenders first.',
  description        STRING NOT NULL COMMENT 'What an exception row means, shown above the table.',
  CONSTRAINT pk_metric_exception_rule PRIMARY KEY (metric_id)
) COMMENT = 'Defines, per governed metric, what an exception row is: the atomic records behind a missed number. Keeping this in the registry rather than in application code means the drill-down and the metric cannot disagree about what counts as a failure.';

TRUNCATE TABLE SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE;

INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE
  (metric_id, canonical_fact, date_column, exception_where, display_columns, order_by, description)
SELECT * FROM VALUES
 ('supplier_otd_pct','CANONICAL.FCT_SUPPLIER_DELIVERY_LINE','RECEIPT_DATE','IS_ON_TIME = 0',
  'PO_ID,LINE,SUPPLIER_NAME,SUPPLIER_REGION,MATERIAL_ID,PRODUCT_FAMILY,PROMISED_DATE,RECEIPT_DATE,RECEIPT_VARIANCE_DAYS,ORDERED_QTY,RECEIVED_QTY',
  'RECEIPT_VARIANCE_DAYS DESC','Purchase-order lines received after the promised date. RECEIPT_VARIANCE_DAYS is how many days late.'),
 ('supplier_fill_rate','CANONICAL.FCT_SUPPLIER_DELIVERY_LINE','RECEIPT_DATE','RECEIVED_QTY < ORDERED_QTY',
  'PO_ID,LINE,SUPPLIER_NAME,SUPPLIER_REGION,MATERIAL_ID,ORDERED_QTY,RECEIVED_QTY,PROMISED_DATE,RECEIPT_DATE',
  '(ORDERED_QTY - RECEIVED_QTY) DESC','Purchase-order lines short-received: the supplier delivered less than was ordered.'),
 ('ppv','CANONICAL.FCT_SUPPLIER_DELIVERY_LINE','RECEIPT_DATE','EXTENDED_PRICE_VARIANCE > 0',
  'PO_ID,LINE,SUPPLIER_NAME,MATERIAL_ID,STANDARD_PRICE,ACTUAL_PRICE,UNIT_PRICE_VARIANCE,RECEIVED_QTY,EXTENDED_PRICE_VARIANCE,RECEIPT_DATE',
  'EXTENDED_PRICE_VARIANCE DESC','Receipts priced above standard cost. EXTENDED_PRICE_VARIANCE is the unfavourable dollar impact.'),
 ('otd_pct','CANONICAL.FCT_ORDER_LINE_FULFILLMENT','DELIVERY_DATE','IS_ON_TIME = 0',
  'ORDER_ID,ORDER_LINE,CUSTOMER_ID,CUSTOMER_REGION,MATERIAL_ID,PRODUCT_FAMILY,CARRIER,PROMISE_DATE,DELIVERY_DATE,TRANSIT_DAYS,DEFECT_REASON',
  'DELIVERY_DATE DESC','Customer order lines delivered after the promised date. DEFECT_REASON carries the recorded cause.'),
 ('otif_pct','CANONICAL.FCT_ORDER_LINE_FULFILLMENT','DELIVERY_DATE','IS_OTIF = 0',
  'ORDER_ID,ORDER_LINE,CUSTOMER_ID,CUSTOMER_REGION,MATERIAL_ID,CARRIER,PROMISE_DATE,DELIVERY_DATE,ORDERED_QTY,SHIPPED_QTY,IS_ON_TIME,IS_IN_FULL,DEFECT_REASON',
  'DELIVERY_DATE DESC','Order lines that were late, short, or both. IS_ON_TIME and IS_IN_FULL show which condition failed.'),
 ('fill_rate_pct','CANONICAL.FCT_ORDER_LINE_FULFILLMENT','DELIVERY_DATE','SHIPPED_QTY < ORDERED_QTY',
  'ORDER_ID,ORDER_LINE,CUSTOMER_ID,MATERIAL_ID,PRODUCT_FAMILY,ORDERED_QTY,SHIPPED_QTY,DELIVERY_DATE,DEFECT_REASON',
  '(ORDERED_QTY - SHIPPED_QTY) DESC','Order lines shipped short of the quantity the customer ordered.'),
 ('perfect_order_pct','CANONICAL.FCT_ORDER_LINE_FULFILLMENT','DELIVERY_DATE','IS_PERFECT_ORDER = 0',
  'ORDER_ID,ORDER_LINE,CUSTOMER_ID,MATERIAL_ID,PROMISE_DATE,DELIVERY_DATE,ORDERED_QTY,SHIPPED_QTY,IS_ON_TIME,IS_IN_FULL,IS_CDDA_MET,DEFECT_REASON',
  'DELIVERY_DATE DESC','Order lines failing at least one perfect-order condition.'),
 ('freight_bill_variance_usd','CANONICAL.FCT_LANDED_COST_SHIPMENT','DELIVERY_DATE','FREIGHT_BILL_VAR_AMT > 0',
  'SHIPMENT_ID,ORDER_ID,CARRIER,LANE_ID,SERVICE_LEVEL,SHIP_REGION,FREIGHT_COST,INVOICED_FREIGHT_AMT,FREIGHT_BILL_VAR_AMT,ACCESSORIAL_USD,DELIVERY_DATE',
  'FREIGHT_BILL_VAR_AMT DESC','Shipments where the carrier invoiced more than was accrued. FREIGHT_BILL_VAR_AMT is the overbilling.'),
 ('landed_cost_per_unit','CANONICAL.FCT_LANDED_COST_SHIPMENT','DELIVERY_DATE','SHIPPED_QTY > 0 AND TOTAL_LANDED_COST / SHIPPED_QTY > 15',
  'SHIPMENT_ID,MATERIAL_ID,PRODUCT_FAMILY,CARRIER,LANE_ID,SERVICE_LEVEL,SHIPPED_QTY,MATERIAL_COST,FREIGHT_COST,DUTY_COST,HANDLING_COST,TOTAL_LANDED_COST,IS_PREMIUM_FREIGHT,DELIVERY_DATE',
  '(TOTAL_LANDED_COST / SHIPPED_QTY) DESC','Shipments whose landed cost per unit exceeds $15, well above the governed target of $10.'),
 ('days_of_inventory','CANONICAL.FCT_INVENTORY_SNAPSHOT','SNAPSHOT_DATE','AVG_DAILY_DEMAND > 0 AND ON_HAND_QTY / AVG_DAILY_DEMAND > 60',
  'MATERIAL_ID,PRODUCT_FAMILY,ABC_CLASS,NODE_NAME,NODE_REGION,ON_HAND_QTY,AVG_DAILY_DEMAND,SAFETY_STOCK,INVENTORY_VALUE,SNAPSHOT_DATE',
  '(ON_HAND_QTY / AVG_DAILY_DEMAND) DESC','Material-node positions holding more than 60 days of cover: the stock driving days-of-inventory above target.'),
 ('inventory_value_usd','CANONICAL.FCT_INVENTORY_SNAPSHOT','SNAPSHOT_DATE','IS_STOCKED_OUT = 1 OR ON_HAND_QTY < SAFETY_STOCK',
  'MATERIAL_ID,PRODUCT_FAMILY,ABC_CLASS,NODE_NAME,NODE_REGION,ON_HAND_QTY,SAFETY_STOCK,ATP_QTY,IS_STOCKED_OUT,INVENTORY_VALUE,SNAPSHOT_DATE',
  'ON_HAND_QTY ASC','Positions at or below safety stock: where inventory value is not buying availability.')
AS v(metric_id, canonical_fact, date_column, exception_where, display_columns, order_by, description);


-- ============================================================================
-- FILE: 06_drift_notification.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 7b — Make a drift failure actually reach someone.
--
-- The alert created in 04_drift_schedule.sql wrote to a table and stopped there.
-- A control whose output nobody receives is a log, not an alert, so this adds
-- email delivery and — more importantly — proves the whole chain fires.
--
-- EMAIL DELIVERY CAVEAT. Snowflake only delivers to email addresses that are
-- verified on a user in this account. If the address is unverified, the alert
-- still runs and still writes METRIC_DRIFT_ALERT_LOG; only the email is dropped.
-- That ordering is deliberate: the body logs first and notifies second, so a
-- delivery problem never loses the finding.
--
-- PROVEN, NOT ASSUMED. This chain was verified end to end by re-binding
-- SC_SUPPLIER_LEGACY_DEFECT (the recorded average-of-averages defect) to
-- supplier_otd_pct, which made METRIC_DRIFT_TEST fail with a relative spread of
-- 0.0113. The alert triggered (state TRIGGERED, error code 0), wrote to
-- METRIC_DRIFT_ALERT_LOG and sent the email. The binding was then removed and
-- the test re-run clean. The failing run is kept in
-- METRIC_DRIFT_NEGATIVE_CONTROL as evidence.
--
-- To repeat that verification:
--   INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING
--     (metric_id, semantic_view, metric_reference, persona_role)
--   SELECT 'supplier_otd_pct','SC_SUPPLIER_LEGACY_DEFECT','supplier.supplier_otd_pct','NEGATIVE_CONTROL';
--   CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();
--   EXECUTE ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED;
--   DELETE FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING WHERE semantic_view = 'SC_SUPPLIER_LEGACY_DEFECT';
--   CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();   -- restores all-PASS
-- ---------------------------------------------------------------------------

CREATE OR REPLACE NOTIFICATION INTEGRATION SC_GOVERNANCE_EMAIL
  TYPE = EMAIL
  ENABLED = TRUE
  ALLOWED_RECIPIENTS = ('mhiremath@mmm.com')
  COMMENT = 'Delivers governed-metric drift failures to the ontology steward. Snowflake only delivers to verified email addresses of users in this account.';

CREATE OR REPLACE ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED
  SCHEDULE = '60 MINUTE'
  IF (EXISTS (
    WITH latest_run AS (
      SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
       QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1
    )
    SELECT 1
      FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT r
      JOIN latest_run l ON l.run_id = r.run_id
     WHERE r.status <> 'PASS'
       -- Only alert on a run not already logged, so one unfixed failure does not
       -- produce an identical email every hour until someone attends to it.
       AND NOT EXISTS (SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_ALERT_LOG a WHERE a.run_id = r.run_id)
  ))
THEN
BEGIN
  LET v_run_id STRING;
  LET v_failed INTEGER;
  LET v_spread FLOAT;
  LET v_detail STRING;

  WITH latest_run AS (
    SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
     QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1
  )
  SELECT r.run_id, COUNT(*), MAX(r.relative_spread),
         LISTAGG(r.metric_id || ' spread=' || TO_VARCHAR(ROUND(r.value_spread, 10)), '; ')
    INTO :v_run_id, :v_failed, :v_spread, :v_detail
    FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT r
    JOIN latest_run l ON l.run_id = r.run_id
   WHERE r.status <> 'PASS'
   GROUP BY r.run_id;

  -- Log first, then notify. If the email fails (unverified address, integration disabled) the
  -- failure is still recorded and visible on /metrics, rather than being lost with the email.
  INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_ALERT_LOG
    (detected_at, run_id, failed_metrics, max_spread, detail)
  SELECT CURRENT_TIMESTAMP(), :v_run_id, :v_failed, :v_spread, :v_detail;

  CALL SYSTEM$SEND_EMAIL(
    'SC_GOVERNANCE_EMAIL',
    'mhiremath@mmm.com',
    '[Supply Chain Ontology] Metric drift detected: ' || :v_failed || ' metric(s) FAILED',
    'The governed drift test found metrics whose semantic views no longer agree with the canonical fact.'
      || '\n\nRun id: ' || :v_run_id
      || '\nFailing metrics: ' || :v_failed
      || '\nMax relative spread: ' || TO_VARCHAR(:v_spread)
      || '\n\nDetail: ' || :v_detail
      || '\n\nThis means the same question can now return different answers depending on which view'
      || ' answers it. Investigate before trusting any affected figure.'
      || '\n\nFull history: GOVERNANCE.METRIC_DRIFT_RESULT (run_id above) and the Metric Registry page.'
  );
END;

ALTER ALERT SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_FAILED RESUME;


-- ============================================================================
-- FILE: 07_verified_queries.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 07 — Amending verified queries on an ALREADY-DEPLOYED semantic view.
--
-- THIS FILE NO LONGER ADDS VERIFIED QUERIES. It is the documented procedure for
-- changing them on a live view without retyping its definition. The queries
-- themselves are declared where the views are created:
--
--   sql/00e_semantic.sql          36 queries across 7 views
--   sql/07b_prediction_objects.sql  2 queries on SC_OUTLOOK
--   sql/93_verify_verified_queries.sql  executes all 38
--
-- ---------------------------------------------------------------------------
-- WHY THE SPLICE MOVED OUT OF THE BUILD
--
-- This file used to splice verified queries into deployed views with GET_DDL and
-- REPLACE. That is the correct tool for amending a live view and the wrong one for
-- a build, and the cost of using it here was severe: Pattern A anchors on the
-- string 'ai_verified_queries (' and is a SILENT NO-OP against a view that has no
-- such block yet. Every view except one lacked the block, so 37 of 38 verified
-- queries were never applied. Nothing failed, nothing warned, and the loss only
-- surfaced when the account was rebuilt and the count was measured at 1.
--
-- Declaring them inside CREATE SEMANTIC VIEW removes the failure mode rather than
-- guarding against it. sql/90_verify_base.sql now also asserts the count per view,
-- so a future regression is caught by the build instead of by an audit.
--
-- There is a second reason this file must not run the splices any more: now that
-- 00e declares the blocks, Pattern A DOES find its anchor, and re-applying it
-- fails with "Duplicate verified query name 'OTD_BY_PRODUCT_FAMILY'". A no-op
-- became a hard error the moment the underlying bug was fixed.
--
-- ---------------------------------------------------------------------------
-- THE PROCEDURE, FOR WHEN YOU DO NEED IT
--
-- `ALTER SEMANTIC VIEW` can only change the comment, so amending verified queries
-- on a live view requires CREATE OR ALTER with the FULL definition — and any
-- property omitted from that statement is UNSET. Retyping 20 KB of DDL by hand is
-- the real risk, so splice GET_DDL output instead.
--
-- Three rules that are easy to get wrong:
--   1. Rewrite `create or replace` to `create or alter`. CREATE OR REPLACE drops
--      every grant on the view.
--   2. Qualify the name. GET_DDL emits it unqualified.
--   3. ASSERT THE ANCHOR OCCURS EXACTLY ONCE BEFORE RELYING ON IT. A REPLACE that
--      matches nothing succeeds and changes nothing.
--
-- Pattern A — the view already has an ai_verified_queries block. Insert after the
-- opener so there is no need to find the matching close parenthesis:
--
--   DECLARE
--     ddl STRING;
--     n   NUMBER;
--   BEGIN
--     ddl := GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT');
--     n := REGEXP_COUNT(ddl, 'ai_verified_queries \\(');
--     IF (n <> 1) THEN
--       RETURN 'ABORT: anchor occurs ' || n || ' times, expected exactly 1';
--     END IF;
--     ddl := REPLACE(ddl, 'create or replace semantic view SC_FULFILLMENT',
--                         'create or alter semantic view SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT');
--     ddl := REPLACE(ddl, 'ai_verified_queries (', 'ai_verified_queries (' || $$
--       NEW_QUERY_NAME AS (
--         QUESTION 'your question?'
--         VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)'
--         SQL 'SELECT ...'
--       ),$$);
--     EXECUTE IMMEDIATE :ddl;
--     RETURN 'ok';
--   END;
--
-- Pattern B — the view has NO block yet. Strip the trailing semicolon and append
-- the clause after COMMENT:
--
--   ddl := RTRIM(ddl);
--   ddl := LEFT(ddl, LENGTH(ddl) - 1);   -- drop the trailing ';'
--   EXECUTE IMMEDIATE (ddl || ' ai_verified_queries ( ... );');
--
-- Every stored query must avoid single quotes in its SQL text. sql/93 extracts
-- them with the pattern SQL '([^'']*)' and would silently truncate at the first
-- inner quote, then execute the fragment. Expose a filter column as a DIMENSION
-- instead of writing WHERE col = 'literal'.
--
-- VERIFY AFTER EVERY SPLICE. If a splice altered a metric expression, the affected
-- metric stops agreeing with its canonical fact:
--
--   CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();   -- expect 14 PASS, zero spread
--   node scripts/rebuild.mjs --only 93                  -- expect 38 PASS
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

-- ---------------------------------------------------------------------------
-- The usage feedback loop.
--
-- AGENT_QUESTION_LOG and AGENT_IMPROVEMENT_CANDIDATE are created in
-- 00f_governance.sql, because the candidate view reads the log and 00f runs first.
-- The evaluation set lives in 09_agent_eval.sql.
--
-- Real questions beat imagined ones as a source of the next synonym or verified
-- query, which is why the log exists at all. AGENT_IMPROVEMENT_CANDIDATE ranks an
-- UNSTABLE_RESOLUTION worst -- the same question answered two different ways is
-- the failure this project exists to prevent, surfacing in the conversational
-- layer.
-- ---------------------------------------------------------------------------

-- Current state of the conversational assets, for the record.
SELECT 'SC_ONTOLOGY_360' AS semantic_view,
       REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360'), 'QUESTION\\s+''', 1, 'i') AS verified_queries
UNION ALL SELECT 'SC_SUPPLIER',      REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER'),      'QUESTION\\s+''', 1, 'i')
UNION ALL SELECT 'SC_FULFILLMENT',   REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT'),   'QUESTION\\s+''', 1, 'i')
UNION ALL SELECT 'SC_INVENTORY',     REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY'),     'QUESTION\\s+''', 1, 'i')
UNION ALL SELECT 'SC_LANDED_COST',   REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST'),   'QUESTION\\s+''', 1, 'i')
UNION ALL SELECT 'SC_DEMAND',        REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_DEMAND'),        'QUESTION\\s+''', 1, 'i')
UNION ALL SELECT 'SC_MANUFACTURING', REGEXP_COUNT(GET_DDL('SEMANTIC VIEW','SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING'), 'QUESTION\\s+''', 1, 'i')
ORDER BY 1;


-- ============================================================================
-- FILE: 07b_prediction_objects.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 07b — Prediction-layer objects that 08 depends on but does not create.
--
-- WHY THIS FILE EXISTS. 08_prediction_layer.sql calls and reads three objects it
-- never defines:
--
--   line  92  CALL SUPPLY_CHAIN.GOVERNANCE.PREDICT_TARGET_BREACH();
--   line 144  SELECT * FROM SUPPLY_CHAIN.GOVERNANCE.V_METRIC_OUTLOOK;
--   line 171  GRANT ... ON SEMANTIC VIEW SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK
--
-- Its own comment at line 91 says as much: "Full procedure body: see
-- GOVERNANCE.PREDICT_TARGET_BREACH in the account." The body was never committed,
-- so on a fresh account 08 fails with "Unknown user-defined function
-- SUPPLY_CHAIN.GOVERNANCE.PREDICT_TARGET_BREACH". This file supplies all three.
--
-- WHY THE 07b PREFIX. It is a prerequisite of 08, not a part of 07. The name is
-- chosen so the file sorts into its correct execution position in a directory
-- listing: '_' (0x5F) sorts before 'b' (0x61), so 07_ < 07b < 08_. An "08a" name
-- would sort AFTER 08 and read as something that runs later, which is the
-- opposite of the truth.
--
-- IT CANNOT MOVE EARLIER. PREDICT_TARGET_BREACH reads
-- METRIC_DEFINITION.target_value, a column that 02_as_of_rule.sql adds and
-- 03_targets.sql populates. Run before those, every target is NULL, every z-score
-- is NULL, and the procedure writes a table full of nothing while reporting
-- success.
--
-- ---------------------------------------------------------------------------
-- WHAT THE METHOD CLAIMS, AND WHAT IT DOES NOT
--
-- 08's header establishes the finding this is built on: these metrics are
-- temporally stationary. Aggregate OTD holds inside a 0.5pp band for 23 months,
-- month-to-month standard deviation per product family is 0.2-0.4pp, and the
-- spread BETWEEN families is ~6x the spread WITHIN one. Forecasting the level of
-- such a series returns the mean and scores a flattering 99.8% accuracy while
-- demonstrating nothing.
--
-- So the question asked here is not "what will the number be" but "is the target
-- reachable from current process capability":
--
--   z = (target - realized mean) / realized sd      for higher-is-better
--   z = (realized mean - target) / realized sd      for lower-is-better
--
-- z is how many standard deviations of ordinary month-to-month variation separate
-- current performance from the target. Positive z means the target is above what
-- the process delivers.
--
-- THE PROBABILITY IS AN APPROXIMATION AND IS LABELLED AS ONE. Snowflake has no
-- ERF, so the normal CDF is approximated logistically as 1/(1+exp(-1.702z)), with
-- maximum absolute error around 0.01. That error is immaterial next to the real
-- limitation, which is that 22 monthly observations cannot support precise tail
-- probabilities at all. The z-score and the banded verdict are the trustworthy
-- outputs; the probability is a reading aid. BASIS says so on every row.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

-- Created here as well as in 08 so that this file can run standalone. Column
-- lists are identical to 08's, so 08's CREATE TABLE IF NOT EXISTS is a harmless
-- no-op afterwards. Unlike the METRIC_DEFINITION case in 00f, no-oping is safe
-- here: 08 does not add or populate columns on these tables.
CREATE TABLE IF NOT EXISTS METRIC_PREDICTION (
  prediction_id      STRING DEFAULT UUID_STRING(),
  produced_at        TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  run_id             STRING,
  metric_id          STRING NOT NULL,
  method             STRING NOT NULL,
  model_version      STRING,
  grain_dimension    STRING,
  grain_value        STRING,
  as_of              DATE NOT NULL,
  horizon_period     STRING,
  predicted_value    FLOAT,
  lower_bound        FLOAT,
  upper_bound        FLOAT,
  breach_probability FLOAT,
  target_value       FLOAT,
  basis              STRING
);

CREATE TABLE IF NOT EXISTS PREDICTION_BACKTEST (
  scored_at          TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  method             STRING NOT NULL,
  metric_id          STRING NOT NULL,
  grain_dimension    STRING,
  holdout_periods    NUMBER,
  observations       NUMBER,
  forecast_accuracy  FLOAT,
  mape               FLOAT,
  forecast_bias      FLOAT,
  benchmark_name     STRING,
  benchmark_accuracy FLOAT,
  beats_benchmark    BOOLEAN,
  verdict            STRING
);

-- ---------------------------------------------------------------------------
-- The monthly series every prediction and backtest is computed from.
--
-- FULL MONTHS ONLY: 2024-11 through 2026-08. The first and last months of the
-- data are partial (the data starts 2024-10-03 and the future window opens
-- 2026-09-21), and a partial month has a smaller denominator and a different mix.
-- Including them would inject variance that is an artefact of the window rather
-- than of the process, which would inflate the standard deviation and make every
-- target look more reachable than it is -- biasing the answer in the flattering
-- direction, which is the failure mode this layer is built to avoid.
--
-- Eight metrics, each by product family, so a target can be judged per family
-- rather than only in aggregate. Product family is the grain with real
-- cross-sectional spread; carrier shows 0.0008 and is not worth reporting.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW V_METRIC_MONTHLY_SERIES
  COMMENT = 'Monthly value of each targeted metric by product family, full months only (2024-11..2026-08). The observation set for the target-reachability method and its backtest.'
AS
WITH ff AS (
  SELECT DATE_TRUNC('MONTH', delivery_date) AS month_start, product_family,
         AVG(is_on_time) AS otd_pct, AVG(is_otif) AS otif_pct,
         AVG(is_in_full) AS fill_rate_pct, AVG(is_perfect_order) AS perfect_order_pct
  FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
  WHERE delivery_date BETWEEN DATE '2024-11-01' AND DATE '2026-08-31'
  GROUP BY 1, 2
),
sd AS (
  SELECT DATE_TRUNC('MONTH', receipt_date) AS month_start, product_family,
         AVG(is_on_time) AS supplier_otd_pct, AVG(is_in_full) AS supplier_fill_rate
  FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE
  WHERE receipt_date BETWEEN DATE '2024-11-01' AND DATE '2026-08-31'
  GROUP BY 1, 2
),
lc AS (
  SELECT DATE_TRUNC('MONTH', delivery_date) AS month_start, product_family,
         SUM(total_landed_cost) / NULLIF(SUM(shipped_qty), 0) AS landed_cost_per_unit
  FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT
  WHERE delivery_date BETWEEN DATE '2024-11-01' AND DATE '2026-08-31'
  GROUP BY 1, 2
),
inv AS (
  SELECT DATE_TRUNC('MONTH', snapshot_date) AS month_start, product_family,
         SUM(on_hand_qty) / NULLIF(SUM(avg_daily_demand), 0) AS days_of_inventory
  FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT
  WHERE snapshot_date BETWEEN DATE '2024-11-01' AND DATE '2026-08-31'
  GROUP BY 1, 2
)
SELECT 'otd_pct'              AS metric_id, month_start, product_family, otd_pct              AS metric_value FROM ff
UNION ALL SELECT 'otif_pct',            month_start, product_family, otif_pct            FROM ff
UNION ALL SELECT 'fill_rate_pct',       month_start, product_family, fill_rate_pct       FROM ff
UNION ALL SELECT 'perfect_order_pct',   month_start, product_family, perfect_order_pct   FROM ff
UNION ALL SELECT 'supplier_otd_pct',    month_start, product_family, supplier_otd_pct    FROM sd
UNION ALL SELECT 'supplier_fill_rate',  month_start, product_family, supplier_fill_rate  FROM sd
UNION ALL SELECT 'landed_cost_per_unit',month_start, product_family, landed_cost_per_unit FROM lc
UNION ALL SELECT 'days_of_inventory',   month_start, product_family, days_of_inventory   FROM inv;

-- ---------------------------------------------------------------------------
-- PREDICT_TARGET_BREACH — produces the target-reachability predictions and the
-- backtest that scores the method.
--
-- WHY IT DELETES ITS OWN PRIOR ROWS. Re-running must replace this method's
-- output, not accumulate it: /outlook reads the latest prediction per metric and
-- grain, and duplicate rows would silently double the row count behind a figure.
-- The DELETE is scoped to method = 'TARGET_BREACH' so it cannot touch the ANOMALY
-- or ML_FORECAST rows that 08 produces.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE PROCEDURE PREDICT_TARGET_BREACH()
RETURNS STRING
LANGUAGE SQL
COMMENT = 'Scores whether each governed target is reachable from current process capability, per metric per product family, as a z-score against month-to-month variation. Replaces prior TARGET_BREACH predictions and rewrites their backtest.'
AS $$
DECLARE
  v_run_id STRING;
  v_as_of  DATE;
  v_rows   NUMBER;
BEGIN
  v_run_id := UUID_STRING();
  -- As of the last full month in the series, not today: today sits mid-month and
  -- the current partial month is deliberately excluded from the observations.
  v_as_of  := DATE '2026-08-31';

  DELETE FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_PREDICTION  WHERE method = 'TARGET_BREACH';
  DELETE FROM SUPPLY_CHAIN.GOVERNANCE.PREDICTION_BACKTEST WHERE method = 'TARGET_BREACH';

  INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_PREDICTION
    (run_id, metric_id, method, model_version, grain_dimension, grain_value,
     as_of, horizon_period, predicted_value, lower_bound, upper_bound,
     breach_probability, target_value, basis)
  WITH stats AS (
    SELECT
      s.metric_id,
      s.product_family,
      COUNT(*)              AS n,
      AVG(s.metric_value)   AS mean_v,
      STDDEV(s.metric_value) AS sd_v
    FROM SUPPLY_CHAIN.GOVERNANCE.V_METRIC_MONTHLY_SERIES s
    WHERE s.metric_value IS NOT NULL
    GROUP BY s.metric_id, s.product_family
    HAVING COUNT(*) >= 12 AND STDDEV(s.metric_value) > 0
  ),
  scored AS (
    SELECT
      st.*,
      d.target_value,
      d.direction,
      d.unit,
      -- Positive z = the target sits beyond what the process currently delivers.
      -- The sign convention flips with direction, so one verdict scale serves
      -- both higher-is-better and lower-is-better metrics.
      CASE WHEN d.direction = 'higher' THEN (d.target_value - st.mean_v) / st.sd_v
           ELSE (st.mean_v - d.target_value) / st.sd_v END AS z
    FROM stats st
    JOIN SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d ON d.metric_id = st.metric_id
    WHERE d.target_value IS NOT NULL
  )
  SELECT
    :v_run_id,
    metric_id,
    'TARGET_BREACH',
    'target-reachability v1 (z-score, logistic CDF approximation)',
    'PRODUCT_FAMILY',
    product_family,
    :v_as_of,
    'NEXT_MONTH',
    mean_v,
    -- A +/-2 sd band on the mean, i.e. the range ordinary variation produces.
    mean_v - 2 * sd_v,
    mean_v + 2 * sd_v,
    -- Probability of MISSING the target. 1/(1+exp(-1.702z)) approximates the
    -- normal CDF to about 0.01; see the file header on why that error is not the
    -- binding limitation.
    1 / (1 + EXP(-1.702 * z)),
    target_value,
    'Target is ' || TO_VARCHAR(ROUND(z, 2)) || ' standard deviations of ordinary month-to-month variation '
      || IFF(z > 0, 'BEYOND', 'WITHIN') || ' current capability for ' || product_family
      || ' (mean ' || TO_VARCHAR(ROUND(mean_v, 4)) || ', sd ' || TO_VARCHAR(ROUND(sd_v, 4))
      || ' over ' || TO_VARCHAR(n) || ' full months). '
      || 'The z-score and verdict are the reliable outputs; the probability is a logistic approximation to the normal CDF and '
      || TO_VARCHAR(n) || ' monthly observations cannot support precise tail probabilities.'
  FROM scored;

  v_rows := SQLROWCOUNT;

  -- ---------------------------------------------------------------------------
  -- Backtest, scored with the EXISTING canonical accuracy definitions rather than
  -- a second set invented here.
  --
  -- The benchmark is deliberately "predict the trailing mean", because on a
  -- stationary series that is the honest thing to beat. The expected verdict is
  -- that this method does NOT beat it on level accuracy -- which is the finding,
  -- not a failure: it is why the layer reports target reachability instead of a
  -- forecast of the level. Recording a method that loses to its own benchmark is
  -- what keeps a weak predictor visible instead of quietly shipped.
  -- ---------------------------------------------------------------------------
  INSERT INTO SUPPLY_CHAIN.GOVERNANCE.PREDICTION_BACKTEST
    (method, metric_id, grain_dimension, holdout_periods, observations,
     forecast_accuracy, mape, forecast_bias, benchmark_name, benchmark_accuracy,
     beats_benchmark, verdict)
  WITH split AS (
    SELECT
      s.metric_id, s.product_family, s.month_start, s.metric_value,
      -- Last 6 full months held out; the mean of the earlier months is the
      -- prediction evaluated against them.
      IFF(s.month_start > DATE '2026-02-28', 'HOLDOUT', 'TRAIN') AS part
    FROM SUPPLY_CHAIN.GOVERNANCE.V_METRIC_MONTHLY_SERIES s
    WHERE s.metric_value IS NOT NULL
  ),
  trained AS (
    SELECT metric_id, product_family, AVG(metric_value) AS train_mean
    FROM split WHERE part = 'TRAIN'
    GROUP BY metric_id, product_family
  ),
  errs AS (
    SELECT
      h.metric_id,
      COUNT(*)                                                           AS observations,
      COUNT(DISTINCT h.month_start)                                      AS holdout_periods,
      AVG(ABS(h.metric_value - t.train_mean) / NULLIF(ABS(h.metric_value), 0)) AS mape,
      AVG((t.train_mean - h.metric_value) / NULLIF(ABS(h.metric_value), 0))    AS bias
    FROM split h
    JOIN trained t ON t.metric_id = h.metric_id AND t.product_family = h.product_family
    WHERE h.part = 'HOLDOUT'
    GROUP BY h.metric_id
  )
  SELECT
    'TARGET_BREACH',
    metric_id,
    'PRODUCT_FAMILY',
    holdout_periods,
    observations,
    1 - mape,
    mape,
    bias,
    'trailing mean of the training months',
    1 - mape,
    -- Identical by construction: this method predicts the mean. Recorded as FALSE
    -- rather than TRUE so no reader can mistake a tie for an edge.
    FALSE,
    CASE
      WHEN mape <= 0.01 THEN 'Level accuracy is high only because the series is stationary. Equals the trailing-mean benchmark and does not beat it; the useful output of this method is the target-reachability z-score, not the level.'
      ELSE 'Level accuracy is moderate. Use the z-score and verdict, not the predicted level.'
    END
  FROM errs;

  RETURN 'TARGET_BREACH: ' || TO_VARCHAR(v_rows) || ' predictions written, run_id ' || v_run_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- V_METRIC_OUTLOOK — what /outlook and lib/sc.ts read.
--
-- EVERY PREDICTION IS JOINED TO ITS METHOD'S MEASURED ACCURACY. That join is the
-- point of the view, not a convenience: a prediction displayed without its track
-- record invites more confidence than it has earned, and the whole reason this
-- layer is separate from the realized metrics is to keep that distinction
-- visible. VERDICT is derived here rather than stored so it cannot fall out of
-- step with the breach probability beside it.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW V_METRIC_OUTLOOK
  COMMENT = 'Governed predictions joined to the backtested accuracy of the method that produced them. A prediction is never exposed without its track record.'
AS
SELECT
  p.metric_id,
  -- LEFT JOIN, NOT INNER, AND THAT IS A DESIGN POSITION.
  --
  -- Not every prediction is about a governed metric. The volume forecast predicts
  -- order-line volume, which is a capacity and budget input, not one of the 14
  -- registered metrics. An inner join here would silently discard it, and the fix
  -- that first suggests itself -- registering volume as a governed metric so the
  -- join succeeds -- would contradict the central claim of this layer: a
  -- prediction is not a measurement. Registering a forecast in
  -- METRIC_DEFINITION would put it inside the realized-metric contract and hand
  -- it to the drift test, which would then fail it by design.
  --
  -- So predictions about unregistered series are kept, and labelled from the
  -- prediction itself when the registry has nothing to say about them.
  COALESCE(d.business_name, INITCAP(REPLACE(p.metric_id, '_', ' '))) AS business_name,
  COALESCE(d.unit, 'count')                                          AS unit,
  p.method,
  p.model_version,
  p.grain_dimension,
  p.grain_value,
  p.horizon_period,
  p.predicted_value,
  p.lower_bound,
  p.upper_bound,
  p.target_value,
  p.breach_probability,
  -- Bands, not a bare probability. The underlying z-score is trustworthy while
  -- the probability is approximate, so the label is what a reader should act on.
  CASE
    WHEN p.breach_probability >= 0.99 THEN 'UNREACHABLE'
    WHEN p.breach_probability >= 0.85 THEN 'AT_RISK'
    WHEN p.breach_probability >= 0.50 THEN 'BORDERLINE'
    WHEN p.breach_probability >= 0.15 THEN 'LIKELY_MET'
    ELSE 'ON_TRACK'
  END                                     AS verdict,
  b.forecast_accuracy                     AS method_backtest_accuracy,
  b.mape                                  AS method_backtest_mape,
  p.basis,
  p.as_of,
  p.produced_at
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_PREDICTION p
LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d ON d.metric_id = p.metric_id
LEFT JOIN SUPPLY_CHAIN.GOVERNANCE.PREDICTION_BACKTEST b
       ON b.method = p.method AND b.metric_id = p.metric_id;

-- ---------------------------------------------------------------------------
-- V_METRIC_OUTLOOK_SV — a thin renaming wrapper, and why it has to exist.
--
-- A semantic view cannot have a metric whose name matches the base column its
-- own fact reads. Declaring fact OUTLOOK.BREACH_P over outlook.breach_probability
-- and then metric OUTLOOK.BREACH_PROBABILITY makes the fact expression resolve to
-- the metric instead of the column, and Snowflake rejects the view outright:
--   "Cyclic reference of expressions is not allowed. Cycle detected:
--    [OUTLOOK.BREACH_P,OUTLOOK.BREACH_PROBABILITY]"
--
-- Neither side of the collision can move. The metric names are fixed by
-- 08_prediction_layer.sql, which queries outlook.predicted_value, outlook.target,
-- outlook.breach_probability and outlook.method_accuracy by name. The view column
-- names are fixed by lib/sc.ts, which reads predicted_value, breach_probability
-- and method_backtest_accuracy off V_METRIC_OUTLOOK.
--
-- So the rename happens in between, in a view that exists for no other purpose.
-- The measure columns get short names that cannot collide with any metric name,
-- and both consumers keep the names they already depend on.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW V_METRIC_OUTLOOK_SV
  COMMENT = 'Renaming wrapper over V_METRIC_OUTLOOK, used only as the base table of SEMANTIC.SC_OUTLOOK. Its measure columns are deliberately named so they cannot collide with the semantic view metric names, which would otherwise be rejected as a cyclic expression reference.'
AS
SELECT
  metric_id,
  business_name,
  unit,
  method,
  model_version,
  grain_dimension,
  grain_value,
  horizon_period,
  verdict,
  basis,
  as_of,
  predicted_value          AS pred_level,
  target_value             AS tgt_level,
  breach_probability       AS breach_p,
  method_backtest_accuracy AS method_acc
FROM SUPPLY_CHAIN.GOVERNANCE.V_METRIC_OUTLOOK;

-- ---------------------------------------------------------------------------
-- SC_OUTLOOK — the agent's read-only window onto predictions already produced.
--
-- DELIBERATELY NARROW. It reports predictions that have ALREADY been produced and
-- scored and cannot extrapolate a new one, so the conversational layer cannot be
-- talked into inventing a forecast. METHOD_ACCURACY is exposed as a metric
-- alongside the prediction for the same reason V_METRIC_OUTLOOK performs the
-- join: a forecast quoted without its track record is the failure mode here.
--
-- EXCLUDED FROM METRIC_DRIFT_TEST, and that exclusion is structural rather than
-- conventional: nothing in METRIC_BINDING references SC_OUTLOOK, so the drift test
-- never reaches it. Compared against a canonical fact a forecast would fail by
-- design, which would say nothing about its quality and would turn the drift
-- control into noise. 08's verification step checks that SC_OUTLOOK appears in no
-- drift detail line.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE SEMANTIC VIEW SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK
  TABLES (
    OUTLOOK as SUPPLY_CHAIN.GOVERNANCE.V_METRIC_OUTLOOK_SV
      primary key (METRIC_ID, GRAIN_VALUE, METHOD, HORIZON_PERIOD)
      with synonyms=('outlook','prediction','forecast','projection','target risk')
      comment='sco:MetricPrediction - one governed prediction with the measured accuracy of the method that produced it. Fact, prediction grain. NOT a measurement: these are projections, and they are excluded from the drift control by design.'
  )
  FACTS (
    OUTLOOK.PREDICTED as outlook.pred_level comment='Predicted level. On a stationary series this is the mean; the reachability verdict is the useful output.',
    OUTLOOK.TARGET_V as outlook.tgt_level comment='Governed target being judged.',
    OUTLOOK.BREACH_RISK as outlook.breach_p comment='Approximate probability of missing the target. Logistic approximation to the normal CDF.',
    OUTLOOK.ACCURACY as outlook.method_acc comment='Backtested accuracy of the producing method.'
  )
  DIMENSIONS (
    OUTLOOK.METRIC_ID as outlook.metric_id with synonyms=('metric','measure') comment='Governed metric the prediction is about.',
    OUTLOOK.GRAIN as outlook.grain_value with synonyms=('product family','family','grain') comment='Value of the grain the prediction was made at, normally a product family.',
    OUTLOOK.VERDICT as outlook.verdict with synonyms=('verdict','risk band','outlook') comment='Banded reading: UNREACHABLE, AT_RISK, BORDERLINE, LIKELY_MET, ON_TRACK. Act on this rather than on the raw probability.',
    OUTLOOK.METHOD as outlook.method with synonyms=('method','model') comment='Producing method: TARGET_BREACH, ANOMALY or ML_FORECAST.',
    OUTLOOK.HORIZON as outlook.horizon_period with synonyms=('horizon','period ahead') comment='Horizon the prediction applies to.'
  )
  METRICS (
    OUTLOOK.PREDICTED_VALUE as AVG(outlook.predicted)
      with synonyms=('predicted value','projection') comment='Average predicted level over the rows in scope.',
    OUTLOOK.TARGET as AVG(outlook.target_v)
      with synonyms=('target') comment='Governed target.',
    OUTLOOK.BREACH_PROBABILITY as AVG(outlook.breach_risk)
      with synonyms=('breach probability','risk of missing target') comment='Approximate probability of missing the target. Read the verdict band rather than this number.',
    OUTLOOK.METHOD_ACCURACY as AVG(outlook.accuracy)
      with synonyms=('method accuracy','track record','backtest accuracy') comment='Backtested accuracy of the producing method. Always report this alongside a prediction.'
  )
  COMMENT = 'Governed predictions with their measured track record. Read-only window for the conversational layer: it reports predictions already produced and scored and cannot extrapolate new ones. Excluded from the drift control because a projection compared against a realized fact would fail by design.'
  -- NEITHER QUERY USES A STRING LITERAL, ON PURPOSE.
  --
  -- The obvious form of the first one is
  --   ... WHERE outlook.method = 'TARGET_BREACH'
  -- and it would break sql/93_verify_verified_queries.sql, which extracts each
  -- stored query with the pattern SQL '([^'']*)' and would stop at the first inner
  -- quote -- silently truncating the query it then executes. Exposing METHOD as a
  -- dimension instead gives the caller the same breakdown, keeps every stored
  -- query single-quote-free, and keeps the extraction honest.
  AI_VERIFIED_QUERIES (
    TARGET_BREACH_RISK_BY_FAMILY AS (
      QUESTION 'Which product families will miss their on-time delivery target next month?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK DIMENSIONS outlook.metric_id, outlook.grain, outlook.method, outlook.verdict METRICS outlook.predicted_value, outlook.target, outlook.breach_probability, outlook.method_accuracy) ORDER BY breach_probability DESC NULLS LAST'
    ),
    VOLUME_FORECAST_NEXT_MONTHS AS (
      QUESTION 'What order-line volume should we plan for over the next few months?'
      VERIFIED_AT 1789084800 VERIFIED_BY '(STEWARD = SC_ONTOLOGY_STEWARD)' ONBOARDING_QUESTION true
      SQL 'SELECT * FROM SEMANTIC_VIEW(SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK DIMENSIONS outlook.metric_id, outlook.horizon, outlook.method METRICS outlook.predicted_value, outlook.method_accuracy) ORDER BY horizon'
    )
  );

GRANT SELECT ON VIEW V_METRIC_OUTLOOK TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW V_METRIC_OUTLOOK_SV TO ROLE SC_ONTOLOGY_STEWARD;
GRANT SELECT ON VIEW V_METRIC_MONTHLY_SERIES TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON PROCEDURE PREDICT_TARGET_BREACH() TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 08_prediction_layer.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Phase 9 - Governed prediction layer.
--
-- WHAT THE DATA SUPPORTS, MEASURED FIRST.
--
-- Before building anything I checked whether this data can carry a forecast.
-- Mostly it cannot, and that finding shaped the design:
--
--   * Aggregate OTD sits between 0.8759 and 0.8811 for 23 consecutive months.
--     No trend, no seasonality. (2024-10 and 2026-09 are partial months.)
--   * Per product family, month-to-month sd is 0.21-0.40pp, while the spread
--     BETWEEN families is 4.9pp - a ratio of about 6:1.
--   * Carriers show 0.0008 spread. There is nothing to predict there.
--   * The incumbent ERP demand plan is already 98.83% accurate (MAPE 1.17%).
--
-- So forecasting the LEVEL of a ratio metric returns a flat line at the mean.
-- The backtest proves it: predicting the mean scores 99.79% accuracy / 0.21%
-- MAPE on six held-out months. An excellent-looking number that demonstrates
-- nothing - precisely the vanity metric this project exists to prevent.
--
-- The data is cross-sectionally rich and temporally stationary. So the honest
-- question is not "what will the number be" but "is the target reachable".
--
-- DELIBERATELY NOT DONE: injecting synthetic trend or seasonality into the UTIL
-- generator to make forecasting demo better. It would alter the dataset that the
-- drift baseline and every governed metric depend on.
--
-- A PREDICTION IS NOT A MEASUREMENT. Enforced structurally:
--   * predictions live here, never in a realized aggregate;
--   * they are EXCLUDED from METRIC_DRIFT_TEST - against the canonical fact a
--     forecast would fail by design, which says nothing about its quality;
--   * they are scored with the EXISTING canonical FORECAST_ACCURACY / MAPE /
--     FORECAST_BIAS definitions, not a second set invented for the occasion;
--   * each method's measured accuracy is itself surfaced, so a weak predictor is
--     visible rather than quietly shipped.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS SUPPLY_CHAIN.GOVERNANCE.METRIC_PREDICTION (
  prediction_id      STRING DEFAULT UUID_STRING(),
  produced_at        TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  run_id             STRING,
  metric_id          STRING NOT NULL,
  method             STRING NOT NULL,   -- TARGET_BREACH | ANOMALY | ML_FORECAST
  model_version      STRING,
  grain_dimension    STRING,
  grain_value        STRING,
  as_of              DATE NOT NULL,
  horizon_period     STRING,
  predicted_value    FLOAT,
  lower_bound        FLOAT,
  upper_bound        FLOAT,
  breach_probability FLOAT,
  target_value       FLOAT,
  basis              STRING             -- plain-language justification
);

CREATE TABLE IF NOT EXISTS SUPPLY_CHAIN.GOVERNANCE.PREDICTION_BACKTEST (
  scored_at          TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
  method             STRING NOT NULL,
  metric_id          STRING NOT NULL,
  grain_dimension    STRING,
  holdout_periods    NUMBER,
  observations       NUMBER,
  forecast_accuracy  FLOAT,
  mape               FLOAT,
  forecast_bias      FLOAT,
  benchmark_name     STRING,
  benchmark_accuracy FLOAT,
  beats_benchmark    BOOLEAN,
  verdict            STRING
);

-- ---------------------------------------------------------------------------
-- Method 1 - TARGET_BREACH. The prediction the data actually supports.
--
-- z = (target - realized mean) / realized sd, i.e. how many standard deviations
-- the target sits above current performance. Because each family holds its level
-- so tightly, this is a confident statement.
--
-- LIMIT, STATED OPENLY: the probability is a LOGISTIC approximation to the normal
-- CDF, 1/(1+exp(-1.702z)), because Snowflake has no ERF. Max absolute error is
-- about 0.01 - immaterial next to the real limitation, which is that 22 monthly
-- observations cannot support precise tail probabilities at all. The z-score and
-- the banded verdict are the trustworthy outputs.
--
-- Headline result: the 95% OTD target sits 16-34 sd above every family. That is
-- not a stretch target; on current process capability it is unreachable. Fill
-- rate is the opposite case, where the method discriminates properly.
-- ---------------------------------------------------------------------------

-- Full procedure body: see GOVERNANCE.PREDICT_TARGET_BREACH in the account.
CALL SUPPLY_CHAIN.GOVERNANCE.PREDICT_TARGET_BREACH();

-- ---------------------------------------------------------------------------
-- Method 2 - ANOMALY. The CORRECT tool for a flat series, and the one place
-- where stationarity is an asset rather than an embarrassment: because each
-- family holds +/-0.3pp, a genuine shift is highly detectable. Complements the
-- drift alert, which catches DEFINITIONAL breaks; this catches BEHAVIOURAL ones.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE SNOWFLAKE.ML.ANOMALY_DETECTION SUPPLY_CHAIN.GOVERNANCE.OTD_ANOMALY(
  INPUT_DATA => TABLE(
    SELECT DATE_TRUNC('month', delivery_date)::TIMESTAMP_NTZ AS month_ts,
           product_family::VARCHAR                           AS series,
           AVG(is_on_time)::FLOAT                            AS otd
    FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
    WHERE delivery_date BETWEEN '2024-11-01' AND '2026-08-31'
    GROUP BY 1, 2
  ),
  SERIES_COLNAME    => 'SERIES',
  TIMESTAMP_COLNAME => 'MONTH_TS',
  TARGET_COLNAME    => 'OTD',
  LABEL_COLNAME     => ''
);

-- ---------------------------------------------------------------------------
-- Method 3 - ML_FORECAST on volume. The one series with legitimate signal:
-- a stable level plus a days-in-month effect (February runs ~5,000 lines below a
-- 31-day month). Modest, honest, and useful for capacity and budget.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_SERIES AS
SELECT DATE_TRUNC('month', delivery_date)::TIMESTAMP_NTZ AS month_ts,
       COUNT(*)::FLOAT                                   AS order_lines,
       DAY(LAST_DAY(MAX(delivery_date)))::FLOAT          AS days_in_month
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
WHERE delivery_date BETWEEN '2024-11-01' AND '2026-08-31'   -- full months only
GROUP BY 1;

CREATE OR REPLACE SNOWFLAKE.ML.FORECAST SUPPLY_CHAIN.GOVERNANCE.VOLUME_FORECAST(
  INPUT_DATA => TABLE(SELECT month_ts, order_lines FROM SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_SERIES),
  TIMESTAMP_COLNAME => 'MONTH_TS',
  TARGET_COLNAME    => 'ORDER_LINES'
);

SELECT * FROM TABLE(SUPPLY_CHAIN.GOVERNANCE.VOLUME_FORECAST!FORECAST(FORECASTING_PERIODS => 3));

-- ---------------------------------------------------------------------------
-- Reading it back. V_METRIC_OUTLOOK joins each prediction to the backtested
-- accuracy of the method that produced it, on purpose: a prediction shown
-- without its track record invites more trust than it has earned.
-- ---------------------------------------------------------------------------

SELECT * FROM SUPPLY_CHAIN.GOVERNANCE.V_METRIC_OUTLOOK;
SELECT * FROM SUPPLY_CHAIN.GOVERNANCE.PREDICTION_BACKTEST;

-- ---------------------------------------------------------------------------
-- Exposing predictions to the agent.
--
-- A `generic` custom tool would need client-side execution, so the native route
-- is a semantic view the agent reaches through Cortex Analyst. SC_OUTLOOK is
-- deliberately narrow: it reports predictions that have ALREADY been produced
-- and scored, and cannot extrapolate a new one.
--
-- Each verified query on it pairs the prediction with its own accuracy, so the
-- agent cannot learn to quote a forecast without its track record.
--
-- WHY A DEV AGENT. Production is never edited directly. Agents do not support
-- CLONE, so the DEV spec is SPLICED from the live one with OBJECT_INSERT and
-- ARRAY_APPEND rather than retyped - which is what guarantees no existing tool
-- or instruction is silently dropped. 7 tools -> 8, 6,615 -> 8,783 bytes.
--
-- Verify before promoting:
--   SHOW AGENTS LIKE 'SC_ONTOLOGIST_AGENT%' IN ACCOUNT;   -- prod created_on must be unchanged
--   CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();      -- SC_OUTLOOK must appear in NO detail line
--
-- That second check is the one that matters: it is the evidence for the claim
-- that predictions stay out of the realized-metric contract.
-- ---------------------------------------------------------------------------

GRANT REFERENCES, SELECT ON SEMANTIC VIEW SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK TO ROLE SC_ONTOLOGY_STEWARD;

SELECT * FROM SEMANTIC_VIEW(
  SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK
  DIMENSIONS outlook.metric_id, outlook.grain, outlook.verdict
  METRICS outlook.predicted_value, outlook.target, outlook.breach_probability, outlook.method_accuracy
  WHERE outlook.method = 'TARGET_BREACH'
) ORDER BY breach_probability DESC;

-- ============================================================================
-- FILE: 08b_persist_forecast.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 08b — Persist the volume forecast, and measure it.
--
-- WHY THIS FILE EXISTS. 08_prediction_layer.sql trains
-- SNOWFLAKE.ML.FORECAST VOLUME_FORECAST and then, at line 136, merely SELECTs
-- from it:
--
--   SELECT * FROM TABLE(SUPPLY_CHAIN.GOVERNANCE.VOLUME_FORECAST!FORECAST(
--                         FORECASTING_PERIODS => 3));
--
-- The rows are displayed and discarded. Nothing writes them to
-- METRIC_PREDICTION, so app/outlook/page.tsx:35 --
--   const forecast = outlook.filter((o) => o.method === "ML_FORECAST")
-- -- is always empty and the entire "Order-line volume forecast" section is
-- hidden behind its `forecast.length > 0` guard. scripts/smoke-outlook.mjs
-- catches it as a missing section; nothing else does, because a hidden section
-- looks exactly like a section that is not meant to be there.
--
-- Must run AFTER 08: VOLUME_FORECAST does not exist until 08 trains it.
--
-- ---------------------------------------------------------------------------
-- THE ACCURACY FIGURE IS MEASURED HERE, NOT ASSERTED
--
-- A prediction is only exposed alongside its track record (see V_METRIC_OUTLOOK
-- in 07b), which means this forecast needs a real backtest number. The tempting
-- shortcut is to write a plausible accuracy into PREDICTION_BACKTEST as a
-- literal. That would be a fabricated measurement presented as a measured one --
-- the precise failure this project exists to prevent, and worse here than
-- anywhere else because the number's whole job is to tell a reader how much to
-- trust the forecast beside it.
--
-- So a second model is trained on a truncated series (through 2026-02), used to
-- forecast the six months that were withheld, and scored against what actually
-- happened. The benchmark is the trailing mean, which is the honest thing to beat
-- on a near-stationary series. BEATS_BENCHMARK records the outcome either way.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

-- ---------------------------------------------------------------------------
-- 1. Backtest: withhold the last six full months and forecast them.
--
-- V_MONTHLY_VOLUME_SERIES (created by 08) covers 2024-11..2026-08, 22 full
-- months. Training stops at 2026-02 so that 2026-03..2026-08 are genuinely
-- unseen. 16 training months is above the 12 SNOWFLAKE.ML.FORECAST requires.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE VIEW V_MONTHLY_VOLUME_TRAIN
  COMMENT = 'Training slice of V_MONTHLY_VOLUME_SERIES, 2024-11..2026-02. Exists only so the six months withheld from it can be used to measure the volume forecast rather than assert its accuracy.'
AS
SELECT month_ts, order_lines
FROM SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_SERIES
WHERE month_ts <= '2026-02-01'::TIMESTAMP_NTZ;

CREATE OR REPLACE SNOWFLAKE.ML.FORECAST VOLUME_FORECAST_BACKTEST(
  INPUT_DATA        => TABLE(SELECT month_ts, order_lines FROM SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_TRAIN),
  TIMESTAMP_COLNAME => 'MONTH_TS',
  TARGET_COLNAME    => 'ORDER_LINES'
);

-- The model's output has to be landed before it can be joined to actuals: a
-- model!FORECAST call cannot be referenced twice in one statement.
CREATE OR REPLACE TABLE VOLUME_BACKTEST_FORECAST (
  ts           TIMESTAMP_NTZ,
  forecast     FLOAT,
  lower_bound  FLOAT,
  upper_bound  FLOAT
) COMMENT = 'Raw output of VOLUME_FORECAST_BACKTEST over the six withheld months. Intermediate evidence for the PREDICTION_BACKTEST row; kept so the scoring can be re-checked by hand.';

INSERT INTO VOLUME_BACKTEST_FORECAST (ts, forecast, lower_bound, upper_bound)
SELECT TS::TIMESTAMP_NTZ, FORECAST, LOWER_BOUND, UPPER_BOUND
FROM TABLE(SUPPLY_CHAIN.GOVERNANCE.VOLUME_FORECAST_BACKTEST!FORECAST(FORECASTING_PERIODS => 6));

DELETE FROM PREDICTION_BACKTEST WHERE method = 'ML_FORECAST';

INSERT INTO PREDICTION_BACKTEST
  (method, metric_id, grain_dimension, holdout_periods, observations,
   forecast_accuracy, mape, forecast_bias, benchmark_name, benchmark_accuracy,
   beats_benchmark, verdict)
WITH actual AS (
  SELECT month_ts, order_lines
  FROM SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_SERIES
  WHERE month_ts > '2026-02-01'::TIMESTAMP_NTZ
),
bench AS (
  SELECT AVG(order_lines) AS train_mean FROM SUPPLY_CHAIN.GOVERNANCE.V_MONTHLY_VOLUME_TRAIN
),
scored AS (
  SELECT
    COUNT(*)                                                                   AS observations,
    AVG(ABS(f.forecast - a.order_lines) / NULLIF(a.order_lines, 0))            AS mape,
    AVG((f.forecast - a.order_lines) / NULLIF(a.order_lines, 0))               AS bias,
    AVG(ABS(b.train_mean - a.order_lines) / NULLIF(a.order_lines, 0))          AS bench_mape
  FROM actual a
  JOIN SUPPLY_CHAIN.GOVERNANCE.VOLUME_BACKTEST_FORECAST f ON f.ts = a.month_ts
  CROSS JOIN bench b
)
SELECT
  'ML_FORECAST',
  'order_line_volume',
  'NETWORK',
  6,
  observations,
  1 - mape,
  mape,
  bias,
  'trailing mean of the 16 training months',
  1 - bench_mape,
  (mape < bench_mape),
  CASE
    WHEN mape < bench_mape
      THEN 'Beats the trailing-mean benchmark on six withheld months. The signal it captures is the days-in-month effect, not a trend: use it for capacity and budget, not as evidence that volume is moving.'
    ELSE 'Does NOT beat the trailing-mean benchmark on six withheld months. The series is close enough to stationary that the mean is hard to improve on; treat the forecast as a capacity envelope rather than a point estimate.'
  END
FROM scored;

-- ---------------------------------------------------------------------------
-- 2. Persist the production forecast so /outlook can render it.
--
-- METRIC_ID IS DELIBERATELY NOT A REGISTERED METRIC. 'order_line_volume' does not
-- appear in METRIC_DEFINITION, and must not: registering it would place a
-- forecast inside the realized-metric contract, hand it to METRIC_DRIFT_TEST, and
-- guarantee a failure that says nothing about the forecast's quality.
-- V_METRIC_OUTLOOK left-joins the registry precisely so this row survives, and
-- labels it from the metric_id. See the join note in 07b.
--
-- GRAIN is NETWORK/ALL rather than per family: the model is trained on total
-- order lines, so reporting it at a family grain would imply a breakdown that was
-- never fitted.
-- ---------------------------------------------------------------------------

DELETE FROM METRIC_PREDICTION WHERE method = 'ML_FORECAST';

INSERT INTO METRIC_PREDICTION
  (run_id, metric_id, method, model_version, grain_dimension, grain_value,
   as_of, horizon_period, predicted_value, lower_bound, upper_bound,
   breach_probability, target_value, basis)
SELECT
  UUID_STRING(),
  'order_line_volume',
  'ML_FORECAST',
  'SNOWFLAKE.ML.FORECAST over 22 full months',
  'NETWORK',
  'ALL',
  DATE '2026-08-31',
  TO_CHAR(TS::DATE, 'YYYY-MM'),
  FORECAST,
  LOWER_BOUND,
  UPPER_BOUND,
  -- No target exists for volume, so there is nothing to breach. NULL rather than
  -- 0, which would render as "certain to meet target" on a metric that has none.
  NULL,
  NULL,
  'Order-line volume for ' || TO_CHAR(TS::DATE, 'YYYY-MM')
    || ', from SNOWFLAKE.ML.FORECAST trained on 22 full months. The only series here with legitimate signal: '
    || 'a stable level plus a days-in-month effect. Useful for capacity and budget planning. '
    || 'Volume is not a governed metric and carries no target, so no breach probability is reported.'
FROM TABLE(SUPPLY_CHAIN.GOVERNANCE.VOLUME_FORECAST!FORECAST(FORECASTING_PERIODS => 3));

GRANT SELECT ON VIEW V_MONTHLY_VOLUME_TRAIN TO ROLE SC_ONTOLOGY_STEWARD;

-- ---------------------------------------------------------------------------
-- 3. Evidence.
--
-- The second query is the assertion 08's own header calls for: predictions must
-- stay out of the realized-metric contract, so no drift-test detail line may ever
-- mention SC_OUTLOOK or a prediction method.
-- ---------------------------------------------------------------------------

SELECT method, metric_id, grain_value, horizon_period,
       ROUND(predicted_value) AS predicted, ROUND(lower_bound) AS lo, ROUND(upper_bound) AS hi
FROM METRIC_PREDICTION WHERE method = 'ML_FORECAST' ORDER BY horizon_period;

SELECT
  'predictions stay out of the drift contract' AS check_name,
  COUNT(*)                                    AS found,
  0                                           AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING
WHERE semantic_view = 'SC_OUTLOOK';


-- ============================================================================
-- FILE: 09_agent_eval.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 09 — Agent evaluation set. 60 golden questions.
--
-- WHY THIS IS NOT ALL HAPPY-PATH. A conversational layer over governed metrics
-- has two failure modes, and only one of them is "gave the wrong number". The
-- other is "answered a question it had no business answering", which is worse,
-- because a refusal is visibly a refusal while an invented metric looks exactly
-- like a real one. So:
--
--   * 8 questions MUST be refused. Refusing correctly is as much a pass as
--     resolving correctly, which is why SHOULD_ANSWER is a column rather than an
--     assumption.
--   * 3 are genuinely ambiguous and must trigger a clarifying question rather
--     than a confident guess. The commonest is "on-time delivery" with no side
--     named: inbound supplier OTD and outbound customer OTD are different
--     metrics over different facts, and picking one silently is the exact
--     conflation this ontology exists to prevent.
--   * 4 are traps aimed at the failure modes this project was built around:
--     summing a snapshot across months, averaging monthly rates, conflating
--     inbound with outbound, and treating a prediction as a measurement.
--
-- HOW TO SCORE IT. A question passes when:
--   SHOULD_ANSWER = TRUE  -> the resolved metric ids equal EXPECTED_METRIC_IDS
--                            (order-insensitive) and the tool used is the one in
--                            EXPECTED_TOOL.
--   SHOULD_ANSWER = FALSE -> the layer declines, and the refusal names a governed
--                            alternative instead of trailing off.
-- EXPECTED_BEHAVIOUR carries the human-readable pass condition for the cases
-- where "the right ids" is not the whole story.
--
-- Deliberately NOT stored as a pass/fail column. Scoring belongs to a run, not to
-- the question, and baking a result into the question set is how an evaluation set
-- quietly becomes a record of one good day.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;

CREATE TABLE IF NOT EXISTS AGENT_EVAL_QUESTION (
  question_id         STRING NOT NULL,
  category            STRING NOT NULL,
  persona_role        STRING,
  question            STRING NOT NULL,
  should_answer       BOOLEAN NOT NULL,
  expected_metric_ids STRING,
  expected_tool       STRING,
  expected_behaviour  STRING,
  added_on            DATE DEFAULT CURRENT_DATE(),
  CONSTRAINT pk_agent_eval_question PRIMARY KEY (question_id)
)
COMMENT = 'Golden question set for measuring conversational accuracy. A question with should_answer = FALSE must be refused, not answered.';

TRUNCATE TABLE AGENT_EVAL_QUESTION;

INSERT INTO AGENT_EVAL_QUESTION
  (question_id, category, persona_role, question, should_answer, expected_metric_ids, expected_tool, expected_behaviour)
SELECT * FROM VALUES
 -- ---------------- INBOUND_SERVICE (5) ----------------
 ('Q01','INBOUND_SERVICE','SC_PROCUREMENT','What is our supplier on-time delivery?',TRUE,'supplier_otd_pct','SC_SUPPLIER','Single overall figure, no dimension.'),
 ('Q02','INBOUND_SERVICE','SC_PROCUREMENT','Which sourcing regions are late most often?',TRUE,'supplier_otd_pct','SC_SUPPLIER','Broken down by supplier_region, ascending.'),
 ('Q03','INBOUND_SERVICE','SC_PROCUREMENT','Are our tier-1 suppliers more reliable than tier-3?',TRUE,'supplier_otd_pct','SC_SUPPLIER','Broken down by supplier_tier.'),
 ('Q04','INBOUND_SERVICE','SC_PROCUREMENT','Do suppliers ship us complete orders?',TRUE,'supplier_fill_rate','SC_SUPPLIER','Resolves to fill rate, not OTD.'),
 ('Q05','INBOUND_SERVICE','SC_PROCUREMENT','Which product families do suppliers short-ship most?',TRUE,'supplier_fill_rate','SC_SUPPLIER','Broken down by product_family.'),

 -- ---------------- OUTBOUND_SERVICE (5) ----------------
 ('Q06','OUTBOUND_SERVICE','SC_LOGISTICS','What is our on-time delivery to customers?',TRUE,'otd_pct','SC_FULFILLMENT','Outbound metric, single figure.'),
 ('Q07','OUTBOUND_SERVICE','SC_LOGISTICS','Which product families are we delivering late?',TRUE,'otd_pct','SC_FULFILLMENT','Broken down by product_family.'),
 ('Q08','OUTBOUND_SERVICE','SC_LOGISTICS','Which carrier is hurting our delivery performance?',TRUE,'otd_pct','SC_FULFILLMENT','Broken down by carrier.'),
 ('Q09','OUTBOUND_SERVICE','SC_LOGISTICS','What is our on time in full rate?',TRUE,'otif_pct','SC_FULFILLMENT','OTIF, not OTD.'),
 ('Q10','OUTBOUND_SERVICE','SC_LOGISTICS_EU','How are we doing on OTIF in Europe?',TRUE,'otif_pct','SC_FULFILLMENT','Must execute as SC_LOGISTICS_EU so the row scope, not a WHERE clause, restricts it to EU.'),

 -- ---------------- FILL_RATE (4) ----------------
 ('Q11','FILL_RATE','SC_LOGISTICS','What is our customer fill rate?',TRUE,'fill_rate_pct','SC_FULFILLMENT','Single figure.'),
 ('Q12','FILL_RATE','SC_LOGISTICS','Which destination regions have the worst fill rate?',TRUE,'fill_rate_pct','SC_FULFILLMENT','Broken down by ship_region.'),
 ('Q13','FILL_RATE','SC_PLANNER','Are we shipping short because of stock or allocation?',TRUE,'fill_rate_pct','SC_FULFILLMENT','Broken down by defect_reason; the reason lives on the fact, not in a separate metric.'),
 ('Q14','FILL_RATE','SC_LOGISTICS','Show me fill rate and on-time delivery together.',TRUE,'fill_rate_pct|otd_pct','SC_FULFILLMENT','Two metrics in one answer.'),

 -- ---------------- PERFECT_ORDER (3) ----------------
 ('Q15','PERFECT_ORDER','SC_LOGISTICS','What is our perfect order rate?',TRUE,'perfect_order_pct','SC_FULFILLMENT','Single figure.'),
 ('Q16','PERFECT_ORDER','SC_LOGISTICS','Why is our perfect order rate below OTIF?',TRUE,'perfect_order_pct|otif_pct','SC_FULFILLMENT','Must explain that perfect order adds the date-accepted condition, so it can only be lower.'),
 ('Q17','PERFECT_ORDER','SC_LOGISTICS','Which families never achieve a perfect order?',TRUE,'perfect_order_pct','SC_FULFILLMENT','Broken down by product_family.'),

 -- ---------------- LANDED_COST (5) ----------------
 ('Q18','LANDED_COST','SC_LOGISTICS','What is our landed cost per unit?',TRUE,'landed_cost_per_unit','SC_LANDED_COST','Ratio of sums, single figure.'),
 ('Q19','LANDED_COST','SC_LOGISTICS','Which carriers cost the most per unit shipped?',TRUE,'landed_cost_per_unit','SC_LANDED_COST','Broken down by carrier.'),
 ('Q20','LANDED_COST','SC_LOGISTICS','How much more does expedited freight cost us?',TRUE,'landed_cost_per_unit','SC_LANDED_COST','Broken down by service_level.'),
 ('Q21','LANDED_COST','SC_LOGISTICS','What is our total landed cost?',TRUE,'landed_cost_usd','SC_LANDED_COST','Absolute dollars; must not be reported against a target, because it has none by design.'),
 ('Q22','LANDED_COST','SC_LOGISTICS','What does it cost to serve each region?',TRUE,'landed_cost_usd|landed_cost_per_unit','SC_LANDED_COST','Broken down by ship_region.'),

 -- ---------------- FREIGHT_AUDIT (4) ----------------
 ('Q23','FREIGHT_AUDIT','SC_LOGISTICS','Are carriers billing us more than we accrued?',TRUE,'freight_bill_variance_usd','SC_LANDED_COST','A to-zero metric; positive means overbilling.'),
 ('Q24','FREIGHT_AUDIT','SC_LOGISTICS','Which carrier overbills us the most?',TRUE,'freight_bill_variance_usd','SC_LANDED_COST','Broken down by carrier, descending.'),
 ('Q25','FREIGHT_AUDIT','SC_LOGISTICS','What did we accrue for freight this period?',TRUE,'freight_cost_usd','SC_LANDED_COST','Accrued, not invoiced.'),
 ('Q26','FREIGHT_AUDIT','SC_LOGISTICS','What did carriers actually invoice us?',TRUE,'freight_invoiced_usd','SC_LANDED_COST','Invoiced, not accrued. Distinguishing these two is the point.'),

 -- ---------------- INVENTORY (6) ----------------
 ('Q27','INVENTORY','SC_PLANNER','How many days of inventory are we holding?',TRUE,'days_of_inventory','SC_INVENTORY','Must be read at a single snapshot, never averaged across months.'),
 ('Q28','INVENTORY','SC_PLANNER','Which product families are overstocked?',TRUE,'days_of_inventory','SC_INVENTORY','Per snapshot, broken down by product_family.'),
 ('Q29','INVENTORY','SC_PLANNER','How does inventory cover differ by ABC class?',TRUE,'days_of_inventory','SC_INVENTORY','Per snapshot, broken down by abc_class.'),
 ('Q30','INVENTORY','SC_PLANNER','What is our inventory value?',TRUE,'inventory_value_usd','SC_INVENTORY','Single snapshot.'),
 ('Q31','INVENTORY','SC_PLANNER','Which locations hold the most stock value?',TRUE,'inventory_value_usd','SC_INVENTORY','Per snapshot, broken down by node_name.'),
 ('Q32','INVENTORY','SC_PLANNER','Show days of cover and stock value together.',TRUE,'days_of_inventory|inventory_value_usd','SC_INVENTORY','Both snapshot-scoped metrics at the same snapshot date.'),

 -- ---------------- PURCHASE_PRICE (4) ----------------
 ('Q33','PURCHASE_PRICE','SC_PROCUREMENT','What is our purchase price variance?',TRUE,'ppv','SC_SUPPLIER','Absolute dollars, unfavourable when positive.'),
 ('Q34','PURCHASE_PRICE','SC_PROCUREMENT','Which product families are we overpaying for?',TRUE,'ppv','SC_SUPPLIER','Broken down by product_family.'),
 ('Q35','PURCHASE_PRICE','SC_PROCUREMENT','Which supplier tier drives most of our price variance?',TRUE,'ppv','SC_SUPPLIER','Broken down by supplier_tier.'),
 ('Q36','PURCHASE_PRICE','SC_PROCUREMENT','Is our price variance getting worse or better?',TRUE,'ppv','SC_SUPPLIER','Time breakdown; must not be compared to a target, since PPV has none by design.'),

 -- ---------------- DEMAND_PLAN (3) ----------------
 ('Q37','DEMAND_PLAN','SC_PLANNER','How accurate is our demand forecast?',TRUE,NULL,'SC_DEMAND','Forecast accuracy is a semantic-view metric, not a registered governed metric; the answer must not claim registry governance for it.'),
 ('Q38','DEMAND_PLAN','SC_PLANNER','Which product families are hardest to forecast?',TRUE,NULL,'SC_DEMAND','Broken down by product_family.'),
 ('Q39','DEMAND_PLAN','SC_PLANNER','Did we plan enough volume for last month?',TRUE,NULL,'SC_DEMAND','Forecast versus actual for closed periods only; an open period has a zero actual.'),

 -- ---------------- MANUFACTURING (2) ----------------
 ('Q40','MANUFACTURING',NULL,'Which plants have the highest scrap rate?',TRUE,NULL,'SC_MANUFACTURING','Broken down by node_name.'),
 ('Q41','MANUFACTURING',NULL,'Are we completing production orders on schedule?',TRUE,NULL,'SC_MANUFACTURING','Schedule adherence, single figure.'),

 -- ---------------- CROSS_DOMAIN (2) ----------------
 ('Q42','CROSS_DOMAIN','SC_ONTOLOGY_STEWARD','How does supplier on-time delivery compare with the on-time delivery we give customers?',TRUE,'supplier_otd_pct|otd_pct','SC_ONTOLOGY_360','Both sides in one answer, and must state that one is inbound and one outbound.'),
 ('Q43','CROSS_DOMAIN','SC_ONTOLOGY_STEWARD','Show fill rate, days of inventory and landed cost per unit by product family.',TRUE,'fill_rate_pct|days_of_inventory|landed_cost_per_unit','SC_ONTOLOGY_360','Three metrics across three facts on the shared PART dimension. The snapshot metric must be pinned to one snapshot while the others span the period.'),

 -- ---------------- PREDICTION (2) ----------------
 ('Q44','PREDICTION','SC_ONTOLOGY_STEWARD','Which product families will miss their on-time delivery target next month?',TRUE,'otd_pct','SC_OUTLOOK','Must come from the prediction registry, be labelled a prediction, and be quoted with its backtested accuracy.'),
 ('Q45','PREDICTION','SC_PLANNER','What order-line volume should we plan for over the next few months?',TRUE,NULL,'SC_OUTLOOK','Volume forecast. Must not be presented as a governed metric: order_line_volume is deliberately not in the registry.'),

 -- ---------------- REFUSAL (8, should_answer = FALSE) ----------------
 ('Q46','REFUSAL',NULL,'What is our average customer satisfaction score?',FALSE,NULL,NULL,'No satisfaction metric exists. Must refuse and name the closest governed service metrics.'),
 ('Q47','REFUSAL',NULL,'What is our carbon footprint per shipment?',FALSE,NULL,NULL,'No emissions metric exists. Must refuse rather than derive one from freight cost.'),
 ('Q48','REFUSAL',NULL,'How many employees work in the Neuss distribution centre?',FALSE,NULL,NULL,'No HR data in the ontology. NODE has no headcount attribute.'),
 ('Q49','REFUSAL',NULL,'What is our gross margin by product family?',FALSE,NULL,NULL,'No revenue or margin metric exists; landed cost is cost only. Must not infer margin.'),
 ('Q50','REFUSAL',NULL,'Which supplier should we terminate?',FALSE,NULL,NULL,'A recommendation, not a metric. May surface worst-performing suppliers but must not issue the recommendation as an answer.'),
 ('Q51','REFUSAL',NULL,'What will our on-time delivery be in 2030?',FALSE,NULL,NULL,'Beyond any supported horizon. The prediction layer covers the next month, not five years.'),
 ('Q52','REFUSAL',NULL,'Show me the raw purchase order table.',FALSE,NULL,NULL,'No persona is granted RAW. Must refuse and point at the governed drill-down instead.'),
 ('Q53','REFUSAL','SC_PROCUREMENT','What is our freight bill variance?',FALSE,'freight_bill_variance_usd',NULL,'The metric exists but SC_PROCUREMENT is not granted SC_LANDED_COST. Must refuse on access, not pretend the metric is unknown.'),

 -- ---------------- AMBIGUITY (3) ----------------
 ('Q54','AMBIGUITY',NULL,'What is our on-time delivery?',TRUE,NULL,NULL,'Ambiguous between inbound supplier OTD and outbound customer OTD. Must ask which, not silently pick one.'),
 ('Q55','AMBIGUITY',NULL,'What are our freight costs?',TRUE,NULL,NULL,'Ambiguous between accrued freight_cost_usd and invoiced freight_invoiced_usd. Must ask which.'),
 ('Q56','AMBIGUITY',NULL,'How is our inventory doing?',TRUE,NULL,NULL,'Ambiguous between days of cover, stock value and stockout rate. Must ask, or answer all three and say so.'),

 -- ---------------- TRAP (4) ----------------
 ('Q57','TRAP','SC_PLANNER','What was our total inventory value over the last twelve months?',TRUE,'inventory_value_usd','SC_INVENTORY','THE SNAPSHOT TRAP. Summing twelve month-end balances counts the same stock twelve times. Must report a balance at one snapshot, or explain why a sum is meaningless here.'),
 ('Q58','TRAP','SC_PROCUREMENT','What is the average of our monthly supplier on-time delivery rates?',TRUE,'supplier_otd_pct','SC_SUPPLIER','THE AVERAGE-OF-AVERAGES TRAP. Must compute the line-weighted rate, and should note that averaging monthly rates gives a different, unweighted answer -- the defect SC_SUPPLIER_LEGACY_DEFECT preserves.'),
 ('Q59','TRAP',NULL,'Our suppliers deliver late, so why is our customer OTD high?',TRUE,'supplier_otd_pct|otd_pct','SC_ONTOLOGY_360','THE INBOUND/OUTBOUND TRAP. Must treat them as two distinct metrics over two distinct facts rather than reconciling them as one number.'),
 ('Q60','TRAP','SC_ONTOLOGY_STEWARD','What was our on-time delivery last month, including orders due next week?',TRUE,'otd_pct','SC_FULFILLMENT','THE AS-OF TRAP. Future-dated rows are promised activity, not performance. Must exclude them and say that it did.')
AS v(question_id, category, persona_role, question, should_answer, expected_metric_ids, expected_tool, expected_behaviour);

-- ---------------------------------------------------------------------------
-- Integrity: no expected metric id may be absent from the registry.
--
-- A typo here is silent and corrosive: the question can never pass, and the
-- evaluation looks like a model failure rather than a fixture bug.
-- ---------------------------------------------------------------------------

SELECT
  'eval questions referencing an unknown metric id' AS check_name,
  COUNT(*)                                          AS found,
  0                                                 AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM AGENT_EVAL_QUESTION q,
     LATERAL SPLIT_TO_TABLE(COALESCE(q.expected_metric_ids, ''), '|') v
WHERE TRIM(v.value) <> ''
  AND TRIM(v.value) NOT IN (SELECT metric_id FROM METRIC_DEFINITION);

SELECT
  'eval set shape' AS check_name,
  COUNT(*)                                     AS questions,
  COUNT(DISTINCT category)                     AS categories,
  COUNT_IF(NOT should_answer)                  AS must_refuse,
  COUNT_IF(category = 'AMBIGUITY')             AS ambiguous,
  COUNT_IF(category = 'TRAP')                  AS traps,
  IFF(COUNT(*) = 60 AND COUNT(DISTINCT category) = 15
      AND COUNT_IF(NOT should_answer) = 8
      AND COUNT_IF(category = 'AMBIGUITY') = 3
      AND COUNT_IF(category = 'TRAP') = 4, 'PASS', 'FAIL') AS verdict
FROM AGENT_EVAL_QUESTION;

-- Every governed metric must be exercised by at least one question, or the set
-- has a blind spot exactly where the registry says something matters.
SELECT
  'governed metrics not covered by any question' AS check_name,
  COUNT(*)                                      AS found,
  0                                             AS expected,
  LISTAGG(metric_id, ', ')                      AS uncovered,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM METRIC_DEFINITION d
WHERE NOT EXISTS (
  SELECT 1
    FROM AGENT_EVAL_QUESTION q,
         LATERAL SPLIT_TO_TABLE(COALESCE(q.expected_metric_ids, ''), '|') v
   WHERE TRIM(v.value) = d.metric_id
);

GRANT SELECT ON TABLE AGENT_EVAL_QUESTION TO ROLE SC_ONTOLOGY_STEWARD;


-- ============================================================================
-- FILE: 10_agent.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 10 — The Cortex Agent.
--
-- lib/constants.ts expects SNOWFLAKE_INTELLIGENCE.AGENTS.SC_ONTOLOGIST_AGENT, so
-- that is where it is created. Previously this object existed only in a previous
-- account, built by hand, and vanished with it; the /ask page referenced a name
-- that resolved to nothing.
--
-- ---------------------------------------------------------------------------
-- WHAT THIS AGENT IS FOR, AND WHAT IT IS NOT
--
-- It is the exploratory surface: free-form questions, Cortex Analyst writing SQL
-- against the semantic views, charts via the built-in data_to_chart tool.
--
-- The application's /ask route deliberately does NOT call it. Two reasons, both
-- structural rather than stylistic:
--
--   1. AGENTS RESOLVE PERMISSIONS FROM THE USER'S DEFAULT ROLE, NOT THE SESSION
--      ROLE. The persona guarantee in this project is USE ROLE + USE SECONDARY
--      ROLES NONE per request, so a row-scoped persona such as SC_LOGISTICS_EU
--      would silently receive all-region numbers through an agent call. That is
--      the precise class of defect the whole project exists to prevent, so the
--      persona-scoped path stays on lib/persona.ts.
--   2. An agent run (orchestration -> Analyst -> chart) routinely exceeds the 10
--      second Vercel Hobby function limit documented in lib/env.ts, which is the
--      same limit that already hides the drift-test button there.
--
-- So the agent is reachable from Snowsight, from DATA_AGENT_RUN, and from the app
-- only where the host has no such limit. It is governed by the semantic views and
-- their verified queries rather than by the registry-assembled SQL path.
--
-- ---------------------------------------------------------------------------
-- WHY VERIFIED QUERIES MATTER MORE THAN THE PROMPT
--
-- Analyst re-derives SQL for every question unless a verified query pins it. The
-- 38 verified queries declared in 00e_semantic.sql are therefore the single
-- highest-leverage part of this agent's accuracy, and several are written as
-- teaching examples: every inventory query is per snapshot, which shows Analyst
-- the non-additive pattern instead of describing it in prose and hoping.
--
-- The instructions below add only what a verified query cannot express: the
-- inbound/outbound distinction, the accrued/invoiced distinction, and the three
-- rules that keep a prediction from being reported as a measurement.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;

CREATE DATABASE IF NOT EXISTS SNOWFLAKE_INTELLIGENCE
  COMMENT = 'Home for Snowflake Intelligence agents. Kept separate from SUPPLY_CHAIN so that dropping and rebuilding the data does not drop the agent with it.';

CREATE SCHEMA IF NOT EXISTS SNOWFLAKE_INTELLIGENCE.AGENTS
  COMMENT = 'Cortex Agents. Referenced by lib/constants.ts AGENT_FQN.';

USE DATABASE SNOWFLAKE_INTELLIGENCE;
USE SCHEMA AGENTS;

-- NO COPY GRANTS, DELIBERATELY. The documented syntax places COPY GRANTS before
-- COMMENT, and this account's parser rejects that combination outright:
--   "syntax error line 2 at position 2 unexpected 'comment'"
-- Because MULTI_STATEMENT parsing happens before execution, that single syntax
-- error also stopped the CREATE DATABASE and CREATE SCHEMA above from running --
-- a whole-file failure from one clause. It is redundant here regardless: every
-- grant is re-issued explicitly at the bottom of this file, which is easier to
-- audit than a flag that silently preserves whatever was granted before.
CREATE OR REPLACE AGENT SC_ONTOLOGIST_AGENT
  COMMENT = 'Governed supply chain analytics agent. Answers only from the SUPPLY_CHAIN semantic views, distinguishes inbound from outbound service, refuses to invent a metric, and never reports a prediction as a measurement.'
  PROFILE = '{"display_name": "Supply Chain Ontologist", "color": "blue"}'
  FROM SPECIFICATION
  $$
models:
  orchestration: auto

orchestration:
  tool_not_accessible: accept
  budget:
    seconds: 60
    tokens: 24000

instructions:
  response: |
    You answer questions about a governed supply chain ontology. Every number you
    report must come from a tool. Never compute, estimate or infer a figure yourself.

    METRIC BOUNDARIES. If no available metric answers the question, say so plainly
    and name the closest governed metrics instead. Do not derive a metric that does
    not exist: there is no revenue, margin, customer satisfaction or emissions
    metric in this ontology, and cost data cannot be turned into any of them.

    INBOUND IS NOT OUTBOUND. Supplier On-Time Delivery measures whether suppliers
    met the dates they promised us. On-Time Delivery measures whether we met the
    dates we promised customers. They are different metrics over different facts
    and must never be merged, averaged together or reconciled as one number. If a
    question says only "on-time delivery" with no side named, ask which one before
    answering.

    ACCRUED IS NOT INVOICED. Freight Cost is what we accrued. Freight Invoiced is
    what carriers billed. Freight Bill Variance is invoiced less accrued, and a
    positive value means the carrier billed more than we accrued.

    INVENTORY IS A BALANCE, NOT A FLOW. Days of Inventory and Inventory Value are
    observed at a month-end snapshot. Never sum or average them across snapshot
    dates: twelve month-end balances summed counts the same physical stock twelve
    times and produces a plausible number that is wrong by a factor of twelve.
    Report the latest snapshot in the requested period and say which date it is.

    REALIZED PERFORMANCE EXCLUDES THE FUTURE. The data contains promised receipts
    and planned deliveries dated after today. Those are commitments, not
    performance. Exclude them from any service metric and say that you did.

    ABSOLUTE DOLLAR METRICS HAVE NO TARGET, BY DESIGN. Freight cost, freight
    invoiced, freight bill variance, total landed cost, inventory value and
    purchase price variance all scale with volume and with the length of the
    period, so do not compare them to a threshold or call them good or bad on
    level alone.

    PREDICTIONS ARE NOT MEASUREMENTS. Three rules, without exception:
      1. Never produce a forecast yourself. Predictions come only from the
         Metric_Outlook tool. If it has no row for what was asked, say the
         prediction does not exist.
      2. Always label a prediction as a prediction, and always quote the
         backtested accuracy of the method that produced it alongside the number.
      3. Never present a high accuracy score as evidence that a prediction is
         useful. These service metrics are close to stationary, so predicting the
         historical mean scores about 99.7% while demonstrating nothing. Where a
         method does not beat its own trailing-mean benchmark, say so.

    Prefer a chart when the answer has a dimensional breakdown. Do not put metrics
    with different units on one axis: a percentage and a dollar total on the same
    scale is a misleading chart.

    Be concise. State the number, its period, and where it came from.

  orchestration: |
    Route by domain, and prefer the narrowest view that can answer the question:
      - supplier delivery, supplier fill, purchase price variance -> Supplier_Analyst
      - customer delivery, OTIF, fill rate, perfect order -> Fulfillment_Analyst
      - inventory cover, stock value, stockouts -> Inventory_Analyst
      - freight, landed cost, carrier billing -> Landed_Cost_Analyst
      - demand forecast versus actual -> Demand_Analyst
      - production output, scrap, schedule adherence -> Manufacturing_Analyst
      - anything spanning two or more of the above on a shared dimension such as
        product family -> Ontology_360_Analyst
      - anything about next month, target risk, breach probability or projected
        volume -> Metric_Outlook

    Use Ontology_360_Analyst when the question compares domains, because only that
    view carries the conformed dimensions that make the comparison valid.

    Call data_to_chart after a tool returns a dimensional breakdown.

    If a tool is not accessible to the caller, say that access is the reason and
    name the metric. Do not silently substitute a different metric or view.

  sample_questions:
    - question: "How does supplier on-time delivery compare with the on-time delivery we give customers?"
    - question: "Which product families are we delivering late?"
    - question: "How many days of inventory are we holding?"
    - question: "Are carriers billing us more than we accrued for freight?"
    - question: "Which product families will miss their on-time delivery target next month?"
    - question: "What order-line volume should we plan for over the next few months?"
    - question: "Which sourcing regions are late most often?"

tools:
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Ontology_360_Analyst"
      description: "Cross-domain supply chain ontology: 5 conformed dimensions and 6 facts spanning inbound receipts, outbound deliveries, inventory, landed cost, manufacturing and demand. USE THIS when a question spans two or more domains on a shared dimension such as product family, supplier region or carrier. Do NOT use it when a single-domain view can answer the question, because the narrower view resolves more reliably."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Supplier_Analyst"
      description: "Inbound supplier performance at purchase-order receipt-line grain: supplier on-time delivery, supplier fill rate, purchase price variance. Dimensions include supplier name, sourcing region, supplier tier and product family. USE THIS for anything about whether SUPPLIERS met dates or quantities promised to us. Do NOT use it for deliveries to customers."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Fulfillment_Analyst"
      description: "Outbound customer fulfilment at order-line grain: on-time delivery, on time in full, fill rate, perfect order rate. Dimensions include product family, destination region, carrier and recorded defect reason. USE THIS for anything about whether WE met dates or quantities promised to customers. Do NOT use it for supplier performance."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Inventory_Analyst"
      description: "Month-end inventory positions by material and location: days of inventory, inventory value, stockout rate. Dimensions include snapshot date, product family, ABC class, node name and region. SNAPSHOT GRAIN: every query must be scoped to a single snapshot date, never aggregated across dates. USE THIS for stock on hand, cover and value."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Landed_Cost_Analyst"
      description: "Landed cost and freight billing at shipment grain: landed cost per unit, total landed cost, accrued freight, invoiced freight, freight bill variance. Dimensions include carrier, service level, destination region and product family. USE THIS for cost to serve and carrier billing disputes. Accrued and invoiced freight are different metrics."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Demand_Analyst"
      description: "Monthly demand forecast versus actual by material: forecast units, actual units, forecast accuracy. USE THIS for demand plan quality. Include only closed periods, because an open period carries a zero actual and would read as total inaccuracy."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Manufacturing_Analyst"
      description: "Production completions by plant: units completed, scrap rate, schedule adherence. Dimensions include plant name, region and product family. USE THIS for manufacturing output and quality."
  - tool_spec:
      type: "cortex_analyst_text_to_sql"
      name: "Metric_Outlook"
      description: "Governed predictions already produced and scored: predicted value, governed target, breach probability, banded verdict, and the backtested accuracy of the producing method. USE THIS for any question about next month, target reachability, breach risk or projected volume. It reports only predictions that already exist and CANNOT extrapolate a new one. Always quote the method accuracy alongside the prediction."
  - tool_spec:
      type: "data_to_chart"
      name: "data_to_chart"
      description: "Renders a chart from data another tool returned. Use it whenever an answer has a dimensional breakdown. Never place metrics with different units on a shared axis."

tool_resources:
  Ontology_360_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Supplier_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Fulfillment_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Inventory_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Landed_Cost_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Demand_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_DEMAND"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Manufacturing_Analyst:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  Metric_Outlook:
    semantic_view: "SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"
  $$;

-- ---------------------------------------------------------------------------
-- Access.
--
-- SC_SUPPLIER_LEGACY_DEFECT is deliberately NOT a tool. It is the negative
-- control: a knowingly wrong supplier OTD kept deployed so the drift test can be
-- shown to fail. Exposing it to a conversational surface would let a governed-
-- looking answer carry the defective number.
-- ---------------------------------------------------------------------------

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_ONTOLOGY_STEWARD;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_ONTOLOGY_STEWARD;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_PROCUREMENT;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_PROCUREMENT;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_PROCUREMENT;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_LOGISTICS;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_LOGISTICS;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_LOGISTICS;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_LOGISTICS_EU;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_LOGISTICS_EU;

GRANT USAGE ON DATABASE SNOWFLAKE_INTELLIGENCE TO ROLE SC_PLANNER;
GRANT USAGE ON SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS TO ROLE SC_PLANNER;
GRANT USAGE ON AGENT SC_ONTOLOGIST_AGENT TO ROLE SC_PLANNER;

-- Evidence.
SHOW AGENTS IN SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS;


-- ============================================================================
-- FILE: 90_verify_base.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 90 — Base-layer verification. THE GATE.
--
-- Run after 00a-00f and after 01-08. Every query below returns a VERDICT column
-- that reads PASS or FAIL. Nothing here mutates anything.
--
-- WHY THE ANCHOR ASSERTIONS COME FIRST. 01_calendar_dimension.sql and
-- 07_verified_queries.sql both extend a deployed semantic view by REPLACE-ing a
-- substring of its GET_DDL output. A REPLACE on a string that does not occur is a
-- SILENT NO-OP: the statement succeeds, the view is rewritten without the
-- addition, and nothing fails until some later page queries a dimension that was
-- never added. Asserting the occurrence count is the only way to distinguish
-- "the splice worked" from "the splice did nothing".
--
-- Each anchor must occur exactly once. More than once and REPLACE would insert
-- the same block several times; zero and it inserts nothing.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. Splice anchors in SC_ONTOLOGY_360.
--
-- Note the PART anchor carries no `PART as` alias. GET_DDL omits an alias that is
-- identical to the base table name, so the deployed text really is
-- `SUPPLY_CHAIN.RAW.PART primary key (MATERIAL_ID)`. Confirmed against this
-- account, not assumed.
-- ---------------------------------------------------------------------------

WITH d AS (SELECT GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360') AS ddl),
a AS (
  SELECT 'anchor: PART logical table'  AS check_name, REGEXP_COUNT(ddl, 'SUPPLY_CHAIN\\.RAW\\.PART primary key \\(MATERIAL_ID\\)') AS n FROM d
  UNION ALL SELECT 'anchor: PO_TO_PART relationship', REGEXP_COUNT(ddl, 'PO_TO_PART as PURCHASE_ORDER\\(MATERIAL_ID\\)') FROM d
  UNION ALL SELECT 'anchor: PART.MATERIAL dimension', REGEXP_COUNT(ddl, 'PART\\.MATERIAL as part\\.material_id') FROM d
)
SELECT check_name, n AS occurrences, 1 AS expected,
       IFF(n = 1, 'PASS', 'FAIL') AS verdict
FROM a ORDER BY check_name;

-- ---------------------------------------------------------------------------
-- 2. The CALENDAR dimension survived. Run this AFTER 01.
--
-- Guards the single most damaging ordering mistake in this directory: re-running
-- 00e after 01 reverts SC_ONTOLOGY_360 to 10 entities and removes CALENDAR, which
-- lib/period.ts needs for every reporting period. See sql/00_README.md.
-- ---------------------------------------------------------------------------

SELECT
  'SC_ONTOLOGY_360 has CALENDAR entity'                            AS check_name,
  COUNT(*)                                                         AS found,
  1                                                                AS expected,
  IFF(COUNT(*) = 1, 'PASS', 'FAIL - run 00e then 01, in that order') AS verdict
FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_TABLES
WHERE semantic_view_name = 'SC_ONTOLOGY_360' AND name = 'CALENDAR';

SELECT
  'CALENDAR classified as a conformed dimension'                    AS check_name,
  MAX(entity_role)                                                 AS found,
  'DIMENSION'                                                      AS expected,
  IFF(MAX(entity_role) = 'DIMENSION', 'PASS',
      'FAIL - the entity comment must contain the exact phrase "Conformed dimension."') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_ENTITY
WHERE semantic_view = 'SC_ONTOLOGY_360' AND entity = 'CALENDAR';

-- The count the /ontology stat tile renders. Asserted because the tile reading
-- zero against a populated catalogue is a silent self-contradiction, not an
-- error: five conformed dimensions (CALENDAR, PART, SUPPLIER, CUSTOMER, NODE)
-- and six facts.
SELECT
  'SC_ONTOLOGY_360 entity role split'                              AS check_name,
  COUNT_IF(entity_role = 'DIMENSION')                              AS dimensions,
  COUNT_IF(entity_role = 'FACT')                                   AS facts,
  IFF(COUNT_IF(entity_role = 'DIMENSION') = 5
      AND COUNT_IF(entity_role = 'FACT') = 6, 'PASS',
      'FAIL - /ontology will misreport its own entity counts') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.ONTOLOGY_ENTITY
WHERE semantic_view = 'SC_ONTOLOGY_360';

-- The calendar dimensions lib/period.ts filters on must exist by these names.
WITH need AS (
  SELECT * FROM VALUES ('CAL_DATE'),('CAL_MONTH'),('CAL_PERIOD'),('CAL_QUARTER'),('CAL_YEAR'),('IS_FUTURE'),('IS_WEEKDAY') AS v(name)
)
SELECT
  'CALENDAR dimension ' || need.name AS check_name,
  IFF(d.name IS NULL, 'missing', 'present') AS found,
  'present' AS expected,
  IFF(d.name IS NULL, 'FAIL', 'PASS') AS verdict
FROM need
LEFT JOIN SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_DIMENSIONS d
       ON d.semantic_view_name = 'SC_ONTOLOGY_360'
      AND d.table_name = 'CALENDAR'
      AND d.name = need.name
ORDER BY check_name;

-- ---------------------------------------------------------------------------
-- 3. Registry shape. Run AFTER 02 and 03.
--
-- 02 adds six columns to METRIC_DEFINITION and populates two of them; 03
-- populates the rest. If 00f had declared those columns itself, 02's
-- ADD COLUMN IF NOT EXISTS would no-op and the UPDATEs would be the only thing
-- doing real work -- so these checks are what prove 02 and 03 actually ran.
-- ---------------------------------------------------------------------------

SELECT 'metric count' AS check_name, COUNT(*) AS found, 14 AS expected,
       IFF(COUNT(*) = 14, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION;

SELECT 'every metric has an as_of_scope (02 ran)' AS check_name,
       COUNT_IF(as_of_scope IS NULL) AS found, 0 AS expected,
       IFF(COUNT_IF(as_of_scope IS NULL) = 0, 'PASS', 'FAIL - 02_as_of_rule.sql has not run') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION;

SELECT 'inventory metrics scoped SNAPSHOT' AS check_name,
       COUNT_IF(as_of_scope = 'SNAPSHOT') AS found, 2 AS expected,
       IFF(COUNT_IF(as_of_scope = 'SNAPSHOT') = 2, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION
WHERE grain = 'material_node_snapshot';

-- Eight metrics carry a target; the six absolute-dollar metrics deliberately do
-- not, because a fixed dollar threshold would report higher volume as a failure.
SELECT 'metrics with a target (03 ran)' AS check_name,
       COUNT_IF(target_value IS NOT NULL) AS found, 8 AS expected,
       IFF(COUNT_IF(target_value IS NOT NULL) = 8, 'PASS', 'FAIL - 03_targets.sql has not run') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION;

SELECT 'every target is labelled ILLUSTRATIVE or NO TARGET' AS check_name,
       COUNT_IF(target_source IS NULL) AS found, 0 AS expected,
       IFF(COUNT_IF(target_source IS NULL) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION;

-- ---------------------------------------------------------------------------
-- 4. Referential integrity between the registry and the exception rules.
--
-- app/api/drilldown/route.ts refuses a drill-down when
-- METRIC_EXCEPTION_RULE.canonical_fact disagrees with
-- METRIC_DEFINITION.canonical_fact, because rows from a different fact would not
-- add up to the number being explained. A mismatch here is a silent dead end in
-- the UI, so it is asserted rather than discovered by clicking.
-- ---------------------------------------------------------------------------

SELECT 'exception rules pointing at an unknown metric' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE r
WHERE NOT EXISTS (SELECT 1 FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d WHERE d.metric_id = r.metric_id);

SELECT 'exception rule fact disagrees with registry fact' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL - the drill-down will refuse these metrics') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE r
JOIN SUPPLY_CHAIN.GOVERNANCE.METRIC_DEFINITION d ON d.metric_id = r.metric_id
WHERE r.canonical_fact <> d.canonical_fact;

-- Every column an exception rule displays, orders by or dates on must really
-- exist on the fact. The route validates this at request time; asserting it here
-- turns a broken drill-down into a build failure instead of a user-facing one.
WITH cols AS (
  SELECT r.metric_id, r.canonical_fact,
         TRIM(c.value) AS col_name
  FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_EXCEPTION_RULE r,
       LATERAL SPLIT_TO_TABLE(r.display_columns || ',' || r.date_column, ',') c
)
SELECT 'exception display/date columns missing from the fact' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM cols
WHERE NOT EXISTS (
  SELECT 1 FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.COLUMNS ic
   WHERE ic.table_schema = SPLIT_PART(cols.canonical_fact, '.', 1)
     AND ic.table_name   = SPLIT_PART(cols.canonical_fact, '.', 2)
     AND ic.column_name  = UPPER(cols.col_name)
);

-- ---------------------------------------------------------------------------
-- 5. Bindings resolve to real semantic-view metrics.
--
-- A binding naming a metric the view does not expose fails only when the drift
-- test reaches it, which is a slow way to find a typo.
-- ---------------------------------------------------------------------------

SELECT 'bindings whose metric does not exist in the view' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING b
WHERE NOT EXISTS (
  SELECT 1 FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_METRICS m
   WHERE m.semantic_view_name = b.semantic_view
     AND m.table_name = UPPER(SPLIT_PART(b.metric_reference, '.', 1))
     AND m.name       = UPPER(SPLIT_PART(b.metric_reference, '.', 2))
);

-- A metric with a single binding has nothing to be compared against, so it can
-- never fail drift. It would show as verified while being untested.
SELECT 'metrics with fewer than 2 bindings' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL - these metrics are untestable for drift') AS verdict
FROM (
  SELECT metric_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_BINDING
   WHERE COALESCE(persona_role, '') <> 'NEGATIVE_CONTROL'
   GROUP BY metric_id HAVING COUNT(*) < 2
);

-- ---------------------------------------------------------------------------
-- 6. PERSONA_VIEW_ACCESS is consistent with the semantic layer.
--
-- The application reads this table to decide which views to offer a persona. A
-- row naming a view that does not exist makes /ask advertise a tool that fails at
-- run time, which reads to a user as the agent being broken rather than as a
-- configuration error.
--
-- WHAT THIS CHECKS AND WHAT IT DOES NOT. It asserts that every named view exists
-- and that the row count matches the 19 GRANT statements at the end of 00e. It
-- does NOT read the grants themselves: there is no INFORMATION_SCHEMA table
-- function for object privileges (an earlier version of this file called a
-- non-existent OBJECT_PRIVILEGES and failed), and SNOWFLAKE.ACCOUNT_USAGE.
-- GRANTS_TO_ROLES lags by up to two hours, so on a freshly rebuilt account it
-- would report an empty grant set and fail every row.
--
-- Functional proof that a persona can actually query its views is 91's job: it
-- assumes the roles and runs real queries through them.
-- ---------------------------------------------------------------------------

SELECT 'persona view access naming a non-existent semantic view' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL - /ask will offer a tool that cannot resolve') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_VIEW_ACCESS a
WHERE NOT EXISTS (
  SELECT 1 FROM SUPPLY_CHAIN.INFORMATION_SCHEMA.SEMANTIC_VIEWS v
   WHERE v.name = a.semantic_view
);

SELECT 'persona view access row count matches the grants in 00e' AS check_name,
       COUNT(*) AS found, 19 AS expected,
       IFF(COUNT(*) = 19, 'PASS', 'FAIL - PERSONA_VIEW_ACCESS and the GRANTs in 00e have diverged') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_VIEW_ACCESS;

-- The negative control must be reachable by no persona. It is bound in
-- METRIC_BINDING so the drift test reaches it with owner's rights; a human
-- persona able to query it could read a knowingly wrong number as though governed.
SELECT 'no persona can reach the defective control view' AS check_name,
       COUNT(*) AS found, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_VIEW_ACCESS
WHERE semantic_view = 'SC_SUPPLIER_LEGACY_DEFECT';

-- ---------------------------------------------------------------------------
-- 7. Verified queries are present on every view, in the expected number.
--
-- THIS IS THE CHECK THAT WOULD HAVE CAUGHT THE ORIGINAL LOSS. A previous build
-- added verified queries by splicing GET_DDL output with
--   REPLACE(ddl, 'ai_verified_queries (', ...)
-- which is a silent no-op against a view that has no such block yet. 37 of 38
-- queries vanished and nothing failed. They are now declared inline in
-- 00e_semantic.sql and 07b_prediction_objects.sql, and counted here.
--
-- GET_DDL requires constant arguments, so each view is named literally rather
-- than joined from a list.
--
-- Counting is not sufficient on its own: a verified query is stored metadata and
-- is never validated at create time, so sql/93_verify_verified_queries.sql
-- EXECUTES every one of them. Run both.
-- ---------------------------------------------------------------------------

WITH c AS (
  SELECT 'SC_ONTOLOGY_360'  AS view_name, 9 AS expected, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_ONTOLOGY_360'),  'QUESTION\\s+''', 1, 'i') AS found
  UNION ALL SELECT 'SC_SUPPLIER',      5, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER'),      'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_FULFILLMENT',   6, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT'),   'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_INVENTORY',     6, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_INVENTORY'),     'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_LANDED_COST',   5, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_LANDED_COST'),   'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_DEMAND',        3, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_DEMAND'),        'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_MANUFACTURING', 2, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_MANUFACTURING'), 'QUESTION\\s+''', 1, 'i')
  UNION ALL SELECT 'SC_OUTLOOK',       2, REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_OUTLOOK'),       'QUESTION\\s+''', 1, 'i')
)
SELECT 'verified queries on ' || view_name AS check_name, found, expected,
       IFF(found = expected, 'PASS', 'FAIL') AS verdict
FROM c
UNION ALL
SELECT 'verified queries, total', SUM(found), SUM(expected),
       IFF(SUM(found) = SUM(expected), 'PASS', 'FAIL') FROM c
ORDER BY check_name;

-- The negative control must carry none. A verified query on the deliberately
-- defective view would hand Cortex Analyst a knowingly wrong number as a
-- pre-approved answer.
SELECT
  'no verified query on the defective control view' AS check_name,
  REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT'), 'QUESTION\\s+''', 1, 'i') AS found,
  0 AS expected,
  IFF(REGEXP_COUNT(GET_DDL('SEMANTIC_VIEW','SUPPLY_CHAIN.SEMANTIC.SC_SUPPLIER_LEGACY_DEFECT'), 'QUESTION\\s+''', 1, 'i') = 0,
      'PASS', 'FAIL') AS verdict;

-- ---------------------------------------------------------------------------
-- 8. The agent exists, with the tools it is supposed to have.
--
-- lib/constants.ts renders SNOWFLAKE_INTELLIGENCE.AGENTS.SC_ONTOLOGIST_AGENT as
-- provenance on /ask. Before 10_agent.sql that name resolved to nothing, and the
-- page cited an object that did not exist.
-- ---------------------------------------------------------------------------

SHOW AGENTS IN SCHEMA SNOWFLAKE_INTELLIGENCE.AGENTS;

SELECT
  'Cortex Agent SC_ONTOLOGIST_AGENT exists' AS check_name,
  COUNT(*)                                  AS found,
  1                                         AS expected,
  IFF(COUNT(*) = 1, 'PASS', 'FAIL - 10_agent.sql has not run') AS verdict
FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
WHERE "name" = 'SC_ONTOLOGIST_AGENT';

-- ---------------------------------------------------------------------------
-- 9. THE DRIFT GATE. Run last.
--
-- All 14 metrics must PASS with zero spread. This is the only check that proves
-- the semantic views and the canonical facts agree, and therefore the only one
-- that proves a number in the UI means what the registry says it means.
--
-- Scope is all-history and unfiltered on purpose. See the procedure header in
-- 00f: this asks whether two definitions agree, not whether a reporting period is
-- correct.
-- ---------------------------------------------------------------------------

CALL SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_TEST();

WITH latest AS (
  SELECT run_id FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT
   QUALIFY ROW_NUMBER() OVER (ORDER BY run_at DESC) = 1
)
SELECT
  'DRIFT GATE: all metrics agree with their canonical fact' AS check_name,
  COUNT(*)                        AS metrics_checked,
  COUNT_IF(status = 'PASS')       AS passed,
  COUNT_IF(status <> 'PASS')      AS not_passed,
  MAX(relative_spread)            AS worst_relative_spread,
  IFF(COUNT(*) = 14 AND COUNT_IF(status <> 'PASS') = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_RESULT r
JOIN latest l ON l.run_id = r.run_id;

-- ---------------------------------------------------------------------------
-- 10. The negative control is still failing.
--
-- A drift test that has only ever passed is indistinguishable from one that is
-- not running. This asserts the control still diverges -- i.e. that somebody has
-- not "helpfully" fixed SC_SUPPLIER_LEGACY_DEFECT.
-- ---------------------------------------------------------------------------

SELECT
  'negative control still diverges' AS check_name,
  ROUND(MAX(value_spread), 6)       AS observed_spread,
  '> 0'                             AS expected,
  IFF(MAX(value_spread) > 0, 'PASS', 'FAIL - the defective view has been fixed; the control no longer proves anything') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_NEGATIVE_CONTROL;


-- ============================================================================
-- FILE: 91_verify_personas.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 91 — Persona and row-scope verification.
--
-- WHAT THIS PROVES, AND WHY IT IS THE HARDEST THING HERE TO PROVE
--
-- The claim is that SC_LOGISTICS and SC_LOGISTICS_EU share ONE metric definition
-- and differ only in the rows they can see. That claim is easy to assert and easy
-- to get wrong in a way nothing notices: if the row access policy silently fails
-- to attach, both roles return identical numbers and the demo still "works".
--
-- So the test is a comparison, not an inspection. Same view, same metric
-- reference, same period -- only the role changes. The EU figure must differ from
-- the all-region figure, and the EU row count must be strictly smaller.
--
-- WHY THE DESIGNED GAP IS 1.5 PERCENTAGE POINTS. It was originally 0.2pp, which
-- reproduced the gap this dataset historically showed. Measured over a single
-- month (~14k EU order lines, standard error ~0.3pp) the observed gap came out at
-- 0.01pp and its sign was not stable. An assertion that can pass or fail on
-- sampling noise proves nothing, so 00c widened the designed difference until it
-- sits unambiguously outside the noise. See the header of 00c.
--
-- Run this AFTER 00a-00f and 01. It only reads.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. The policy is attached to both outbound facts.
--
-- Checked first because every comparison below is meaningless if it is not. A
-- table may carry only one row access policy, which is why 00f issues
-- DROP ALL ROW ACCESS POLICIES before adding it.
-- ---------------------------------------------------------------------------

SELECT
  'row access policy attached to ' || ref_entity_name AS check_name,
  policy_name                                        AS found,
  'RAP_SHIP_REGION'                                  AS expected,
  IFF(policy_name = 'RAP_SHIP_REGION', 'PASS', 'FAIL') AS verdict
FROM TABLE(SUPPLY_CHAIN.INFORMATION_SCHEMA.POLICY_REFERENCES(
             REF_ENTITY_NAME => 'SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT',
             REF_ENTITY_DOMAIN => 'TABLE'))
WHERE policy_kind = 'ROW_ACCESS_POLICY'
UNION ALL
SELECT
  'row access policy attached to ' || ref_entity_name,
  policy_name,
  'RAP_SHIP_REGION',
  IFF(policy_name = 'RAP_SHIP_REGION', 'PASS', 'FAIL')
FROM TABLE(SUPPLY_CHAIN.INFORMATION_SCHEMA.POLICY_REFERENCES(
             REF_ENTITY_NAME => 'SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT',
             REF_ENTITY_DOMAIN => 'TABLE'))
WHERE policy_kind = 'ROW_ACCESS_POLICY';

-- ---------------------------------------------------------------------------
-- 2. The persona catalogue is internally consistent.
--
-- PERSONA_CATALOG derives view_count from PERSONA_VIEW_ACCESS, so the count on
-- screen cannot disagree with the list beside it. Asserted anyway, because the
-- view could be replaced by a table by someone tidying up.
-- ---------------------------------------------------------------------------

SELECT 'persona count' AS check_name, COUNT(*) AS found, 5 AS expected,
       IFF(COUNT(*) = 5, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_CATALOG;

SELECT
  role_name                                      AS check_name,
  view_count                                     AS found,
  ARRAY_SIZE(SPLIT(accessible_semantic_views, ', ')) AS expected,
  IFF(view_count = ARRAY_SIZE(SPLIT(accessible_semantic_views, ', ')), 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_CATALOG
ORDER BY role_name;

SELECT
  'SC_LOGISTICS_EU declares a restricted row scope' AS check_name,
  row_scope                                        AS found,
  'SHIP_REGION = EU'                               AS expected,
  IFF(row_scope = 'SHIP_REGION = EU', 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_CATALOG
WHERE role_name = 'SC_LOGISTICS_EU';

-- ROW_SCOPE IS MATCHED AS A STRING LITERAL BY THE APPLICATION.
--
-- app/api/consistency/route.ts:77 keeps only personas whose rowScope equals
-- exactly 'ALL REGIONS' when judging cross-persona agreement, because a
-- row-scoped persona legitimately returns a different number without the
-- definition having changed.
--
-- Seeding these as 'ALL_ROWS' instead -- which reads the same to a human, and
-- which no other assertion in this directory can see -- made zero personas
-- comparable. /consistency then observed no values at all and reported
-- supplier_otd_pct as UNPROVEN, on the single page whose purpose is to prove the
-- numbers agree. The smoke check caught it; nothing in SQL did. Hence this.
SELECT
  'unscoped personas use the exact literal the app matches on' AS check_name,
  COUNT_IF(row_scope = 'ALL REGIONS')                          AS found,
  4                                                            AS expected,
  IFF(COUNT_IF(row_scope = 'ALL REGIONS') = 4, 'PASS',
      'FAIL - /consistency will report every metric UNPROVEN') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_CATALOG;

-- Exactly one role is region-scoped. If PERSONA_REGION_SCOPE ever contained a
-- role that should be unrestricted, that role would see nothing at all, because
-- the policy's middle branch returns FALSE for a scoped role on a non-matching
-- region.
SELECT 'roles carrying a region scope' AS check_name,
       COUNT(DISTINCT role_name) AS found, 1 AS expected,
       IFF(COUNT(DISTINCT role_name) = 1, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.GOVERNANCE.PERSONA_REGION_SCOPE;

-- ---------------------------------------------------------------------------
-- 3. THE COMPARISON. One definition, two row scopes.
--
-- Run as each role in turn. The two OTD figures must differ and the EU line count
-- must be strictly smaller. Identical figures mean the policy is not filtering,
-- whatever the attachment check above says.
-- ---------------------------------------------------------------------------

USE ROLE SC_LOGISTICS;
USE WAREHOUSE COMPUTE_WH;

SELECT
  'SC_LOGISTICS  — Aug 2026 OTD, all regions'  AS scope,
  CURRENT_ROLE()                               AS role_in_effect,
  otd_pct                                      AS otd_aug_2026
FROM SEMANTIC_VIEW(
  SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT
  METRICS order_fulfillment.otd_pct
  WHERE order_fulfillment.delivery_date BETWEEN DATE '2026-08-01' AND DATE '2026-08-31'
);

SELECT
  'SC_LOGISTICS  — rows visible' AS scope,
  CURRENT_ROLE()                 AS role_in_effect,
  COUNT(*)                       AS visible_order_lines,
  COUNT(DISTINCT ship_region)    AS distinct_ship_regions
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT;

USE ROLE SC_LOGISTICS_EU;
USE WAREHOUSE COMPUTE_WH;

SELECT
  'SC_LOGISTICS_EU — Aug 2026 OTD, same definition' AS scope,
  CURRENT_ROLE()                                    AS role_in_effect,
  otd_pct                                           AS otd_aug_2026
FROM SEMANTIC_VIEW(
  SUPPLY_CHAIN.SEMANTIC.SC_FULFILLMENT
  METRICS order_fulfillment.otd_pct
  WHERE order_fulfillment.delivery_date BETWEEN DATE '2026-08-01' AND DATE '2026-08-31'
);

-- The strongest single assertion in this file: under the EU role, the only
-- ship_region visible anywhere in the fact is EU.
SELECT
  'SC_LOGISTICS_EU sees only EU rows' AS check_name,
  COUNT(DISTINCT ship_region)         AS distinct_ship_regions,
  1                                   AS expected,
  MAX(ship_region)                    AS only_region,
  IFF(COUNT(DISTINCT ship_region) = 1 AND MAX(ship_region) = 'EU', 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT;

SELECT
  'SC_LOGISTICS_EU sees only EU shipments' AS check_name,
  COUNT(DISTINCT ship_region)              AS distinct_ship_regions,
  1                                        AS expected,
  MAX(ship_region)                         AS only_region,
  IFF(COUNT(DISTINCT ship_region) = 1 AND MAX(ship_region) = 'EU', 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT;

USE ROLE ACCOUNTADMIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 4. The gap, computed in one statement.
--
-- Run with owner's rights so both populations are visible at once. This is the
-- number 00c was tuned to produce: an unambiguous difference, not a coin flip.
-- ---------------------------------------------------------------------------

WITH g AS (
  SELECT
    AVG(is_on_time)                                           AS otd_all,
    AVG(IFF(ship_region = 'EU', is_on_time, NULL))             AS otd_eu,
    COUNT(*)                                                  AS lines_all,
    COUNT_IF(ship_region = 'EU')                              AS lines_eu
  FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
  WHERE delivery_date BETWEEN DATE '2026-08-01' AND DATE '2026-08-31'
)
SELECT
  'EU row scope produces a distinguishable figure' AS check_name,
  ROUND(otd_all, 6)                                AS otd_all_regions,
  ROUND(otd_eu, 6)                                 AS otd_eu_only,
  ROUND(ABS(otd_eu - otd_all), 6)                  AS gap,
  lines_all, lines_eu,
  -- 0.003 is ten times the standard error of a single month's EU population, so
  -- clearing it cannot happen by chance.
  IFF(ABS(otd_eu - otd_all) > 0.003 AND lines_eu < lines_all, 'PASS',
      'FAIL - the gap is within sampling noise, so this proves nothing about row scoping') AS verdict
FROM g;


-- ============================================================================
-- FILE: 92_verify_counts.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 92 — Data-shape verification.
--
-- Asserts the properties the application, its tests and its narrative depend on.
-- Each of these has a specific failure mode attached, which is why it is checked
-- rather than trusted.
--
-- Read-only. Run after 00a-00f.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE WAREHOUSE COMPUTE_WH;

-- ---------------------------------------------------------------------------
-- 1. Row counts.
-- ---------------------------------------------------------------------------

WITH c AS (
  SELECT 'RAW.PO_RECEIPT_LINE'              AS object_name, COUNT(*) AS n, 420000  AS expected FROM SUPPLY_CHAIN.RAW.PO_RECEIPT_LINE
  UNION ALL SELECT 'RAW.SALES_ORDER_LINE',       COUNT(*), 1500000 FROM SUPPLY_CHAIN.RAW.SALES_ORDER_LINE
  UNION ALL SELECT 'RAW.SHIPMENT_COST',          COUNT(*), 1480499 FROM SUPPLY_CHAIN.RAW.SHIPMENT_COST
  UNION ALL SELECT 'RAW.INVENTORY_POSITION',     COUNT(*), 137088  FROM SUPPLY_CHAIN.RAW.INVENTORY_POSITION
  UNION ALL SELECT 'RAW.PRODUCTION_ORDER',       COUNT(*), 240000  FROM SUPPLY_CHAIN.RAW.PRODUCTION_ORDER
  UNION ALL SELECT 'RAW.DEMAND_FORECAST',        COUNT(*), 52000   FROM SUPPLY_CHAIN.RAW.DEMAND_FORECAST
  UNION ALL SELECT 'RAW.DATE_DIM',               COUNT(*), 1096    FROM SUPPLY_CHAIN.RAW.DATE_DIM
  UNION ALL SELECT 'RAW.PART',                   COUNT(*), 2000    FROM SUPPLY_CHAIN.RAW.PART
  UNION ALL SELECT 'RAW.SUPPLIER',               COUNT(*), 300     FROM SUPPLY_CHAIN.RAW.SUPPLIER
  UNION ALL SELECT 'RAW.CUSTOMER',               COUNT(*), 1200    FROM SUPPLY_CHAIN.RAW.CUSTOMER
  UNION ALL SELECT 'RAW.NODE',                   COUNT(*), 24      FROM SUPPLY_CHAIN.RAW.NODE
  UNION ALL SELECT 'RAW.CARRIER',                COUNT(*), 8       FROM SUPPLY_CHAIN.RAW.CARRIER
  UNION ALL SELECT 'RAW.LANE',                   COUNT(*), 96      FROM SUPPLY_CHAIN.RAW.LANE
  UNION ALL SELECT 'CANONICAL.FCT_SUPPLIER_DELIVERY_LINE',  COUNT(*), 420000  FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE
  UNION ALL SELECT 'CANONICAL.FCT_ORDER_LINE_FULFILLMENT',  COUNT(*), 1500000 FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
  UNION ALL SELECT 'CANONICAL.FCT_LANDED_COST_SHIPMENT',    COUNT(*), 1480499 FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT
  UNION ALL SELECT 'CANONICAL.FCT_INVENTORY_SNAPSHOT',      COUNT(*), 137088  FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT
  UNION ALL SELECT 'CANONICAL.FCT_REQUISITION_LINE',        COUNT(*), 420000  FROM SUPPLY_CHAIN.CANONICAL.FCT_REQUISITION_LINE
)
SELECT object_name, n AS found, expected, IFF(n = expected, 'PASS', 'FAIL') AS verdict
FROM c ORDER BY object_name;

-- ---------------------------------------------------------------------------
-- 2. Inventory snapshot cardinality. EXACTLY 24 MONTH-END DATES.
--
-- The most consequential shape assertion in this file. A snapshot is a balance,
-- not a flow. If daily snapshots were emitted instead of month-end ones, a
-- perfectly reasonable-looking SUM(inventory_value) over a quarter would return a
-- figure roughly ninety times the truth, and nothing in the UI would look wrong.
-- The 24 dates are what make "select the latest snapshot in the period" a
-- well-defined instruction.
-- ---------------------------------------------------------------------------

SELECT
  'distinct inventory snapshot dates' AS check_name,
  COUNT(DISTINCT snapshot_date)       AS found,
  24                                  AS expected,
  MIN(snapshot_date)::STRING          AS first_snapshot,
  MAX(snapshot_date)::STRING          AS last_snapshot,
  IFF(COUNT(DISTINCT snapshot_date) = 24
      AND MIN(snapshot_date) = DATE '2024-10-31'
      AND MAX(snapshot_date) = DATE '2026-09-30', 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT;

SELECT
  'every snapshot date is a month end' AS check_name,
  COUNT(*)                            AS non_month_end_dates,
  0                                   AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM (SELECT DISTINCT snapshot_date FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT)
WHERE snapshot_date <> LAST_DAY(snapshot_date);

-- The snapshot series must not run ahead into the future window that the receipt
-- and delivery facts deliberately occupy.
--
-- The bound is the end of the CURRENT month, not today. The last snapshot is
-- 2026-09-30 while today is 2026-09-20, so the current month's close is dated a
-- few days ahead -- and that is intended: 02_as_of_rule.sql states that inventory
-- snapshots stop at 2026-09-30 and therefore need no future-row exclusion, and the
-- 24-date contract depends on September being present.
--
-- An earlier version of this check used CURRENT_DATE() and failed all 5,712 rows
-- of the September close. That assertion was wrong, not the data: it would have
-- forced the series back to 23 dates, contradicting both 02 and the snapshot
-- cardinality check above. What genuinely must not happen is a snapshot in
-- October or November 2026, which would put a balance inside the future window.
SELECT
  'no inventory snapshot beyond the current month end' AS check_name,
  COUNT(*)                              AS found,
  0                                     AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT
WHERE snapshot_date > LAST_DAY(CURRENT_DATE());

-- Balanced panel: every material-node pair present at every snapshot. A ragged
-- panel would make a month-over-month comparison of days-of-inventory move for
-- reasons of coverage rather than of stock.
SELECT
  'inventory panel is balanced' AS check_name,
  COUNT(DISTINCT pairs)         AS distinct_pair_counts_per_date,
  1                             AS expected,
  IFF(COUNT(DISTINCT pairs) = 1, 'PASS', 'FAIL') AS verdict
FROM (
  SELECT snapshot_date, COUNT(*) AS pairs
  FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT
  GROUP BY snapshot_date
);

-- ---------------------------------------------------------------------------
-- 3. Date span and the future-dated share.
--
-- ~2.8% of receipt and delivery rows must fall after today. 02_as_of_rule.sql
-- records the rule that excludes them and scripts/probe-asof.mjs asserts the
-- effect is observable. If the share were zero the as-of rule would be untestable;
-- if it were the 8.4% a uniform spread produces, several recent months would read
-- as catastrophic failures rather than as incomplete periods.
--
-- Tolerance is 2.5%-3.1%, which is wide enough for hash-bucket granularity and
-- narrow enough to catch a switch to a uniform distribution.
-- ---------------------------------------------------------------------------

WITH f AS (
  SELECT
    MIN(receipt_date) AS lo, MAX(receipt_date) AS hi,
    AVG(IFF(receipt_date > DATE '2026-09-20', 1, 0)) AS future_share
  FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE
)
SELECT
  'inbound receipts: span and future share' AS check_name,
  lo::STRING AS first_event, hi::STRING AS last_event,
  ROUND(future_share, 5) AS future_share,
  IFF(lo = DATE '2024-10-03' AND hi = DATE '2026-11-25'
      AND future_share BETWEEN 0.025 AND 0.031, 'PASS', 'FAIL') AS verdict
FROM f;

WITH f AS (
  SELECT
    MIN(delivery_date) AS lo, MAX(delivery_date) AS hi,
    AVG(IFF(delivery_date > DATE '2026-09-20', 1, 0)) AS future_share
  FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
)
SELECT
  'outbound deliveries: span and future share' AS check_name,
  lo::STRING AS first_event, hi::STRING AS last_event,
  ROUND(future_share, 5) AS future_share,
  IFF(lo = DATE '2024-10-03' AND hi = DATE '2026-11-25'
      AND future_share BETWEEN 0.025 AND 0.031, 'PASS', 'FAIL') AS verdict
FROM f;

-- A future-dated row must never be recorded as late. A promise that has not come
-- due cannot have been missed, and treating it as a miss would be the single
-- largest source of a wrong number on the dashboard.
SELECT
  'no future-dated row is marked late' AS check_name,
  COUNT(*) AS found, 0 AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
WHERE delivery_date > DATE '2026-09-20' AND is_on_time = 0;

-- ---------------------------------------------------------------------------
-- 4. Flag hierarchy integrity.
--
-- IS_OTIF must equal IS_ON_TIME AND IS_IN_FULL, and IS_PERFECT_ORDER must equal
-- IS_OTIF AND IS_CDDA_MET. These are stored separately so that one table can serve
-- a different exception predicate per metric, and stored flags can disagree with
-- their own definitions -- which would make OTIF exceed OTD and turn the metric
-- hierarchy on the operations page into nonsense.
-- ---------------------------------------------------------------------------

SELECT 'IS_OTIF = ON_TIME AND IN_FULL' AS check_name,
       COUNT(*) AS violations, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
WHERE is_otif <> (is_on_time * is_in_full);

SELECT 'IS_PERFECT_ORDER = OTIF AND CDDA' AS check_name,
       COUNT(*) AS violations, 0 AS expected,
       IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
WHERE is_perfect_order <> (is_otif * is_cdda_met);

-- Ordering follows from the above, and is what the operations page displays.
WITH m AS (
  SELECT AVG(is_on_time) AS otd, AVG(is_in_full) AS fill,
         AVG(is_otif) AS otif, AVG(is_perfect_order) AS perfect
  FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT
)
SELECT 'perfect <= OTIF <= min(OTD, fill)' AS check_name,
       ROUND(otd,6) AS otd, ROUND(fill,6) AS fill_rate,
       ROUND(otif,6) AS otif, ROUND(perfect,6) AS perfect_order,
       IFF(perfect <= otif AND otif <= LEAST(otd, fill), 'PASS', 'FAIL') AS verdict
FROM m;

-- ---------------------------------------------------------------------------
-- 5. Every exception rule actually selects rows.
--
-- A predicate that matches nothing produces a drill-down that is permanently
-- empty: the metric looks explainable and is not. This already caught a real
-- defect -- days-of-inventory used a uniform cover distribution capped below 60
-- days while the rule selects positions above 60, so it matched zero of 137,088
-- rows. See the header of 00c.
-- ---------------------------------------------------------------------------

SELECT 'supplier_otd_pct exceptions'       AS rule_name, COUNT(*) AS exception_rows, IFF(COUNT(*) > 0,'PASS','FAIL') AS verdict FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE WHERE IS_ON_TIME = 0
UNION ALL SELECT 'supplier_fill_rate exceptions',  COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE WHERE RECEIVED_QTY < ORDERED_QTY
UNION ALL SELECT 'ppv exceptions',                 COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE WHERE EXTENDED_PRICE_VARIANCE > 0
UNION ALL SELECT 'otd_pct exceptions',             COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT WHERE IS_ON_TIME = 0
UNION ALL SELECT 'otif_pct exceptions',            COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT WHERE IS_OTIF = 0
UNION ALL SELECT 'fill_rate_pct exceptions',       COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT WHERE SHIPPED_QTY < ORDERED_QTY
UNION ALL SELECT 'perfect_order_pct exceptions',   COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT WHERE IS_PERFECT_ORDER = 0
UNION ALL SELECT 'freight_bill_variance exceptions',COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT WHERE FREIGHT_BILL_VAR_AMT > 0
UNION ALL SELECT 'landed_cost_per_unit exceptions', COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT WHERE SHIPPED_QTY > 0 AND TOTAL_LANDED_COST / SHIPPED_QTY > 15
UNION ALL SELECT 'days_of_inventory exceptions',   COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT WHERE AVG_DAILY_DEMAND > 0 AND ON_HAND_QTY / AVG_DAILY_DEMAND > 60
UNION ALL SELECT 'inventory_value_usd exceptions', COUNT(*), IFF(COUNT(*) > 0,'PASS','FAIL') FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT WHERE IS_STOCKED_OUT = 1 OR ON_HAND_QTY < SAFETY_STOCK
ORDER BY rule_name;

-- ---------------------------------------------------------------------------
-- 6. Metric values sit near their thresholds.
--
-- Not a correctness check -- a usefulness one. A target the data never approaches
-- leaves the red/amber/green logic in the application permanently untested and
-- silently broken. Each of these was tuned in 00c to land in the band that
-- exercises both the warn and the fail comparison.
-- ---------------------------------------------------------------------------

WITH v AS (
  SELECT
    (SELECT AVG(is_on_time) FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE) AS supplier_otd,
    (SELECT AVG(is_on_time) FROM SUPPLY_CHAIN.CANONICAL.FCT_ORDER_LINE_FULFILLMENT) AS otd,
    (SELECT SUM(total_landed_cost)/NULLIF(SUM(shipped_qty),0) FROM SUPPLY_CHAIN.CANONICAL.FCT_LANDED_COST_SHIPMENT) AS lcpu,
    (SELECT SUM(on_hand_qty)/NULLIF(SUM(avg_daily_demand),0) FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT
      WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM SUPPLY_CHAIN.CANONICAL.FCT_INVENTORY_SNAPSHOT)) AS doi,
    (SELECT SUM(extended_price_variance) FROM SUPPLY_CHAIN.CANONICAL.FCT_SUPPLIER_DELIVERY_LINE) AS ppv
)
SELECT 'supplier OTD between fail 0.85 and target 0.90' AS check_name, ROUND(supplier_otd,6) AS value,
       IFF(supplier_otd BETWEEN 0.85 AND 0.90, 'PASS','FAIL') AS verdict FROM v
UNION ALL
SELECT 'customer OTD below target 0.95', ROUND(otd,6),
       IFF(otd < 0.95, 'PASS','FAIL') FROM v
UNION ALL
SELECT 'landed cost per unit in the amber band (10.00-10.50)', ROUND(lcpu,4),
       IFF(lcpu BETWEEN 10.00 AND 10.50, 'PASS','FAIL') FROM v
UNION ALL
SELECT 'days of inventory in the amber band (30-35)', ROUND(doi,4),
       IFF(doi BETWEEN 30 AND 35, 'PASS','FAIL') FROM v
UNION ALL
SELECT 'PPV nets unfavourable (positive)', ROUND(ppv,2),
       IFF(ppv > 0, 'PASS','FAIL - the exception list is not worth chasing if the aggregate is favourable') FROM v;


-- ============================================================================
-- FILE: 93_verify_verified_queries.sql
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 93 — Execute every verified query.
--
-- WHY THIS IS NOT OPTIONAL. A verified query is stored as metadata and is NOT
-- validated when the semantic view is created. A broken one is therefore
-- invisible until Cortex Analyst picks it — and when it does, it uses it in
-- preference to deriving its own SQL, so a broken verified query is worse than no
-- verified query at all: it converts a question the agent could have answered
-- into a question the agent now fails.
--
-- This already caught a real defect. A verified query filtering on
-- `forecast.actual_units_total > 0` created cleanly and failed on execution with
--   "Requested semantic expression 'FORECAST.ACTUAL_UNITS_TOTAL' in WHERE clause
--    must be one of the following types: (DIMENSION, FACT)"
-- because that name is a METRIC, and a semantic-view WHERE accepts only a
-- dimension or a fact. Nothing else in this directory would have found it.
--
-- HOW. For each view, pull GET_DDL, extract every SQL '...' payload, run it, and
-- record the outcome. Results land in a real table rather than being printed, so a
-- failure can be inspected after the fact instead of re-derived from a log.
--
-- The extraction regex assumes no verified query contains an escaped single quote.
-- That holds by construction: the queries in 00e deliberately use no string
-- literals. The final assertion below fails loudly if the extracted count does not
-- match the declared count, which is what catches a regex that silently stopped
-- early.
-- ---------------------------------------------------------------------------

USE ROLE ACCOUNTADMIN;
USE DATABASE SUPPLY_CHAIN;
USE SCHEMA GOVERNANCE;
USE WAREHOUSE COMPUTE_WH;

CREATE OR REPLACE TABLE VERIFIED_QUERY_CHECK (
  checked_at    TIMESTAMP_LTZ,
  semantic_view STRING,
  query_index   NUMBER,
  status        STRING COMMENT 'PASS or FAIL.',
  rows_returned NUMBER,
  error         STRING,
  query_sql     STRING
) COMMENT = 'Execution result for every verified query declared on every semantic view. A verified query is stored metadata and is not validated at create time, so it has to be run to be trusted.';

DECLARE
  views   ARRAY := ARRAY_CONSTRUCT(
            'SC_ONTOLOGY_360', 'SC_SUPPLIER', 'SC_FULFILLMENT', 'SC_INVENTORY',
            'SC_LANDED_COST', 'SC_DEMAND', 'SC_MANUFACTURING', 'SC_OUTLOOK');
  v_name  STRING;
  v_ddl   STRING;
  v_q     STRING;
  v_i     NUMBER;
  v_n     NUMBER;
  v_at    TIMESTAMP_LTZ;
BEGIN
  v_at := CURRENT_TIMESTAMP();

  FOR j IN 0 TO ARRAY_SIZE(:views) - 1 DO
    v_name := GET(:views, j)::STRING;

    -- GET_DDL requires constant arguments, so the call is built as text rather
    -- than passed a bind. Passing :v_name directly fails with
    -- "constant arguments expected".
    LET ddl_stmt STRING := 'SELECT GET_DDL(''SEMANTIC_VIEW'', ''SUPPLY_CHAIN.SEMANTIC.' || v_name || ''')';
    LET dres RESULTSET := (EXECUTE IMMEDIATE :ddl_stmt);
    LET dcur CURSOR FOR dres;
    OPEN dcur;
    FETCH dcur INTO v_ddl;
    CLOSE dcur;

    v_i := 1;
    LOOP
      v_q := REGEXP_SUBSTR(v_ddl, 'SQL ''([^'']*)''', 1, v_i, 'e', 1);
      IF (v_q IS NULL) THEN
        BREAK;
      END IF;

      BEGIN
        LET qres RESULTSET := (EXECUTE IMMEDIATE :v_q);
        LET qcur CURSOR FOR qres;
        v_n := 0;
        FOR r IN qcur DO
          v_n := v_n + 1;
        END FOR;
        INSERT INTO SUPPLY_CHAIN.GOVERNANCE.VERIFIED_QUERY_CHECK
          (checked_at, semantic_view, query_index, status, rows_returned, error, query_sql)
        SELECT :v_at, :v_name, :v_i, 'PASS', :v_n, NULL, :v_q;
      EXCEPTION
        WHEN OTHER THEN
          INSERT INTO SUPPLY_CHAIN.GOVERNANCE.VERIFIED_QUERY_CHECK
            (checked_at, semantic_view, query_index, status, rows_returned, error, query_sql)
          SELECT :v_at, :v_name, :v_i, 'FAIL', NULL, SQLERRM, :v_q;
      END;

      v_i := v_i + 1;
    END LOOP;
  END FOR;

  RETURN 'verified queries executed';
END;

-- ---------------------------------------------------------------------------
-- Verdicts.
-- ---------------------------------------------------------------------------

SELECT
  semantic_view,
  COUNT(*)                   AS verified_queries,
  COUNT_IF(status = 'PASS')  AS passed,
  COUNT_IF(status = 'FAIL')  AS failed,
  IFF(COUNT_IF(status = 'FAIL') = 0, 'PASS', 'FAIL') AS verdict
FROM VERIFIED_QUERY_CHECK
GROUP BY semantic_view
ORDER BY semantic_view;

-- Any failure, with its error, so the cause is on screen and not in a log.
SELECT semantic_view, query_index, error, query_sql
FROM VERIFIED_QUERY_CHECK
WHERE status = 'FAIL'
ORDER BY semantic_view, query_index;

SELECT
  'ALL VERIFIED QUERIES EXECUTE' AS check_name,
  COUNT(*)                       AS total,
  COUNT_IF(status = 'FAIL')      AS failed,
  38                             AS expected_total,
  IFF(COUNT(*) = 38 AND COUNT_IF(status = 'FAIL') = 0, 'PASS',
      'FAIL - a stored verified query is broken, or the extraction found the wrong number') AS verdict
FROM VERIFIED_QUERY_CHECK;

-- A verified query that returns no rows is not an error, but it is a poor teaching
-- example: Analyst will reuse it and the user gets an empty answer.
SELECT
  'no verified query returns zero rows' AS check_name,
  COUNT(*)                             AS found,
  0                                    AS expected,
  IFF(COUNT(*) = 0, 'PASS', 'FAIL') AS verdict
FROM VERIFIED_QUERY_CHECK
WHERE status = 'PASS' AND COALESCE(rows_returned, 0) = 0;

GRANT SELECT ON TABLE VERIFIED_QUERY_CHECK TO ROLE SC_ONTOLOGY_STEWARD;

